// [FIX NVS-15, PLAN_NAPRAWY_NVS_KLUCZE_15_ZNAKOW.md, sekcja 7.1] Klucze NVS
// (Preferences/ESP-IDF) maja twardy limit 15 znakow — przekroczenie nie jest
// bledem kompilacji ani nawet widocznym bledem w logu (put*() po cichu
// zwraca 0, a domyslny Core Debug Level wycina log_e()), tylko cichym
// brakiem persystencji po restarcie. Ten bug wystapil juz DWUKROTNIE w tym
// pliku (mieszadloCzasOff, potem przy audycie jeszcze 3 kolejne klucze).
// Te wrappery lapia przekroczenie limitu W CZASIE KOMPILACJI przez
// static_assert na dlugosci literalu — uzywac zamiast config.putX/getX
// bezposrednio przy KAZDYM NOWYM polu ustawien od teraz. Migracja
// istniejacych wywolan config.putX/getX nie jest wymagana od razu.
template <size_t N>
inline size_t nvsPutUChar(Preferences& p, const char (&key)[N], uint8_t v) {
  static_assert(N - 1 <= 15, "Klucz NVS > 15 znakow (limit ESP-IDF) - skroc nazwe");
  return p.putUChar(key, v);
}
template <size_t N>
inline uint8_t nvsGetUChar(Preferences& p, const char (&key)[N], uint8_t def) {
  static_assert(N - 1 <= 15, "Klucz NVS > 15 znakow (limit ESP-IDF) - skroc nazwe");
  return p.getUChar(key, def);
}
template <size_t N>
inline size_t nvsPutBool(Preferences& p, const char (&key)[N], bool v) {
  static_assert(N - 1 <= 15, "Klucz NVS > 15 znakow (limit ESP-IDF) - skroc nazwe");
  return p.putBool(key, v);
}
template <size_t N>
inline bool nvsGetBool(Preferences& p, const char (&key)[N], bool def) {
  static_assert(N - 1 <= 15, "Klucz NVS > 15 znakow (limit ESP-IDF) - skroc nazwe");
  return p.getBool(key, def);
}
template <size_t N>
inline size_t nvsPutInt(Preferences& p, const char (&key)[N], int32_t v) {
  static_assert(N - 1 <= 15, "Klucz NVS > 15 znakow (limit ESP-IDF) - skroc nazwe");
  return p.putInt(key, v);
}
template <size_t N>
inline int32_t nvsGetInt(Preferences& p, const char (&key)[N], int32_t def) {
  static_assert(N - 1 <= 15, "Klucz NVS > 15 znakow (limit ESP-IDF) - skroc nazwe");
  return p.getInt(key, def);
}
template <size_t N>
inline size_t nvsPutUInt(Preferences& p, const char (&key)[N], uint32_t v) {
  static_assert(N - 1 <= 15, "Klucz NVS > 15 znakow (limit ESP-IDF) - skroc nazwe");
  return p.putUInt(key, v);
}
template <size_t N>
inline uint32_t nvsGetUInt(Preferences& p, const char (&key)[N], uint32_t def) {
  static_assert(N - 1 <= 15, "Klucz NVS > 15 znakow (limit ESP-IDF) - skroc nazwe");
  return p.getUInt(key, def);
}
