// ════════════════════════════════════════════════════════
// [FB-ETAP2B] Circuit breaker — TYLKO dla Firebase (Telegram ma dzis prosty
// staly interwal bez wlasnego breakera — plan sekcja 3.2 mowi wprost o
// OSOBNYCH streakach na usluge, zeby awaria jednej nie blokowala drugiej;
// tu jest tylko Firebase, bo tylko Firebase ma dzis funkcje sieciowa do
// zabezpieczenia). Wzorzec 1:1 Ryby (_netFailStreak/_netCircuitOpen/
// _netCooldownUntilMs/_netBackoffMs, ~linia 4224), nazwy z prefiksem fb_
// zeby bylo jasne ze to nie dzieli stanu z ewentualnym przyszlym TG breakerem.
// ════════════════════════════════════════════════════════
volatile uint8_t  fbNetFailStreak      = 0;       // ile kolejnych TIMEOUT/ERROR z rzedu
volatile bool     fbNetCircuitOpen     = false;    // true = circuit open, pomin wysylke
volatile uint32_t fbNetCooldownUntilMs = 0;        // millis() kiedy wolno probowac ponownie
volatile uint32_t fbNetBackoffMs       = 30000UL;  // aktualny backoff (30s -> 60s -> 120s, sufit 120s)

static const uint8_t  FB_NET_FAIL_THRESHOLD  = 2;       // streak, ktory otwiera circuit
static const uint32_t FB_NET_BACKOFF_INIT_MS = 30000UL; // pierwszy cooldown: 30s
static const uint32_t FB_NET_BACKOFF_MAX_MS  = 120000UL; // sufit: 120s (2 min)

// [FB-ETAP2B] Wywolywac na koncu KAZDEJ sciezki TIMEOUT/ERROR w funkcjach
// Firebase (dzis tylko sendStatusToFirebase(), ETAP 3 doda kolejne).
// [FIX-FB-CB-COOLDOWN-LOG, 2026-09-09] BYLO: "cooldown=%lus" liczone jako
// (fbNetCooldownUntilMs / 1000UL) — to jest ZNACZNIK CZASU millis() w
// sekundach (czyli rosnie z uptime urzadzenia), NIE dlugosc oczekiwania!
// Potwierdzone w logu z urzadzenia: przy stalym "backoff=30s" pole
// "cooldown=" pokazywalo 149s, 229s, 895s, 3218s w kolejnych, niezaleznych
// epizodach — mylaco sugerujac wielominutowe oczekiwanie, podczas gdy
// polaczenie realnie wracalo do half_open po ~15-30s (zgodnie z backoff=).
// NAPRAWA: drukujemy REALNY czas do odblokowania (rowny fbNetBackoffMs w
// momencie otwarcia), ten sam wzorzec co "cooldown=pozostaly=Xs" w logach
// skip_*.
#define FB_NET_FAIL() do { \
  fbNetFailStreak = (uint8_t)(fbNetFailStreak + 1); \
  if (fbNetFailStreak >= FB_NET_FAIL_THRESHOLD && !fbNetCircuitOpen) { \
    fbNetCircuitOpen     = true; \
    fbNetCooldownUntilMs = millis() + fbNetBackoffMs; \
    char _fbCbBuf[96]; \
    snprintf(_fbCbBuf, sizeof(_fbCbBuf), "tag=FB-CB lvl=WARN zdarzenie=open streak=%d backoff=%lus cooldown=%lus", \
             (int)fbNetFailStreak, \
             (unsigned long)(fbNetBackoffMs / 1000UL), \
             (unsigned long)(fbNetBackoffMs / 1000UL)); \
    zapiszLog(String(_fbCbBuf)); \
    fbNetBackoffMs = min(fbNetBackoffMs * 2, FB_NET_BACKOFF_MAX_MS); \
  } \
} while(0)

// [FB-ETAP2B] Wywolywac po kazdym sukcesie wysylki — zeruje streak, zamyka
// circuit, resetuje backoff do wartosci startowej (30s, nie zostaje "na
// stale" podwyzszony po jednym udanym polaczeniu — wzorem Ryby).
#define FB_NET_SUCCESS() do { \
  if (fbNetFailStreak > 0 || fbNetCircuitOpen) { \
    char _fbCbBuf[64]; \
    snprintf(_fbCbBuf, sizeof(_fbCbBuf), "tag=FB-CB lvl=INFO zdarzenie=reset streak_byl=%d", (int)fbNetFailStreak); \
    zapiszLog(String(_fbCbBuf)); \
  } \
  fbNetFailStreak  = 0; \
  fbNetCircuitOpen = false; \
  fbNetBackoffMs   = FB_NET_BACKOFF_INIT_MS; \
} while(0)

// ════════════════════════════════════════════════════════
// [AUDYT-PKT4, Krok 4a] Circuit breaker dla Telegrama — osobny od FB,
// 1:1 wzorem powyzszego fbNetFailStreak/fbNetCircuitOpen/FB_NET_FAIL()/
// FB_NET_SUCCESS(). Zgodnie z Opcja A z audytu (sekcja 4): oddzielny streak
// per usluga, zeby awaria jednej (np. Telegram API ma gorszy dzien) nie
// "zamykala" ruchu do drugiej (Firebase), ktora moze dzialac normalnie —
// to standardowa zasada izolacji (bulkhead) we wzorcu circuit breaker.
//
// UWAGA (Krok 4a — TYLKO DEKLARACJA): ponizsze zmienne/makra nie sa jeszcze
// wolane z zadnego miejsca w pliku — zero zmiany zachowania w tym kroku.
// Podpiecie do tgPostJson()/tgEnsureConnected() (TG_NET_FAIL() w sciezkach
// bledow) oraz bramka "pomin wysylke gdy circuit open" (analogicznie do
// linii ~5663/5868 dla FB) to Krok 4b, celowo osobna partia.
// ════════════════════════════════════════════════════════
volatile uint8_t  tgNetFailStreak      = 0;       // ile kolejnych TIMEOUT/ERROR z rzedu (TG)
volatile bool     tgNetCircuitOpen     = false;    // true = circuit open, pomin wysylke TG
volatile uint32_t tgNetCooldownUntilMs = 0;        // millis() kiedy wolno probowac ponownie (TG)
volatile uint32_t tgNetBackoffMs       = 30000UL;  // aktualny backoff TG (30s -> 60s -> 120s, sufit 120s)

static const uint8_t  TG_NET_FAIL_THRESHOLD  = 2;       // streak, ktory otwiera circuit (TG)
static const uint32_t TG_NET_BACKOFF_INIT_MS = 30000UL; // pierwszy cooldown: 30s (TG)
static const uint32_t TG_NET_BACKOFF_MAX_MS  = 120000UL; // sufit: 120s (2 min) (TG)

// [AUDYT-PKT4] Wywolywac na koncu KAZDEJ sciezki TIMEOUT/ERROR w funkcjach
// Telegrama (Krok 4b: tgEnsureConnected()/tgPostJson()).
#define TG_NET_FAIL() do { \
  tgNetFailStreak = (uint8_t)(tgNetFailStreak + 1); \
  if (tgNetFailStreak >= TG_NET_FAIL_THRESHOLD && !tgNetCircuitOpen) { \
    tgNetCircuitOpen     = true; \
    tgNetCooldownUntilMs = millis() + tgNetBackoffMs; \
    char _tgCbBuf[96]; \
    snprintf(_tgCbBuf, sizeof(_tgCbBuf), "tag=TG-CB lvl=WARN zdarzenie=open streak=%d backoff=%lus cooldown=%lus", \
             (int)tgNetFailStreak, \
             (unsigned long)(tgNetBackoffMs / 1000UL), \
             (unsigned long)(tgNetCooldownUntilMs / 1000UL)); \
    zapiszLog(String(_tgCbBuf)); \
    tgNetBackoffMs = min(tgNetBackoffMs * 2, TG_NET_BACKOFF_MAX_MS); \
  } \
} while(0)

// [AUDYT-PKT4] Wywolywac po kazdym sukcesie wysylki/polaczenia TG — zeruje
// streak, zamyka circuit, resetuje backoff do wartosci startowej.
#define TG_NET_SUCCESS() do { \
  if (tgNetFailStreak > 0 || tgNetCircuitOpen) { \
    char _tgCbBuf[64]; \
    snprintf(_tgCbBuf, sizeof(_tgCbBuf), "tag=TG-CB lvl=INFO zdarzenie=reset streak_byl=%d", (int)tgNetFailStreak); \
    zapiszLog(String(_tgCbBuf)); \
  } \
  tgNetFailStreak  = 0; \
  tgNetCircuitOpen = false; \
  tgNetBackoffMs   = TG_NET_BACKOFF_INIT_MS; \
} while(0)

