// [COMMIT-B] SPSC TelemetryRing: producer = historiaZapiszProbke() / Core 1,
// consumer = przyszly drain telemetryczny. Bufor danych jest w PSRAM;
// head/tail pozostaja w zwyklym RAM i sa publikowane atomowo acquire/release.
// Monotoniczne liczniki modulo uint32_t pozwalaja wykorzystac cala pojemnosc
// bez sztucznego "jednego pustego slotu". Nie ma mutexa, malloc/free podczas
// push/pop ani operacji sieciowych.
static constexpr uint32_t TELEMETRY_RING_CAPACITY = 1440U;

class TelemetryRing {
public:
  bool init() {
    if (m_buffer) return true;
    const size_t bytes = sizeof(TelemetrySample) * TELEMETRY_RING_CAPACITY;
    m_buffer = static_cast<TelemetrySample *>(ps_malloc(bytes));
    if (!m_buffer) {
      DLOGF(DC_TELEMETRY, DL_ERR, "zdarzenie=ring_alloc_fail bytes=%u", (unsigned)bytes);
      return false;
    }
    __atomic_store_n(&m_head, 0U, __ATOMIC_RELAXED);
    __atomic_store_n(&m_tail, 0U, __ATOMIC_RELAXED);
    DLOGF(DC_TELEMETRY, DL_INFO, "zdarzenie=ring_ready capacity=%u bytes=%u psram=1",
          (unsigned)TELEMETRY_RING_CAPACITY, (unsigned)bytes);
    return true;
  }

  bool ready() const { return m_buffer != nullptr; }

  bool push(const TelemetrySample &sample) {
    TelemetrySample *buffer = m_buffer;
    if (!buffer) return false;

    const uint32_t head = __atomic_load_n(&m_head, __ATOMIC_RELAXED);
    const uint32_t tail = __atomic_load_n(&m_tail, __ATOMIC_ACQUIRE);
    if ((uint32_t)(head - tail) >= TELEMETRY_RING_CAPACITY) return false;

    buffer[head % TELEMETRY_RING_CAPACITY] = sample;
    __atomic_store_n(&m_head, head + 1U, __ATOMIC_RELEASE);
    return true;
  }

  bool peek(TelemetrySample &out) const {
    return peekAt(0U, out);
  }

  bool peekAt(uint32_t offset, TelemetrySample &out) const {
    TelemetrySample *buffer = m_buffer;
    if (!buffer || offset >= TELEMETRY_RING_CAPACITY) return false;

    const uint32_t tail = __atomic_load_n(&m_tail, __ATOMIC_RELAXED);
    const uint32_t head = __atomic_load_n(&m_head, __ATOMIC_ACQUIRE);
    const uint32_t used = head - tail;
    if (offset >= used) return false;

    out = buffer[(tail + offset) % TELEMETRY_RING_CAPACITY];
    return true;
  }

  bool commitPop() { return commitPopN(1U); }

  bool commitPopN(uint32_t count) {
    if (!m_buffer || count == 0U || count > TELEMETRY_RING_CAPACITY) return false;
    const uint32_t tail = __atomic_load_n(&m_tail, __ATOMIC_RELAXED);
    const uint32_t head = __atomic_load_n(&m_head, __ATOMIC_ACQUIRE);
    if ((uint32_t)(head - tail) < count) return false;
    __atomic_store_n(&m_tail, tail + count, __ATOMIC_RELEASE);
    return true;
  }

  uint32_t size() const {
    const uint32_t head = __atomic_load_n(&m_head, __ATOMIC_ACQUIRE);
    const uint32_t tail = __atomic_load_n(&m_tail, __ATOMIC_ACQUIRE);
    const uint32_t used = head - tail;
    return used <= TELEMETRY_RING_CAPACITY ? used : TELEMETRY_RING_CAPACITY;
  }

  uint32_t capacity() const { return TELEMETRY_RING_CAPACITY; }
  size_t bytes() const { return sizeof(TelemetrySample) * TELEMETRY_RING_CAPACITY; }

private:
  TelemetrySample *m_buffer = nullptr;
  volatile uint32_t m_head = 0;
  volatile uint32_t m_tail = 0;
};

static_assert(sizeof(TelemetrySample) * TELEMETRY_RING_CAPACITY == 115200U,
              "TelemetryRing budget changed: expected 115200 B");

// [R242] Persistent Spool V2 — read-only page benchmark.
// Rekord spool = pelny TelemetrySample + CRC32 rekordu.
static constexpr size_t SPOOL_RECORD_BYTES = sizeof(TelemetrySample) + 4U;
static constexpr size_t SPOOL_HEADER_BYTES = 64U;
static constexpr size_t SPOOL_FOOTER_BYTES = 64U;
static constexpr size_t SPOOL_META_BYTES = SPOOL_HEADER_BYTES + SPOOL_FOOTER_BYTES;
static constexpr size_t SPOOL_PAGE_32K = 32UL * 1024UL;
static constexpr size_t SPOOL_PAGE_48K = 48UL * 1024UL;
static constexpr size_t SPOOL_PAGE_64K = 64UL * 1024UL;
static constexpr uint32_t SPOOL_64K_SAFE_RECORDS = 768U;

static constexpr uint32_t spoolMaxRecordsForPage(size_t pageBytes) {
  if (pageBytes <= SPOOL_META_BYTES) return 0U;
  return (uint32_t)((pageBytes - SPOOL_META_BYTES) / SPOOL_RECORD_BYTES);
}

static constexpr size_t spoolUsedBytes(size_t pageBytes, uint32_t records) {
  return SPOOL_META_BYTES + ((size_t)records * SPOOL_RECORD_BYTES);
}

static_assert(SPOOL_RECORD_BYTES == 84U, "Spool record benchmark expects 84 B");
static_assert(spoolMaxRecordsForPage(SPOOL_PAGE_32K) == 388U, "32 KiB page benchmark changed");
static_assert(spoolMaxRecordsForPage(SPOOL_PAGE_48K) == 583U, "48 KiB page benchmark changed");
static_assert(spoolMaxRecordsForPage(SPOOL_PAGE_64K) == 778U, "64 KiB page benchmark changed");
static_assert(spoolUsedBytes(SPOOL_PAGE_64K, SPOOL_64K_SAFE_RECORDS) == 64640U,
              "64 KiB safe page budget changed");

// [R244] Frozen Persistent Spool V2 application ABI.
// Page layout (exact): HEADER 64 B + 768 x RECORD(80 B sample + 4 B CRC32) + FOOTER 64 B.
// A partially written last record is invalid when its record CRC does not match.
// Footer is the close/commit marker; no footer => page remains recoverable as an open page.
static constexpr uint32_t SPOOL_PAGE_MAGIC = 0x53504C31UL; // ASCII-ish: SPL1
static constexpr uint16_t SPOOL_PAGE_FORMAT_VERSION = 1U;
static constexpr uint16_t SPOOL_PAGE_HEADER_VERSIONED_BYTES = 64U;
static constexpr uint16_t SPOOL_PAGE_FOOTER_VERSIONED_BYTES = 64U;
static constexpr uint32_t SPOOL_PAGE_COMMIT_MARKER = 0x434F4D4DUL; // COM M

#pragma pack(push, 1)
struct SpoolPageHeader {
  uint32_t magic;
  uint16_t formatVersion;
  uint16_t headerBytes;
  uint64_t pageSeq;
  uint64_t firstSampleSeq;
  uint16_t recordBytes;
  uint16_t capacity;
  uint32_t flags;
  uint32_t firstUnixTs;
  uint32_t firstMonoMs;
  uint8_t  reserved[20];
  uint32_t headerCrc32;
};

struct SpoolPageFooter {
  uint32_t magic;
  uint16_t formatVersion;
  uint16_t footerBytes;
  uint64_t pageSeq;
  uint64_t firstSampleSeq;
  uint64_t lastSampleSeq;
  uint32_t recordCount;
  uint32_t payloadCrc32;
  uint32_t commitMarker;
  uint8_t  reserved[16];
  uint32_t footerCrc32;
};
#pragma pack(pop)

static_assert(sizeof(SpoolPageHeader) == SPOOL_HEADER_BYTES,
              "SpoolPageHeader ABI changed: expected 64 B");
// [BUILD FIX] Helpery R245 sa zdefiniowane nizej, ale sa uzywane przez R252/R253-R262.
static uint32_t spoolR245Crc32(const uint8_t *data, size_t len);
static uint32_t spoolR245HeaderCrc(const SpoolPageHeader &src);
static uint32_t spoolR245FooterCrc(const SpoolPageFooter &src);
static bool spoolR245BuildSample(uint32_t i, TelemetrySample &s);

static_assert(sizeof(SpoolPageFooter) == SPOOL_FOOTER_BYTES,
              "SpoolPageFooter ABI changed: expected 64 B");
static_assert(offsetof(SpoolPageHeader, headerCrc32) == 60U,
              "SpoolPageHeader CRC offset changed");
static_assert(offsetof(SpoolPageFooter, payloadCrc32) == 36U,
              "SpoolPageFooter payload CRC offset changed");
static_assert(offsetof(SpoolPageFooter, commitMarker) == 40U,
              "SpoolPageFooter commit marker offset changed");
static_assert(offsetof(SpoolPageFooter, footerCrc32) == 60U,
              "SpoolPageFooter CRC offset changed");
static_assert(SPOOL_PAGE_HEADER_VERSIONED_BYTES == sizeof(SpoolPageHeader),
              "Header size constant changed");
static_assert(SPOOL_PAGE_FOOTER_VERSIONED_BYTES == sizeof(SpoolPageFooter),
              "Footer size constant changed");
static_assert(SPOOL_PAGE_64K == SPOOL_META_BYTES + (SPOOL_64K_SAFE_RECORDS * SPOOL_RECORD_BYTES) + 896U,
              "64 KiB safe page geometry changed");

