// ── SERWA — ZAMIENNIK ESP32Servo (bez zaleznosci od biblioteki, ktora
// wisi w attach() na S3) — bezposrednio na rdzeniowym API ledcAttach()/
// ledcWrite(). Udaje minimalne API biblioteki (attach/write/read), zeby
// kod sterujacy serwami (zlecServoRuch()/serwoTick(), CZESC 21) nie
// wymagal zmian poza typem parametru. ───────────
#define SERVO_FREQ_HZ    50
#define SERVO_RES_BITS   14                          // limit rdzenia S3 (IDF5)
#define SERVO_MAX_DUTY   ((1UL << SERVO_RES_BITS) - 1)
#define SERVO_MIN_US     544                          // domyslny zakres, jak w ESP32Servo
#define SERVO_MAX_US     2400
#define SERVO_PERIOD_US  (1000000UL / SERVO_FREQ_HZ)  // 20000us @ 50Hz

struct RawServo {
  uint8_t pin = 255;

  void attach(uint8_t p) {
    pin = p;
    if (!ledcAttach(pin, SERVO_FREQ_HZ, SERVO_RES_BITS)) {
      DLOGF(DC_SERVO, DL_ERR, "zdarzenie=ledcattach_blad pin=%u", (unsigned)pin);
    }
  }
  void write(int kat) {
    kat = constrain(kat, 0, 180);
    uint32_t pulseUs = map(kat, 0, 180, SERVO_MIN_US, SERVO_MAX_US);
    uint32_t duty = (uint32_t)((uint64_t)pulseUs * (SERVO_MAX_DUTY + 1) / SERVO_PERIOD_US);
    ledcWrite(pin, duty);
  }
};

RawServo serwoKlapa, serwoSyberek;

