static bool spoolR277FieldsByteExact(String &why) {
  if (!spoolR252ArmTelemetryMirror(why)) return false;
  TelemetrySample s[3]{};
  if (!spoolR273MakeTelemetrySamples(s, why)) { __atomic_store_n(&g_spoolR252MirrorArmed, false, __ATOMIC_RELEASE); return false; }
  s[0].qualityBits = 0xA5A55A5AUL;
  s[0].simulatedBits = 0x0555U;
  for (uint8_t i = 0; i < TELEMETRY_CH_COUNT; ++i) s[0].ageS[i] = (uint16_t)(100U + i);
  spoolR252MirrorOnTelemetrySample(s[0]);
  spoolR252MirrorOnTelemetrySample(s[1]);
  spoolR252MirrorOnTelemetrySample(s[2]);

  File f = LittleFS.open(SPOOL_R252_TEST_FILE, "r");
  if (!f) { why = "open mirror FAIL"; return false; }
  if (!f.seek(SPOOL_HEADER_BYTES)) { f.close(); why = "seek header FAIL"; return false; }
  uint8_t rec[SPOOL_RECORD_BYTES] = {};
  if (f.readBytes(reinterpret_cast<char*>(rec), sizeof(rec)) != (int)sizeof(rec)) { f.close(); why = "read record FAIL"; return false; }
  f.close();
  uint32_t storedCrc = 0U;
  memcpy(&storedCrc, rec + sizeof(TelemetrySample), sizeof(storedCrc));
  const uint32_t calcCrc = spoolR245Crc32(rec, sizeof(TelemetrySample));
  const bool bytesOk = memcmp(rec, &s[0], sizeof(TelemetrySample)) == 0 && storedCrc == calcCrc;
  why = "qualityBits=0xA5A55A5A simulatedBits=0x0555 ageS=100..110 byteExact=" + String(bytesOk ? "YES" : "NO");
  return bytesOk;
}

static bool spoolR278CountersUnchanged(String &why) {
  if (g_telemetryLastSnapshot.sampleSeq == 0U) { why = "brak snapshotu"; return false; }
  if (!g_telemetryCountersMutex) { why = "counterMutex=NOT_READY"; return false; }
  // R278 sprawdza wylacznie kontrakt adaptera. Normalny producent telemetryki
  // moze rownoczesnie pracowac na drugim rdzeniu, dlatego synchronizujemy
  // tylko same countery. Nie trzymamy sekcji krytycznej podczas LittleFS.
  xSemaphoreTake(g_telemetryCountersMutex, portMAX_DELAY);
  const uint32_t produced = g_telemetrySamplesProduced;
  const uint32_t dropped = g_telemetrySamplesDropped;
  const uint32_t sent = g_telemetrySamplesSent;
  const uint32_t transport = g_telemetryTransportFailures;
  const bool armed = spoolR252ArmTelemetryMirror(why);
  bool same = false;
  if (armed) {
    TelemetrySample s[3]{};
    if (spoolR273MakeTelemetrySamples(s, why)) {
      for (uint32_t i = 0; i < 3U; ++i) spoolR252MirrorOnTelemetrySample(s[i]);
      same = produced == g_telemetrySamplesProduced &&
             dropped == g_telemetrySamplesDropped &&
             sent == g_telemetrySamplesSent &&
             transport == g_telemetryTransportFailures;
      why = "produced=" + String((unsigned long)g_telemetrySamplesProduced) +
            " dropped=" + String((unsigned long)g_telemetrySamplesDropped) +
            " sent=" + String((unsigned long)g_telemetrySamplesSent) +
            " transportErrors=" + String((unsigned long)g_telemetryTransportFailures) +
            " unchanged=" + String(same ? "YES" : "NO");
    } else {
      __atomic_store_n(&g_spoolR252MirrorArmed, false, __ATOMIC_RELEASE);
    }
  }
  xSemaphoreGive(g_telemetryCountersMutex);
  return armed && same;
}

