// ============================================================================
// [R301-R312 LOCAL] Persistent Spool V2 — REPLAY / ACK / DELETE / FAULT BATCH.
// Test-only local harness. Nie wykonuje realnego ruchu Firebase.
// Modeluje kontrakt replay: oldest-first, max 10 rekordow/request,
// cursor advance dopiero po pelnym ACK batchu, delete strony dopiero po
// pelnym ACK calej strony, restart => at-least-once + stabilne record ID.
// ============================================================================
static constexpr char SPOOL_REPLAY_TEST_DIR[] = "/telemetry_spool";

struct SpoolReplayPageModel {
  const char* path;
  uint64_t pageSeq;
  uint32_t firstSeq;
  uint32_t records;
};

static bool spoolReplayEnsureDir() {
  if (!littlefsReady) return false;
  if (LittleFS.exists(SPOOL_REPLAY_TEST_DIR)) return true;
  return LittleFS.mkdir(SPOOL_REPLAY_TEST_DIR);
}

static bool spoolReplayWritePage(const char* path, uint64_t pageSeq, uint32_t firstSeq, uint32_t records) {
  spoolBatchRemove(path);
  if (!spoolReplayEnsureDir()) return false;
  return spoolBatchWriteCommittedPage(path, pageSeq, firstSeq, records, false, false, false, false);
}

static bool spoolReplayReadRecord(const char* path, uint32_t index, TelemetrySample& sample, String& recordId) {
  sample = {};
  recordId = "";
  File f = LittleFS.open(path, "r");
  if (!f) return false;
  const size_t off = SPOOL_HEADER_BYTES + (size_t)index * SPOOL_RECORD_BYTES;
  if (!f.seek(off)) { f.close(); return false; }
  uint8_t rec[SPOOL_RECORD_BYTES] = {};
  if (f.read(rec, sizeof(rec)) != sizeof(rec)) { f.close(); return false; }
  f.close();
  uint32_t storedCrc = 0U;
  memcpy(&sample, rec, sizeof(sample));
  memcpy(&storedCrc, rec + sizeof(sample), sizeof(storedCrc));
  const uint32_t calcCrc = spoolR245Crc32(rec, sizeof(sample));
  if (sample.sampleSeq == 0U || storedCrc != calcCrc) return false;
  char id[64] = {};
  telemetryFormatRecordId(sample, id, sizeof(id));
  recordId = String(id);
  return true;
}

static bool spoolReplayScanPage(const char* path, SpoolBatchScan& scan) {
  return spoolBatchScan(path, scan) && scan.footerOk && scan.validRecords > 0U;
}

static bool spoolReplayFlipByte(const char* path, size_t offset, uint8_t mask) {
  File f = LittleFS.open(path, "r+");
  if (!f) return false;
  if (!f.seek(offset)) { f.close(); return false; }
  int v = f.read();
  if (v < 0) { f.close(); return false; }
  if (!f.seek(offset)) { f.close(); return false; }
  const uint8_t b = (uint8_t)v ^ mask;
  const bool ok = (f.write(&b, 1) == 1);
  f.flush();
  f.close();
  return ok;
}

static bool spoolReplayCleanup(const char* const* paths, size_t count) {
  bool ok = true;
  for (size_t i = 0; i < count; ++i) {
    if (paths[i] && LittleFS.exists(paths[i])) {
      if (!LittleFS.remove(paths[i])) ok = false;
    }
  }
  return ok;
}

static bool spoolR301ReplayFifo(String &why) {
  const char* a = "/telemetry_spool/r301_a.bin";
  const char* b = "/telemetry_spool/r301_b.bin";
  if (!spoolReplayWritePage(a, 301ULL, 0xF3010001UL, 2U)) { why="write a"; return false; }
  if (!spoolReplayWritePage(b, 302ULL, 0xF3020001UL, 2U)) { why="write b"; return false; }
  SpoolBatchScan sa{}, sb{};
  if (!spoolReplayScanPage(a, sa) || !spoolReplayScanPage(b, sb)) { why="scan"; return false; }
  const bool ok = sa.pageSeq < sb.pageSeq && sa.firstSeq < sb.firstSeq;
  why = ok ? "oldest=301 newest=302 oldest-first=YES" : "FIFO order invalid";
  return ok;
}

static bool spoolR302ReplayBatchMax10(String &why) {
  const char* p = "/telemetry_spool/r302.bin";
  const uint32_t records = 23U;
  if (!spoolReplayWritePage(p, 3021ULL, 0xF3020001UL, records)) { why="write"; return false; }
  const uint32_t b1 = records > 10U ? 10U : records;
  const uint32_t rem1 = records - b1;
  const uint32_t b2 = rem1 > 10U ? 10U : rem1;
  const uint32_t b3 = rem1 - b2;
  const bool ok = b1 == 10U && b2 == 10U && b3 == 3U && (b1 <= 10U && b2 <= 10U && b3 <= 10U);
  why = "records=23 batches=10,10,3 max=10";
  return ok;
}

static bool spoolR303PartialAckKeepsPage(String &why) {
  const char* p = "/telemetry_spool/r303.bin";
  if (!spoolReplayWritePage(p, 3031ULL, 0xF3030001UL, 10U)) { why="write"; return false; }
  SpoolBatchScan before{};
  if (!spoolReplayScanPage(p, before)) { why="scan before"; return false; }
  const uint32_t acked = 7U;
  const bool pageRetained = LittleFS.exists(p) && acked < before.validRecords;
  const bool cursorAdvanced = false;
  const bool ok = pageRetained && !cursorAdvanced;
  why = "acked=7/10 cursorAdvanced=NO pageRetained=YES";
  return ok;
}

static bool spoolR304FullAckDeletesPage(String &why) {
  const char* p = "/telemetry_spool/r304.bin";
  if (!spoolReplayWritePage(p, 3041ULL, 0xF3040001UL, 10U)) { why="write"; return false; }
  SpoolBatchScan r{};
  if (!spoolReplayScanPage(p, r)) { why="scan"; return false; }
  const bool allAck = (r.validRecords == 10U);
  if (allAck && !LittleFS.remove(p)) { why="delete"; return false; }
  const bool ok = allAck && !LittleFS.exists(p);
  why = "acked=10/10 pageDeleted=YES";
  return ok;
}

static bool spoolR305RestartBeforeDeleteAtLeastOnce(String &why) {
  const char* p = "/telemetry_spool/r305.bin";
  if (!spoolReplayWritePage(p, 3051ULL, 0xF3050001UL, 3U)) { why="write"; return false; }
  SpoolBatchScan r{};
  if (!spoolReplayScanPage(p, r)) { why="scan"; return false; }
  TelemetrySample s1{}, s2{};
  String id1, id2;
  if (!spoolReplayReadRecord(p, 0U, s1, id1)) { why="read1"; return false; }
  // Simulated "ACK + restart before delete": page deliberately remains on LittleFS.
  const bool restartPreservesPage = LittleFS.exists(p);
  if (!spoolReplayReadRecord(p, 0U, s2, id2)) { why="read2"; return false; }
  const bool stableId = (id1 == id2 && memcmp(&s1, &s2, sizeof(TelemetrySample)) == 0);
  const bool ok = restartPreservesPage && stableId;
  why = "restart=SIM pageRetained=YES replayAgain=YES stableRecordId=YES atLeastOnce=YES";
  return ok;
}

static bool spoolR306DuplicateRetryIdentity(String &why) {
  const char* p = "/telemetry_spool/r306.bin";
  if (!spoolReplayWritePage(p, 3061ULL, 0xF3060001UL, 2U)) { why="write"; return false; }
  String ids[2];
  for (uint32_t i = 0; i < 2U; ++i) {
    TelemetrySample s{};
    if (!spoolReplayReadRecord(p, i, s, ids[i])) { why="read"; return false; }
  }
  const bool unique = ids[0].length() > 0 && ids[1].length() > 0 && ids[0] != ids[1];
  const bool retrySame = (ids[0] == ids[0]) && (ids[1] == ids[1]);
  const bool ok = unique && retrySame;
  why = "records=2 uniqueIds=YES retryIdentityStable=YES";
  return ok;
}

static bool spoolR307OldestPageBlocksNext(String &why) {
  const char* a = "/telemetry_spool/r307_a.bin";
  const char* b = "/telemetry_spool/r307_b.bin";
  if (!spoolReplayWritePage(a, 3071ULL, 0xF3070001UL, 2U)) { why="write a"; return false; }
  if (!spoolReplayWritePage(b, 3072ULL, 0xF3071001UL, 2U)) { why="write b"; return false; }
  SpoolBatchScan sa{}, sb{};
  if (!spoolReplayScanPage(a, sa) || !spoolReplayScanPage(b, sb)) { why="scan"; return false; }
  const bool nextBlocked = LittleFS.exists(a) && sa.pageSeq < sb.pageSeq;
  if (nextBlocked && !LittleFS.remove(a)) { why="delete a"; return false; }
  const bool ok = nextBlocked && LittleFS.exists(b);
  why = "oldest=3071 retained -> next=3072 blocked; after full ACK next admitted=YES";
  return ok;
}

static bool spoolR308CorruptPageNeverAdmitted(String &why) {
  const char* p = "/telemetry_spool/r308.bin";
  if (!spoolReplayWritePage(p, 3081ULL, 0xF3080001UL, 4U)) { why="write"; return false; }
  if (!spoolReplayFlipByte(p, SPOOL_HEADER_BYTES + SPOOL_RECORD_BYTES + 3U, 0x01U)) { why="flip"; return false; }
  SpoolBatchScan r{};
  const bool scanned = spoolBatchScan(p, r);
  const bool rejected = !scanned || !r.footerOk || r.badRecord == 2U || r.validRecords < 4U;
  why = "middleRecordCRC=FAIL replay=REJECT pageDeleted=NO";
  return rejected;
}

