static bool spoolR313PartialRecordRecovery(String &why) {
  const char* p = "/telemetry_spool/r313.bin";
  if (!spoolBatchWriteOpenPartial(p, 3131ULL, 0xF3130001UL, 2U, 40U)) { why="write"; return false; }
  SpoolBatchScan r{};
  if (!spoolBatchScan(p, r)) { why="scan"; return false; }
  const bool ok = r.headerOk && !r.footerPresent && r.validRecords == 2U && r.tailBytes == 40U && r.badRecord == 0;
  why = "records=2 tail=40 footer=ABSENT recoverable=YES";
  return ok;
}

