  const bool ok = ro.footerOk && !rn.footerPresent && rn.validRecords == 2U && LittleFS.exists(oldp) && LittleFS.exists(newp);
  why = "oldest=3231 committed; newest=3232 open tail=20; newestCannotBypass=YES";
