// ============================================================================
// [R263-R272 LOCAL] SPOOL V2 BATCH 2 — semantyka i granice kontraktu.
// Wszystko test-only; zero zmian w produkcyjnym Firebase/ringu.
// ============================================================================
static bool spoolBatchWritePageWithFooterOverrides(const char* path, uint64_t pageSeq,
                                                    uint32_t firstSeq, uint32_t records,
                                                    uint32_t footerRecordCount,
                                                    uint64_t footerPageSeq,
                                                    uint32_t footerFirstSeq,
                                                    uint32_t footerLastSeq) {
  spoolBatchRemove(path);
  if (!spoolBatchEnsureDir()) return false;
  File f = LittleFS.open(path, "w");
  if (!f) return false;
  SpoolPageHeader h{};
  h.magic=SPOOL_PAGE_MAGIC; h.formatVersion=SPOOL_PAGE_FORMAT_VERSION; h.headerBytes=SPOOL_HEADER_BYTES;
  h.pageSeq=pageSeq; h.firstSampleSeq=firstSeq; h.recordBytes=SPOOL_RECORD_BYTES; h.capacity=SPOOL_64K_SAFE_RECORDS;
  h.firstMonoMs=millis(); h.headerCrc32=spoolR245HeaderCrc(h);
  if (f.write(reinterpret_cast<uint8_t*>(&h), sizeof(h)) != sizeof(h)) { f.close(); return false; }
  uint32_t pc=0xFFFFFFFFUL;
  for (uint32_t i=0;i<records;i++) {
    if (!spoolBatchWriteRecord(f, firstSeq+i, i+1U, pc)) { f.close(); return false; }
  }
  pc=~pc;
  SpoolPageFooter ft{};
  ft.magic=SPOOL_PAGE_MAGIC; ft.formatVersion=SPOOL_PAGE_FORMAT_VERSION; ft.footerBytes=SPOOL_FOOTER_BYTES;
  ft.pageSeq=footerPageSeq; ft.firstSampleSeq=footerFirstSeq; ft.lastSampleSeq=footerLastSeq;
  ft.recordCount=footerRecordCount; ft.payloadCrc32=pc; ft.commitMarker=SPOOL_PAGE_COMMIT_MARKER;
  ft.footerCrc32=spoolR245FooterCrc(ft);
  const bool ok = f.write(reinterpret_cast<uint8_t*>(&ft), sizeof(ft)) == sizeof(ft);
  f.flush(); f.close();
  return ok;
}

static bool spoolR263FooterBounds(String &why) {
  const char* path="/telemetry_spool/r_batch_263.bin";
  if (!spoolBatchWriteCommittedPage(path,263ULL,0xF2630001UL,4U,false,false,false,false)) { why="write"; return false; }
  SpoolBatchScan r; if (!spoolBatchScan(path,r) || !r.footerOk) { why="footer"; return false; }
  if (r.firstSeq != 0xF2630001ULL || r.lastSeq != 0xF2630004ULL || r.validRecords != 4U) {
    why="first/last/count mismatch"; return false;
  }
  why="first=0xF2630001 last=0xF2630004 count=4"; return true;
}

static bool spoolR264DuplicateSeq(String &why) {
  const char* path="/telemetry_spool/r_batch_264.bin";
  spoolBatchRemove(path); if (!spoolBatchEnsureDir()) { why="mkdir"; return false; }
  File f=LittleFS.open(path,"w"); if(!f){why="open";return false;}
  SpoolPageHeader h{}; h.magic=SPOOL_PAGE_MAGIC; h.formatVersion=SPOOL_PAGE_FORMAT_VERSION; h.headerBytes=SPOOL_HEADER_BYTES;
  h.pageSeq=264ULL; h.firstSampleSeq=0xF2640001UL; h.recordBytes=SPOOL_RECORD_BYTES; h.capacity=SPOOL_64K_SAFE_RECORDS;
  h.headerCrc32=spoolR245HeaderCrc(h); if(f.write((uint8_t*)&h,sizeof(h))!=sizeof(h)){f.close();why="header";return false;}
  uint32_t pc=0xFFFFFFFFUL;
  for(uint32_t i=0;i<2;i++){
    TelemetrySample sample{}; if(!spoolR245BuildSample(i+1U,sample)){f.close();why="sample";return false;}
    sample.sampleSeq=0xF2640001UL; uint8_t rec[SPOOL_RECORD_BYTES]={}; memcpy(rec,&sample,sizeof(sample));
    uint32_t crc=spoolR245Crc32(rec,sizeof(sample)); memcpy(rec+sizeof(sample),&crc,sizeof(crc));
    if(f.write(rec,sizeof(rec))!=sizeof(rec)){f.close();why="record";return false;} pc=spoolR252UpdateCrc(pc,rec,sizeof(rec));
  }
  f.flush(); f.close(); SpoolBatchScan r; if(!spoolBatchScan(path,r)){why="scan";return false;}
  if(r.badRecord!=2 || r.validRecords!=1U){why="duplicate accepted";return false;}
  why="duplicateSeq=0xF2640001 badRecord=2 validPrefix=1"; return true;
}

static bool spoolR265FooterCountMismatch(String &why) {
  const char* path="/telemetry_spool/r_batch_265.bin";
  if(!spoolBatchWritePageWithFooterOverrides(path,265ULL,0xF2650001UL,4U,5U,265ULL,0xF2650001UL,0xF2650004UL)){why="write";return false;}
  SpoolBatchScan r; if(!spoolBatchScan(path,r)||!r.footerPresent){why="footer missing";return false;}
  if(r.footerOk){why="bad recordCount accepted";return false;}
  why="footerRecordCount=5 expected=4 rejected"; return true;
}

static bool spoolR266FooterPageSeqMismatch(String &why) {
  const char* path="/telemetry_spool/r_batch_266.bin";
  if(!spoolBatchWritePageWithFooterOverrides(path,266ULL,0xF2660001UL,3U,3U,9999ULL,0xF2660001UL,0xF2660003UL)){why="write";return false;}
  SpoolBatchScan r; if(!spoolBatchScan(path,r)||!r.footerPresent){why="footer missing";return false;}
  if(r.footerOk){why="bad pageSeq accepted";return false;}
  why="footerPageSeq=9999 headerPageSeq=266 rejected"; return true;
}

