  uint8_t rec[SPOOL_RECORD_BYTES]={}; memcpy(rec,&s,sizeof(s)); uint32_t crc=spoolR245Crc32(rec,sizeof(s)); memcpy(rec+sizeof(s),&crc,4);
  TelemetrySample d{}; memcpy(&d,rec,sizeof(d));
