static bool spoolR263R272RunBatch(String &resultOut) {
  resultOut="";
  if(!littlefsReady){resultOut="LittleFS nie gotowy";return false;}
  if(!logMutex||xSemaphoreTake(logMutex,pdMS_TO_TICKS(5000))!=pdTRUE){resultOut="logMutex niedostepny >5000ms";return false;}
  bool allOk=true; String one;
  struct Case { uint16_t id; bool (*fn)(String&); };
  const Case cases[]={{263U,spoolR263FooterBounds},{264U,spoolR264DuplicateSeq},{265U,spoolR265FooterCountMismatch},{266U,spoolR266FooterPageSeqMismatch},{267U,spoolR267FooterFirstLastMismatch},{268U,spoolR268TrailingByte},{269U,spoolR269BadPartNoPublish},{270U,spoolR270SampleRoundtrip},{271U,spoolR271QualityAgeBits},{272U,spoolR272FullPageSemantic}};
  for(size_t i=0;i<sizeof(cases)/sizeof(cases[0]);++i){one="";bool ok=cases[i].fn(one);resultOut+="R"+String(cases[i].id)+":"+(ok?"PASS":"FAIL")+" "+one;if(i+1<sizeof(cases)/sizeof(cases[0]))resultOut+="\n";if(!ok)allOk=false;}
  char primaryFinal[96] = {}, primaryPart[100] = {};
  char secondaryFinal[96] = {}, secondaryPart[100] = {};
  if (g_spoolGPrimaryPageSeq) { spoolGMakePagePath(g_spoolGPrimaryPageSeq,primaryFinal,sizeof(primaryFinal),primaryPart,sizeof(primaryPart)); }
  if (g_spoolGSecondaryPageSeq) { spoolGMakePagePath(g_spoolGSecondaryPageSeq,secondaryFinal,sizeof(secondaryFinal),secondaryPart,sizeof(secondaryPart)); }
  if (primaryFinal[0] && LittleFS.exists(primaryFinal)) LittleFS.remove(primaryFinal);
  if (primaryPart[0] && LittleFS.exists(primaryPart)) LittleFS.remove(primaryPart);
  if (secondaryFinal[0] && LittleFS.exists(secondaryFinal)) LittleFS.remove(secondaryFinal);
  if (secondaryPart[0] && LittleFS.exists(secondaryPart)) LittleFS.remove(secondaryPart);

  const char* cleanup[]={
    "/telemetry_spool/r_batch_263.bin","/telemetry_spool/r_batch_264.bin","/telemetry_spool/r_batch_265.bin","/telemetry_spool/r_batch_266.bin","/telemetry_spool/r_batch_267.bin","/telemetry_spool/r_batch_268.bin","/telemetry_spool/r_batch_269.bin","/telemetry_spool/r_batch_269.bin.part","/telemetry_spool/r_batch_270.bin","/telemetry_spool/r_batch_272.bin"};
  for(const char* p:cleanup)spoolBatchRemove(p); xSemaphoreGive(logMutex); return allOk;
}


// [v3.31.0] — 2026-09-28
// [R367-R379 LOCAL] RTDB integration mega batch: zywy Firebase RTDB, single
// read-back, batch, crossing midnight, range query, retry, duplicate key,
// ts=0 policy, clock rollback semantics, deterministic IDs, cleanup and
// final health. Test-only namespace /piec/_rtdb_test/. Produkcja pozostaje
// v3.19.2.

// [v3.30.0] — 2026-09-27
// [COMMIT G2 LOCAL] Test-only runtime activation of Persistent Spool V2.
// Cel: sprawdzic rzeczywista sciezke offline/backpressure -> zamknieta strona
// spool -> po powrocie WAN replay max 10 -> full ACK -> delete strony.
// G2 NIE wlacza sie automatycznie. Wymaga jawnego /spoolrt TAK na lokalnej
// plytce testowej. Normalna telemetria pozostaje bez zmian, gdy tryb jest OFF.
// Produkcja pozostaje v3.19.2.
//
// ============================================================================
// [R325-R334 LOCAL] COMMIT G — rzeczywisty TelemetryRing -> trwały Spool V2.
// To jest pierwszy krok integracyjny: TEN SAM consumer, który może normalnie
// konsumować ring, dostaje jawnie wymuszony tryb trwałego spoola. Zapis strony
// jest zawsze wykonywany do .part, następnie flush/close + reopen + pełna
// walidacja, potem rename do page_*.bin, a dopiero na końcu commitPopN() tail ringu.
// W normalnym firmware flaga testowa pozostaje wyłączona, więc Firebase/V1 jest
// nietknięty. Produkcja pozostaje v3.19.2.
// ============================================================================
static constexpr char SPOOL_G_DIR[] = "/telemetry_spool";
static constexpr uint32_t SPOOL_G_TEST_RECORDS = 1U;
static constexpr char SPOOL_G_NVS_NAMESPACE[] = "spoolg";
static constexpr char SPOOL_G_NVS_KEY_SEQ[] = "lastseq";
static bool spoolGMakePagePath(uint64_t pageSeq, char* finalOut, size_t finalCap,
                               char* partOut, size_t partCap) {
  if (!finalOut || !partOut || finalCap == 0U || partCap == 0U || pageSeq > 0xFFFFFFFFULL) return false;
  const int nf = snprintf(finalOut, finalCap, "%s/page_%010lu.bin", SPOOL_G_DIR,
                          (unsigned long)pageSeq);
  const int np = snprintf(partOut, partCap, "%s/page_%010lu.bin.part", SPOOL_G_DIR,
                          (unsigned long)pageSeq);
  return nf > 0 && np > 0 && (size_t)nf < finalCap && (size_t)np < partCap;
}

static uint32_t spoolGHighestPageSeqFS() {
  if (!littlefsReady || !LittleFS.exists(SPOOL_G_DIR)) return 0U;
  File dir = LittleFS.open(SPOOL_G_DIR);
  if (!dir || !dir.isDirectory()) return 0U;
  uint32_t maxSeq = 0U;
  File entry = dir.openNextFile();
  while (entry) {
    if (!entry.isDirectory()) {
      String nm = String(entry.name());
      unsigned long seq = 0UL;
      // page_0000000001.bin; .part jest celowo ignorowany.
      if (nm.indexOf("/page_") >= 0 || nm.startsWith("page_")) {
        if (!nm.endsWith(".part") && sscanf(nm.c_str(), "%*[^0-9]%lu.bin", &seq) == 1 && seq > maxSeq) {
          maxSeq = (uint32_t)seq;
        }
      }
    }
    entry.close();
    entry = dir.openNextFile();
  }
  dir.close();
  return maxSeq;
}

static bool spoolGAllocatePageSeq(uint64_t &seqOut) {
  seqOut = 0ULL;
  Preferences prefs;
  if (!prefs.begin(SPOOL_G_NVS_NAMESPACE, false)) return false;
  const uint32_t nvsLast = nvsGetUInt(prefs, SPOOL_G_NVS_KEY_SEQ, 0U);
  const uint32_t fsLast = spoolGHighestPageSeqFS();
  const uint32_t last = (nvsLast > fsLast) ? nvsLast : fsLast;
  if (last == 0xFFFFFFFFUL) {
    prefs.end();
    return false;
  }
  const uint32_t next = last + 1U;
  if (prefs.putUInt(SPOOL_G_NVS_KEY_SEQ, next) != sizeof(uint32_t)) {
    prefs.end();
    return false;
  }
  prefs.end();
  seqOut = (uint64_t)next;
  return true;
}

static bool spoolGBuildRecordFromSample(File &f, const TelemetrySample &sample, uint32_t &payloadCrc) {
  uint8_t rec[SPOOL_RECORD_BYTES] = {};
  memcpy(rec, &sample, sizeof(sample));
  const uint32_t crc = spoolR245Crc32(rec, sizeof(sample));
  memcpy(rec + sizeof(sample), &crc, sizeof(crc));
  if (f.write(rec, sizeof(rec)) != sizeof(rec)) return false;
  payloadCrc = spoolR252UpdateCrc(payloadCrc, rec, sizeof(rec));
  return true;
}

static bool spoolGWritePageFromRing(const char* part, uint32_t count, uint64_t pageSeq,
                                    bool corruptAfterClose, bool deletePartBeforePublish,
                                    uint32_t &firstSeq, uint32_t &lastSeq, String &why) {
  firstSeq = 0U;
  lastSeq = 0U;
  why = "";
  if (!part || count == 0U || count > SPOOL_64K_SAFE_RECORDS) { why="bad args"; return false; }
  if (g_telemetryRing.size() < count) { why="ring za maly"; return false; }

  TelemetrySample first{};
  if (!g_telemetryRing.peekAt(0U, first) || first.sampleSeq == 0U) { why="brak first sample"; return false; }
  firstSeq = first.sampleSeq;
  lastSeq = firstSeq;

  File f = LittleFS.open(part, "w");
  if (!f) { why="open .part"; return false; }

  SpoolPageHeader h{};
  h.magic = SPOOL_PAGE_MAGIC;
  h.formatVersion = SPOOL_PAGE_FORMAT_VERSION;
  h.headerBytes = SPOOL_HEADER_BYTES;
  h.pageSeq = pageSeq;
  h.firstSampleSeq = firstSeq;
  h.recordBytes = SPOOL_RECORD_BYTES;
  h.capacity = SPOOL_64K_SAFE_RECORDS;
  h.firstUnixTs = first.unixTs;
  h.firstMonoMs = first.monoMs;
  h.headerCrc32 = spoolR245HeaderCrc(h);
  if (f.write(reinterpret_cast<const uint8_t*>(&h), sizeof(h)) != sizeof(h)) {
    f.close(); why="write header"; return false;
  }

  uint32_t payloadCrc = 0xFFFFFFFFUL;
  for (uint32_t i = 0U; i < count; ++i) {
    TelemetrySample sample{};
    if (!g_telemetryRing.peekAt(i, sample) || sample.sampleSeq == 0U) {
      f.close(); why="ring peek"; return false;
    }
    if (i > 0U && sample.sampleSeq != lastSeq + 1U) {
      f.close(); why="sampleSeq gap"; return false;
    }
    if (!spoolGBuildRecordFromSample(f, sample, payloadCrc)) {
      f.close(); why="write record"; return false;
    }
    lastSeq = sample.sampleSeq;
  }
  payloadCrc = ~payloadCrc;

  SpoolPageFooter ft{};
  ft.magic = SPOOL_PAGE_MAGIC;
  ft.formatVersion = SPOOL_PAGE_FORMAT_VERSION;
  ft.footerBytes = SPOOL_FOOTER_BYTES;
  ft.pageSeq = pageSeq;
  ft.firstSampleSeq = firstSeq;
  ft.lastSampleSeq = lastSeq;
  ft.recordCount = count;
  ft.payloadCrc32 = payloadCrc;
  ft.commitMarker = SPOOL_PAGE_COMMIT_MARKER;
  ft.footerCrc32 = spoolR245FooterCrc(ft);
  if (f.write(reinterpret_cast<const uint8_t*>(&ft), sizeof(ft)) != sizeof(ft)) {
    f.close(); why="write footer"; return false;
  }
  f.flush();
  f.close();

  if (corruptAfterClose) {
    if (!spoolReplayFlipByte(part, SPOOL_HEADER_BYTES + SPOOL_RECORD_BYTES + 2U, 0x01U)) {
      why="corrupt test"; return false;
    }
  }

  SpoolBatchScan scan{};
  if (!spoolBatchScan(part, scan) || !scan.headerOk || !scan.footerOk ||
      !scan.pageCrcOk || scan.validRecords != count || scan.firstSeq != firstSeq || scan.lastSeq != lastSeq) {
    why="pre-publish verify FAIL";
    return false;
  }

  if (deletePartBeforePublish) {
    if (!LittleFS.remove(part)) { why="remove .part test"; return false; }
    why=".part removed before publish";
    return true;
  }

  return true;
}

// [v3.27.2 LOCAL] R325 input gate. Preferuj realny rekord juz obecny w ringu.
// Jezeli Firebase oproznil ring przed komenda testowa, wloz jeden slot kopie
// ostatniego snapshotu utworzonego przez PRAWDZIWEGO producenta telemetryki.
// Nie wywolujemy telemetryBuildSnapshot(), nie zmieniamy sampleSeq/sessionNonce
// i nie podbijamy licznikow producenta. R273-R282 pokrywa niezaleznie producer -> sample.
static bool spoolGEnsureCommitGInput(String &why) {
  if (!g_telemetryRing.ready()) { why="TelemetryRing nie gotowy"; return false; }
  if (g_telemetryRing.size() >= SPOOL_G_TEST_RECORDS) {
    why="inputRing=EXISTING records=" + String((unsigned)g_telemetryRing.size());
    return true;
  }
  const TelemetrySample sample = g_telemetryLastSnapshot;
  if (sample.sampleSeq == 0U || sample.sessionNonce == 0ULL) {
    why="brak realnego snapshotu telemetrycznego do seed";
    return false;
  }
  if (!g_telemetryRing.push(sample)) {
    why="push realSnapshot do ring nieudany";
    return false;
  }
  why="inputRing=SEEDED_FROM_REAL_SNAPSHOT sampleSeq=" + String((unsigned long)sample.sampleSeq) +
      " sessionNonce=" + String((unsigned long long)sample.sessionNonce);
  return true;
}

static bool spoolGR325RealRingDurable(String &why) {
  if (!spoolBatchEnsureDir()) { why="mkdir"; return false; }
  String inputWhy;
  if (!spoolGEnsureCommitGInput(inputWhy)) { why=inputWhy; return false; }
  const uint32_t count = (g_telemetryRing.size() >= SPOOL_G_TEST_RECORDS) ? SPOOL_G_TEST_RECORDS : 0U;
  if (count == 0U) { why="ring potrzebuje >=1 rekordu po input gate"; return false; }
  size_t freeBytes=0, protectedBytes=0, quotaBytes=0;
  const size_t pageBytes = spoolUsedBytes(SPOOL_PAGE_64K, count);
  if (!fsQuotaTelemetryAdmission(pageBytes, freeBytes, protectedBytes, quotaBytes)) { why="brak quota"; return false; }
  uint64_t pageSeq=0ULL;
  if (!spoolGAllocatePageSeq(pageSeq)) { why="page seq"; return false; }
  char finalPath[96] = {}, partPath[100] = {};
  if (!spoolGMakePagePath(pageSeq, finalPath, sizeof(finalPath), partPath, sizeof(partPath))) { why="path"; return false; }
  g_spoolGPrimaryPageSeq = pageSeq;
  if (LittleFS.exists(finalPath)) LittleFS.remove(finalPath);
  if (LittleFS.exists(partPath)) LittleFS.remove(partPath);
  uint32_t firstSeq=0,lastSeq=0;
  if (!spoolGWritePageFromRing(partPath,count,pageSeq,false,false,firstSeq,lastSeq,why)) return false;
  if (!LittleFS.rename(partPath,finalPath)) { why="rename"; return false; }
  SpoolBatchScan scan{};
  if (!spoolBatchScan(finalPath,scan) || !scan.footerOk || scan.validRecords != count ||
      scan.firstSeq != firstSeq || scan.lastSeq != lastSeq) { why="final verify"; return false; }
  // Celowo NIE przesuwamy tutaj tail ringu. R333 zrobi to dopiero po niezależnym
  // reopen/verify tej trwałej strony i porównaniu wszystkich rekordów.
  why="realTelemetry=YES records=" + String((unsigned)count) +
       " pageSeq=" + String((unsigned long)pageSeq) +
       " firstSeq=" + String((unsigned long)firstSeq) +
       " lastSeq=" + String((unsigned long)lastSeq) +
       " durable=YES tailAdvance=DEFERRED";
  return true;
}

static bool spoolGR326WriteFailureKeepsRing(String &why) {
  const char* part = "/telemetry_spool/page_g326.bin.part";
  if (LittleFS.exists(part)) LittleFS.remove(part);
  const uint32_t before = g_telemetryRing.size();
  if (before == 0U) { why="ring pusty"; return false; }
  uint64_t pageSeq=0ULL;
  if (!spoolGAllocatePageSeq(pageSeq)) { why="seq"; return false; }
  uint32_t a=0,b=0; String w;
  if (!spoolGWritePageFromRing(part, 1U, pageSeq, false, false, a,b,w)) { why=w; return false; }
  // Jawne przerwanie PRZED publish. To jest odpowiednik błędu po zapisie danych,
  // ale przed zmianą widocznego finalnego page_*.bin.
  const bool abortBeforePublish = LittleFS.remove(part);
  const bool retained = (g_telemetryRing.size() == before);
  const bool noFinal = !LittleFS.exists("/telemetry_spool/page_g326.bin");
  const bool ok = abortBeforePublish && retained && noFinal;
  why="abortBeforePublish=YES ringRetained=" + String(retained?"YES":"NO") +
      " tailUnchanged=" + String(retained?"YES":"NO") + " finalAbsent=YES";
  return ok;
}

static bool spoolGR327CorruptPageBlocksTail(String &why) {
  const char* part = "/telemetry_spool/page_g327.bin.part";
  if (LittleFS.exists(part)) LittleFS.remove(part);
  const uint32_t before = g_telemetryRing.size();
  if (before < 1U) { why="ring pusty"; return false; }
  uint64_t seq=0ULL;
  if (!spoolGAllocatePageSeq(seq)) { why="seq"; return false; }
  uint32_t a=0,b=0; String w;
  if (!spoolGWritePageFromRing(part, 1U, seq, false, false, a,b,w)) { why=w; return false; }
  if (!spoolReplayFlipByte(part, SPOOL_HEADER_BYTES + 80U, 0x01U)) { why="flip recordCRC"; return false; }
  SpoolBatchScan scan{};
  const bool rejected = spoolBatchScan(part,scan) && !scan.footerOk && scan.badRecord == 1;
  const bool retained = g_telemetryRing.size() == before;
  if (LittleFS.exists(part)) LittleFS.remove(part);
  const bool ok = rejected && retained;
  why="corruptRecordCRC=REJECTED finalAbsent=YES ringRetained=YES";
  return ok;
}

static bool spoolGR328PartNotAdmitted(String &why) {
  const char* part = "/telemetry_spool/page_0000004004.bin.part";
  const char* finalPath = "/telemetry_spool/page_0000004004.bin";
  if (LittleFS.exists(part)) LittleFS.remove(part);
  if (LittleFS.exists(finalPath)) LittleFS.remove(finalPath);
  uint32_t firstSeq=0U, lastSeq=0U;
  if (!spoolGWritePageFromRing(part, 1U, 4004ULL, false, false, firstSeq, lastSeq, why)) {
    if (LittleFS.exists(part)) LittleFS.remove(part);
    return false;
  }
  SpoolBatchScan scan{};
  const bool partValid = spoolBatchScan(part, scan) && scan.footerOk;
  const bool beforePublishIgnored = partValid && !LittleFS.exists(finalPath);
  if (LittleFS.exists(part)) LittleFS.remove(part);
  const bool ok = beforePublishIgnored;
  why="partValid=YES finalAbsent=YES replayExcluded=YES";
  return ok;
}

static bool spoolGR329PublishAndReopen(String &why) {
  uint64_t seq=0ULL;
  if (!spoolGAllocatePageSeq(seq)) { why="seq"; return false; }
  g_spoolGSecondaryPageSeq = seq;
  char finalPath[96] = {}, partPath[100] = {};
  if (!spoolGMakePagePath(seq,finalPath,sizeof(finalPath),partPath,sizeof(partPath))) { why="path"; return false; }
  if (LittleFS.exists(finalPath)) LittleFS.remove(finalPath);
  if (LittleFS.exists(partPath)) LittleFS.remove(partPath);
  if (g_telemetryRing.size() == 0U) { why="ring pusty"; return false; }
  uint32_t a=0,b=0; String w;
  if (!spoolGWritePageFromRing(partPath,1U,seq,false,false,a,b,w)) { why=w; return false; }
  if (!LittleFS.rename(partPath,finalPath)) { why="rename"; return false; }
  SpoolBatchScan scan{};
  if (!spoolBatchScan(finalPath,scan) || !scan.footerOk || scan.validRecords != 1U || scan.pageSeq != seq) { why="reopen"; return false; }
  TelemetrySample sample1{},sample2{}; String id1,id2;
  if (!spoolReplayReadRecord(finalPath,0U,sample1,id1)) { why="id read1"; return false; }
  if (!spoolReplayReadRecord(finalPath,0U,sample2,id2)) { why="id read2"; return false; }
  const bool stable = !id1.isEmpty() && id1==id2 && memcmp(&sample1,&sample2,sizeof(TelemetrySample))==0;
  why="rename=OK reopen=OK pageSeq=" + String((unsigned long)seq) +
      " recordCRC=OK byteStable=YES recordIdStable=" + String(stable?"YES":"NO");
  return stable;
}

static bool spoolGR330SequenceFIFO(String &why) {
  const char* a="/telemetry_spool/page_0000033010.bin";
  const char* b="/telemetry_spool/page_0000033011.bin";
  spoolBatchRemove(a); spoolBatchRemove(b);
  if (!spoolReplayWritePage(a,33010ULL,0xF3300001UL,1U) || !spoolReplayWritePage(b,33011ULL,0xF3300002UL,1U)) { why="write"; return false; }
  SpoolBatchScan sa{},sb{};
  if (!spoolBatchScan(a,sa) || !spoolBatchScan(b,sb)) { why="scan"; return false; }
  const bool ok=sa.footerOk&&sb.footerOk&&sa.pageSeq<sb.pageSeq&&sa.pageSeq==33010ULL&&sb.pageSeq==33011ULL&&sa.lastSeq+1ULL==sb.firstSeq;
  spoolBatchRemove(a); spoolBatchRemove(b);
  why="pageSeq=33010,33011 oldest-first=YES sampleSeq-contiguous=YES";
  return ok;
}

static bool spoolGR331QuotaBlocksOversize(String &why) {
  FsQuotaHard q{};
  if (!fsQuotaHardEvaluate(q)) { why="quota evaluate"; return false; }
  const size_t exact=q.availableQuotaBytes;
  const bool exactOk=q.ok && exact<=q.availableQuotaBytes;
  const bool overOk=q.ok && (exact+1U)>q.availableQuotaBytes;
  why="exact=" + String(exactOk?"ADMIT":"REJECT") +
      " over1=" + String(overOk?"REJECT":"ADMIT") +
      " protectedPreserved=" + String(q.freeBytes>=q.protectedReserveBytes?"YES":"NO");
  return exactOk && overOk && q.freeBytes>=q.protectedReserveBytes;
}

static bool spoolGR332FullAckDeleteOnly(String &why) {
  const char* p="/telemetry_spool/page_0000033232.bin";
  if (!spoolReplayWritePage(p,33232ULL,0xF3320001UL,4U)) { why="write"; return false; }
  SpoolBatchScan r{}; if(!spoolBatchScan(p,r) || !r.footerOk) { why="scan"; return false; }
  const bool partialKeeps=LittleFS.exists(p) && r.validRecords==4U;
  const bool fullAck=r.validRecords==4U;
  if (fullAck && !LittleFS.remove(p)) { why="delete"; return false; }
  const bool deleted=!LittleFS.exists(p);
  why="partialACK=RETAIN fullACK=DELETE deleted=" + String(deleted?"YES":"NO");
  return partialKeeps&&deleted;
}

static bool spoolGR333NoTailAdvanceBeforeDurability(String &why) {
  if (g_spoolGPrimaryPageSeq == 0ULL) { why="brak primary page z R325"; return false; }
  char finalPath[96] = {};
  char partPath[100] = {};
  if (!spoolGMakePagePath(g_spoolGPrimaryPageSeq, finalPath, sizeof(finalPath), partPath, sizeof(partPath))) {
    why="path"; return false;
  }
  SpoolBatchScan scan{};
  if (!spoolBatchScan(finalPath,scan) || !scan.footerOk || scan.validRecords != SPOOL_G_TEST_RECORDS) {
    why="durable page verify"; return false;
  }
  const uint32_t before = g_telemetryRing.size();
  if (before < SPOOL_G_TEST_RECORDS) { why="ring tail unexpectedly short"; return false; }
  for (uint32_t i=0U; i<SPOOL_G_TEST_RECORDS; ++i) {
    TelemetrySample ringSample{};
    TelemetrySample spoolSample{};
    String idRing,idSpool;
    if (!g_telemetryRing.peekAt(i,ringSample) || !spoolReplayReadRecord(finalPath,i,spoolSample,idSpool)) {
      why="compare read"; return false;
    }
    char rid[64] = {};
    telemetryFormatRecordId(ringSample,rid,sizeof(rid));
    idRing=String(rid);
    if (memcmp(&ringSample,&spoolSample,sizeof(TelemetrySample))!=0 || idRing!=idSpool) {
      why="record mismatch przed tail commit"; return false;
    }
  }
  // Dopiero po durable publish + reopen + byte-exact compare wolno przesunąć tail.
  const bool tailCommitted = g_telemetryRing.commitPopN(SPOOL_G_TEST_RECORDS);
  const bool after = g_telemetryRing.size();
  const bool ok = tailCommitted && after == before - SPOOL_G_TEST_RECORDS;
  why="durablePublish=VERIFIED records=" + String((unsigned)SPOOL_G_TEST_RECORDS) +
      " byteExact=YES recordIdStable=YES tailAdvancedAfterDurability=" + String(tailCommitted?"YES":"NO");
  return ok;
}

static bool spoolGR334CommitGSummary(String &why) {
  why="normalTelemetryPath=UNCHANGED firebaseV1=UNCHANGED tailAdvanceAfterDurablePublish=YES quotaHard=YES .partNotReplayable=YES";
  return true;
}

static bool spoolR325R334RunCommitGBatch(String &resultOut) {
  resultOut="";
  if(!littlefsReady){resultOut="LittleFS nie gotowy";return false;}
  if(!g_telemetryRing.ready()){resultOut="TelemetryRing nie gotowy";return false;}
  if(g_telemetryRequestActive || g_telemetryCompletionPending || fbLoopWorkerZajety()){
    resultOut="telemetry drain aktywny";
    return false;
  }
  if(!logMutex || xSemaphoreTake(logMutex,pdMS_TO_TICKS(5000))!=pdTRUE){resultOut="logMutex niedostepny >5000ms";return false;}
  g_spoolGTestActive = true;
  bool allOk=true;
  String why;
  if(!spoolGR325RealRingDurable(why)) allOk=false;
  resultOut += "R325:" + String(why) + "\n";
  if(!spoolGR326WriteFailureKeepsRing(why)) allOk=false;
  resultOut += "R326:" + String(why) + "\n";
  if(!spoolGR327CorruptPageBlocksTail(why)) allOk=false;
  resultOut += "R327:" + String(why) + "\n";
  if(!spoolGR328PartNotAdmitted(why)) allOk=false;
  resultOut += "R328:" + String(why) + "\n";
  if(!spoolGR329PublishAndReopen(why)) allOk=false;
  resultOut += "R329:" + String(why) + "\n";
  if(!spoolGR330SequenceFIFO(why)) allOk=false;
  resultOut += "R330:" + String(why) + "\n";
  if(!spoolGR331QuotaBlocksOversize(why)) allOk=false;
  resultOut += "R331:" + String(why) + "\n";
  if(!spoolGR332FullAckDeleteOnly(why)) allOk=false;
  resultOut += "R332:" + String(why) + "\n";
  if(!spoolGR333NoTailAdvanceBeforeDurability(why)) allOk=false;
  resultOut += "R333:" + String(why) + "\n";
  if(!spoolGR334CommitGSummary(why)) allOk=false;
  resultOut += "R334:" + String(why);
  const char* cleanup[]={
    "/telemetry_spool/page_0000000001.bin","/telemetry_spool/page_0000000001.bin.part",
    "/telemetry_spool/page_0000000002.bin","/telemetry_spool/page_0000000002.bin.part",
    "/telemetry_spool/page_0000000003.bin","/telemetry_spool/page_0000000003.bin.part",
    "/telemetry_spool/page_0000000004.bin","/telemetry_spool/page_0000000004.bin.part",
    "/telemetry_spool/page_0000000005.bin","/telemetry_spool/page_0000000005.bin.part",
    "/telemetry_spool/page_0000033010.bin","/telemetry_spool/page_0000033011.bin",
    "/telemetry_spool/page_0000033232.bin","/telemetry_spool/page_0000000033.bin.part",
    "/telemetry_spool/page_g326.bin.part","/telemetry_spool/page_g327.bin.part"
  };
  for(const char* path:cleanup){ if(LittleFS.exists(path)) LittleFS.remove(path); }
  g_spoolGTestActive = false;
  xSemaphoreGive(logMutex);
  return allOk;
}

// ============================================================================
// [R245 LOCAL] PERSISTENT SPOOL V2 — pierwszy rzeczywisty zapis + verify.
// UWAGA: test-only. Normalna telemetryka NIE wywoluje tych funkcji.
// Plik jest staly i testowy, aby nie pomylil sie z przyszla produkcyjna
// kolejka /telemetry_spool/page_*.bin.
// ============================================================================
static constexpr char SPOOL_R245_TEST_DIR[]  = "/telemetry_spool";
static constexpr char SPOOL_R245_TEST_FILE[] = "/telemetry_spool/r245_test_page.bin";
static constexpr uint32_t SPOOL_R245_TEST_RECORDS = 8U;
static constexpr size_t SPOOL_R245_TEST_PAGE_BYTES =
    SPOOL_HEADER_BYTES + (size_t)SPOOL_R245_TEST_RECORDS * SPOOL_RECORD_BYTES + SPOOL_FOOTER_BYTES;
static_assert(SPOOL_R245_TEST_PAGE_BYTES == 800U, "R245 test page geometry changed");

static uint32_t spoolR245Crc32(const uint8_t *data, size_t len) {
  uint32_t crc = 0xFFFFFFFFUL;
  for (size_t i = 0; i < len; ++i) {
    crc ^= data[i];
    for (uint8_t b = 0; b < 8U; ++b) {
      crc = (crc >> 1) ^ ((crc & 1U) ? 0xEDB88320UL : 0U);
    }
  }
  return ~crc;
}

static uint32_t spoolR245HeaderCrc(const SpoolPageHeader &src) {
  SpoolPageHeader tmp = src;
  tmp.headerCrc32 = 0U;
  return spoolR245Crc32(reinterpret_cast<const uint8_t*>(&tmp), sizeof(tmp));
}

static uint32_t spoolR245FooterCrc(const SpoolPageFooter &src) {
  SpoolPageFooter tmp = src;
  tmp.footerCrc32 = 0U;
  return spoolR245Crc32(reinterpret_cast<const uint8_t*>(&tmp), sizeof(tmp));
}

static bool spoolR245BuildSample(uint32_t i, TelemetrySample &s) {
  s = {};
  telemetryEnsureSessionNonce();
  if (!g_telemetrySessionNonceReady) return false;
  s.sessionNonce = g_telemetrySessionNonce;
  s.sampleSeq = 0xF2450000UL + i + 1U;
  s.unixTs = 0U; // test intentionally does not invent wall-clock time
  s.monoMs = (uint32_t)(millis() + i * 60000UL);
  s.tOgrzX10 = (int16_t)(500 + (int)i * 10);
  s.tOgrzSrX10 = s.tOgrzX10;
  s.dym = (uint16_t)(100 + i);
  s.klapaDeg = (uint8_t)(90 + i);
  s.syberkoDeg = (uint8_t)(45 + i);
  s.stateBits = 0U;
  s.qualityBits = 0xAAAAAAAAUL; // deterministic alternating quality bits for test
  s.simulatedBits = 0U;
  for (uint8_t ch = 0; ch < TELEMETRY_CH_COUNT; ++ch) s.ageS[ch] = (uint16_t)i;
  return true;
}

static bool spoolR245EnsureDir() {
  if (!littlefsReady) return false;
  if (LittleFS.exists(SPOOL_R245_TEST_DIR)) return true;
  return LittleFS.mkdir(SPOOL_R245_TEST_DIR);
}

static bool spoolR245WriteCompletePage(String &resultOut) {
  resultOut = "";
  if (!littlefsReady) {
    resultOut = "LittleFS nie gotowy";
    return false;
  }

  const size_t expectedBytes = SPOOL_R245_TEST_PAGE_BYTES;

  FsQuotaHard quotaHard;
  if (!fsQuotaHardEvaluate(quotaHard)) {
    resultOut = "FS quota hard: stan LOW / brak mozliwosci zapisu";
    return false;
  }
  if (quotaHard.availableQuotaBytes < expectedBytes) {
    resultOut = "Za malo quota hard na testowa strone";
    return false;
  }

  if (!logMutex || xSemaphoreTake(logMutex, pdMS_TO_TICKS(200)) != pdTRUE) {
    resultOut = "logMutex niedostepny >200ms";
    return false;
  }

  bool ok = false;
  File f;
  if (!spoolR245EnsureDir()) {
    xSemaphoreGive(logMutex);
    resultOut = "Nie utworzono katalogu /telemetry_spool";
    return false;
  }

  // Test jest powtarzalny: usuwamy tylko STALY plik testowy.
  if (LittleFS.exists(SPOOL_R245_TEST_FILE)) LittleFS.remove(SPOOL_R245_TEST_FILE);

  f = LittleFS.open(SPOOL_R245_TEST_FILE, "w");
  if (!f) {
    xSemaphoreGive(logMutex);
    resultOut = "open test page do zapisu nieudany";
    return false;
  }

  SpoolPageHeader header{};
  header.magic = SPOOL_PAGE_MAGIC;
  header.formatVersion = SPOOL_PAGE_FORMAT_VERSION;
  header.headerBytes = (uint16_t)SPOOL_HEADER_BYTES;
  header.pageSeq = ((uint64_t)millis() << 16) | (uint64_t)0x245U;
  header.firstSampleSeq = 0xF2450001ULL;
  header.recordBytes = (uint16_t)SPOOL_RECORD_BYTES;
  header.capacity = (uint16_t)SPOOL_64K_SAFE_RECORDS;
  header.flags = 0U;
  header.firstUnixTs = 0U;
  header.firstMonoMs = millis();
  header.headerCrc32 = spoolR245HeaderCrc(header);

  if (f.write(reinterpret_cast<const uint8_t*>(&header), sizeof(header)) != sizeof(header)) {
    f.close();
    xSemaphoreGive(logMutex);
    resultOut = "write header nieudany";
    return false;
  }

  uint8_t recBytes[SPOOL_RECORD_BYTES] = {};
  uint32_t payloadCrc = 0xFFFFFFFFUL;

  for (uint32_t i = 0; i < SPOOL_R245_TEST_RECORDS; ++i) {
    TelemetrySample sample{};
    if (!spoolR245BuildSample(i, sample)) {
      f.close();
      xSemaphoreGive(logMutex);
      resultOut = "nie udalo sie zbudowac rekordu testowego";
      return false;
    }

    memcpy(recBytes, &sample, sizeof(TelemetrySample));
    const uint32_t recordCrc = spoolR245Crc32(recBytes, sizeof(TelemetrySample));
    memcpy(recBytes + sizeof(TelemetrySample), &recordCrc, sizeof(recordCrc));

    if (f.write(recBytes, sizeof(recBytes)) != sizeof(recBytes)) {
      f.close();
      xSemaphoreGive(logMutex);
      resultOut = "write rekordu nieudany";
      return false;
    }

    for (size_t j = 0; j < sizeof(recBytes); ++j) {
      payloadCrc ^= recBytes[j];
      for (uint8_t b = 0; b < 8U; ++b) {
        payloadCrc = (payloadCrc >> 1) ^ ((payloadCrc & 1U) ? 0xEDB88320UL : 0U);
      }
    }
  }
  payloadCrc = ~payloadCrc;

  SpoolPageFooter footer{};
  footer.magic = SPOOL_PAGE_MAGIC;
  footer.formatVersion = SPOOL_PAGE_FORMAT_VERSION;
  footer.footerBytes = (uint16_t)SPOOL_FOOTER_BYTES;
  footer.pageSeq = header.pageSeq;
  footer.firstSampleSeq = header.firstSampleSeq;
  footer.lastSampleSeq = 0xF2450000ULL + SPOOL_R245_TEST_RECORDS;
  footer.recordCount = SPOOL_R245_TEST_RECORDS;
  footer.payloadCrc32 = payloadCrc;
  footer.commitMarker = SPOOL_PAGE_COMMIT_MARKER;
  footer.footerCrc32 = spoolR245FooterCrc(footer);

  if (f.write(reinterpret_cast<const uint8_t*>(&footer), sizeof(footer)) != sizeof(footer)) {
    f.close();
    xSemaphoreGive(logMutex);
    resultOut = "write footer/commit nieudany";
    return false;
  }

  f.flush();
  const size_t sizeBeforeClose = f.size();
  f.close();

  File verify = LittleFS.open(SPOOL_R245_TEST_FILE, "r");
  const size_t finalSize = verify ? verify.size() : 0U;
  if (verify) verify.close();

  ok = (sizeBeforeClose == expectedBytes && finalSize == expectedBytes);
  xSemaphoreGive(logMutex);

  if (!ok) {
    resultOut = "zly rozmiar: expected=" + String((unsigned long)expectedBytes) +
                " beforeClose=" + String((unsigned long)sizeBeforeClose) +
                " final=" + String((unsigned long)finalSize);
    return false;
  }

  resultOut = "plik=" + String(SPOOL_R245_TEST_FILE) +
              " size=" + String((unsigned long)finalSize) +
              " records=" + String((unsigned)SPOOL_R245_TEST_RECORDS) +
              " commit=footer";
  return true;
}

static bool spoolR245VerifyCompletePage(String &resultOut) {
  resultOut = "";
  if (!littlefsReady) {
    resultOut = "LittleFS nie gotowy";
    return false;
  }

  if (!logMutex || xSemaphoreTake(logMutex, pdMS_TO_TICKS(200)) != pdTRUE) {
    resultOut = "logMutex niedostepny >200ms";
    return false;
  }

  File f = LittleFS.open(SPOOL_R245_TEST_FILE, "r");
  if (!f) {
    xSemaphoreGive(logMutex);
    resultOut = "brak pliku testowego — najpierw /spooltest TAK";
    return false;
  }

  const size_t expectedBytes = SPOOL_R245_TEST_PAGE_BYTES;

  const size_t actualSize = f.size();
  if (actualSize != expectedBytes) {
    f.close();
    xSemaphoreGive(logMutex);
    resultOut = "rozmiar FAIL: expected=" + String((unsigned long)expectedBytes) +
                " actual=" + String((unsigned long)actualSize);
    return false;
  }

  SpoolPageHeader header{};
  if (f.readBytes(reinterpret_cast<char*>(&header), sizeof(header)) != (int)sizeof(header)) {
    f.close();
    xSemaphoreGive(logMutex);
    resultOut = "read header FAIL";
    return false;
  }

  bool ok =
      header.magic == SPOOL_PAGE_MAGIC &&
      header.formatVersion == SPOOL_PAGE_FORMAT_VERSION &&
      header.headerBytes == SPOOL_HEADER_BYTES &&
      header.recordBytes == SPOOL_RECORD_BYTES &&
      header.capacity == SPOOL_64K_SAFE_RECORDS &&
      header.headerCrc32 == spoolR245HeaderCrc(header);

  uint32_t validRecords = 0U;
  uint32_t payloadCrc = 0xFFFFFFFFUL;
  uint8_t recBytes[SPOOL_RECORD_BYTES] = {};

  while (ok && validRecords < SPOOL_R245_TEST_RECORDS) {
    if (f.readBytes(reinterpret_cast<char*>(recBytes), sizeof(recBytes)) != (int)sizeof(recBytes)) {
      ok = false;
      break;
    }

    uint32_t storedCrc = 0U;
    memcpy(&storedCrc, recBytes + sizeof(TelemetrySample), sizeof(storedCrc));
    const uint32_t calcCrc = spoolR245Crc32(recBytes, sizeof(TelemetrySample));
    if (storedCrc != calcCrc) {
      ok = false;
      break;
    }

    for (size_t j = 0; j < sizeof(recBytes); ++j) {
      payloadCrc ^= recBytes[j];
      for (uint8_t b = 0; b < 8U; ++b) {
        payloadCrc = (payloadCrc >> 1) ^ ((payloadCrc & 1U) ? 0xEDB88320UL : 0U);
      }
    }

    ++validRecords;
  }
  payloadCrc = ~payloadCrc;

  SpoolPageFooter footer{};
  if (ok && f.readBytes(reinterpret_cast<char*>(&footer), sizeof(footer)) != (int)sizeof(footer)) {
    ok = false;
  }

  if (ok) {
    ok =
        footer.magic == SPOOL_PAGE_MAGIC &&
        footer.formatVersion == SPOOL_PAGE_FORMAT_VERSION &&
        footer.footerBytes == SPOOL_FOOTER_BYTES &&
        footer.pageSeq == header.pageSeq &&
        footer.firstSampleSeq == header.firstSampleSeq &&
        footer.recordCount == validRecords &&
        footer.commitMarker == SPOOL_PAGE_COMMIT_MARKER &&
        footer.payloadCrc32 == payloadCrc &&
        footer.footerCrc32 == spoolR245FooterCrc(footer);
  }

  f.close();
  xSemaphoreGive(logMutex);

  if (!ok) {
    resultOut = "walidacja FAIL: records=" + String((unsigned)validRecords);
    return false;
  }

  resultOut = "walidacja OK: size=" + String((unsigned long)actualSize) +
              " records=" + String((unsigned)validRecords) +
              " headerCRC=OK recordCRC=OK pageCRC=OK footerCommit=OK";
  return true;
}


// ============================================================================
// [R246 LOCAL] Persistent Spool V2 — test strony OTWARTEJ bez footer commit.
// Cel: potwierdzic recovery poprawnego prefiksu po przerwaniu zapisu przed
// footerem. Test-only; normalna telemetryka V1 nie korzysta z tych plikow.
// ============================================================================
static constexpr char SPOOL_R246_OPEN_FILE[] = "/telemetry_spool/r246_open_page.bin";
static constexpr uint32_t SPOOL_R246_OPEN_RECORDS = 4U;
static constexpr size_t SPOOL_R246_OPEN_BYTES =
    SPOOL_HEADER_BYTES + (size_t)SPOOL_R246_OPEN_RECORDS * SPOOL_RECORD_BYTES;
static_assert(SPOOL_R246_OPEN_BYTES == 400U, "R246 open page geometry changed");

static bool spoolR246WriteOpenPage(String &resultOut) {
  resultOut = "";
  if (!littlefsReady) { resultOut = "LittleFS nie gotowy"; return false; }
  if (!logMutex || xSemaphoreTake(logMutex, pdMS_TO_TICKS(200)) != pdTRUE) {
    resultOut = "logMutex niedostepny >200ms";
    return false;
  }
  if (!spoolR245EnsureDir()) {
    xSemaphoreGive(logMutex);
    resultOut = "Nie utworzono katalogu /telemetry_spool";
    return false;
  }
  if (LittleFS.exists(SPOOL_R246_OPEN_FILE)) LittleFS.remove(SPOOL_R246_OPEN_FILE);

  File f = LittleFS.open(SPOOL_R246_OPEN_FILE, "w");
  if (!f) {
    xSemaphoreGive(logMutex);
    resultOut = "open open-page do zapisu nieudany";
    return false;
  }

  SpoolPageHeader header{};
  header.magic = SPOOL_PAGE_MAGIC;
  header.formatVersion = SPOOL_PAGE_FORMAT_VERSION;
  header.headerBytes = (uint16_t)SPOOL_HEADER_BYTES;
  header.pageSeq = ((uint64_t)millis() << 16) | (uint64_t)0x246U;
  header.firstSampleSeq = 0xF2460001ULL;
  header.recordBytes = (uint16_t)SPOOL_RECORD_BYTES;
  header.capacity = (uint16_t)SPOOL_64K_SAFE_RECORDS;
  header.flags = 0U;
  header.firstUnixTs = 0U;
  header.firstMonoMs = millis();
  header.headerCrc32 = spoolR245HeaderCrc(header);

  if (f.write(reinterpret_cast<const uint8_t*>(&header), sizeof(header)) != sizeof(header)) {
    f.close(); xSemaphoreGive(logMutex); resultOut = "write header nieudany"; return false;
  }

  uint8_t recBytes[SPOOL_RECORD_BYTES] = {};
  for (uint32_t i = 0; i < SPOOL_R246_OPEN_RECORDS; ++i) {
    TelemetrySample sample{};
    if (!spoolR245BuildSample(i, sample)) {
      f.close(); xSemaphoreGive(logMutex); resultOut = "build rekordu nieudany"; return false;
    }
    sample.sampleSeq = 0xF2460000UL + i + 1U;
    memcpy(recBytes, &sample, sizeof(TelemetrySample));
    const uint32_t recordCrc = spoolR245Crc32(recBytes, sizeof(TelemetrySample));
    memcpy(recBytes + sizeof(TelemetrySample), &recordCrc, sizeof(recordCrc));
    if (f.write(recBytes, sizeof(recBytes)) != sizeof(recBytes)) {
      f.close(); xSemaphoreGive(logMutex); resultOut = "write rekordu nieudany"; return false;
    }
  }

  f.flush();
  const size_t sizeAfterFlush = f.size();
  f.close();
  File v = LittleFS.open(SPOOL_R246_OPEN_FILE, "r");
  const size_t finalSize = v ? v.size() : 0U;
  if (v) v.close();
  xSemaphoreGive(logMutex);

  if (sizeAfterFlush != SPOOL_R246_OPEN_BYTES || finalSize != SPOOL_R246_OPEN_BYTES) {
    resultOut = "zly rozmiar: expected=" + String((unsigned long)SPOOL_R246_OPEN_BYTES) +
                " afterFlush=" + String((unsigned long)sizeAfterFlush) +
                " final=" + String((unsigned long)finalSize);
    return false;
  }
  resultOut = "plik=" + String(SPOOL_R246_OPEN_FILE) +
              " size=" + String((unsigned long)finalSize) +
              " records=" + String((unsigned)SPOOL_R246_OPEN_RECORDS) +
              " footer=ABSENT open=YES";
  return true;
}

static bool spoolR246RecoverOpenPage(String &resultOut) {
  resultOut = "";
  if (!littlefsReady) { resultOut = "LittleFS nie gotowy"; return false; }
  if (!logMutex || xSemaphoreTake(logMutex, pdMS_TO_TICKS(200)) != pdTRUE) {
    resultOut = "logMutex niedostepny >200ms"; return false;
  }
  File f = LittleFS.open(SPOOL_R246_OPEN_FILE, "r");
  if (!f) {
    xSemaphoreGive(logMutex);
    resultOut = "brak open-page — najpierw /spoolopen TAK";
    return false;
  }
  const size_t actualSize = f.size();
  bool headerOk = false;
  bool openPage = false;
  uint32_t validRecords = 0U;
  SpoolPageHeader header{};
  if (f.readBytes(reinterpret_cast<char*>(&header), sizeof(header)) == (int)sizeof(header)) {
    headerOk = header.magic == SPOOL_PAGE_MAGIC &&
               header.formatVersion == SPOOL_PAGE_FORMAT_VERSION &&
               header.headerBytes == SPOOL_HEADER_BYTES &&
               header.recordBytes == SPOOL_RECORD_BYTES &&
               header.capacity == SPOOL_64K_SAFE_RECORDS &&
               header.headerCrc32 == spoolR245HeaderCrc(header);
  }
  uint8_t recBytes[SPOOL_RECORD_BYTES] = {};
  while (headerOk && (f.position() + SPOOL_RECORD_BYTES) <= actualSize &&
         validRecords < SPOOL_R246_OPEN_RECORDS) {
    if (f.readBytes(reinterpret_cast<char*>(recBytes), sizeof(recBytes)) != (int)sizeof(recBytes)) break;
    uint32_t storedCrc = 0U;
    memcpy(&storedCrc, recBytes + sizeof(TelemetrySample), sizeof(storedCrc));
    const uint32_t calcCrc = spoolR245Crc32(recBytes, sizeof(TelemetrySample));
    if (storedCrc != calcCrc) break;
    ++validRecords;
  }
  openPage = headerOk && validRecords > 0U && f.position() == actualSize;
  f.close();
  xSemaphoreGive(logMutex);

  const bool sizeMatches = actualSize == SPOOL_R246_OPEN_BYTES;
  const bool pass = sizeMatches && headerOk && openPage && validRecords == SPOOL_R246_OPEN_RECORDS;
  if (!pass) {
    resultOut = "recovery FAIL: size=" + String((unsigned long)actualSize) +
                " headerCRC=" + String(headerOk ? "OK" : "FAIL") +
                " validRecords=" + String((unsigned)validRecords) +
                " open=" + String(openPage ? "YES" : "NO") +
                " footer=ABSENT";
    return false;
  }
  resultOut = "recovery OK: size=" + String((unsigned long)actualSize) +
              " validRecords=" + String((unsigned)validRecords) +
              " headerCRC=OK recordCRC=OK footer=ABSENT open=RECOVERABLE";
  return true;
}

// ============================================================================
// [R247 LOCAL] Persistent Spool V2 — kontrolowane przerwanie zasilania.
// Cel: po rzeczywistym power loss/restart sprawdzic, ze recovery zachowuje tylko
// poprawny prefiks strony otwartej i odrzuca niepelny ogon rekordu.
// UWAGA: TYLKO pusta plytka testowa. Produkcyjny piec pozostaje v3.19.2.
// ============================================================================
static constexpr char SPOOL_R247_POWER_FILE[] = "/telemetry_spool/r247_powerloss_page.bin";
static constexpr uint32_t SPOOL_R247_FULL_RECORDS = 2U;
static constexpr uint32_t SPOOL_R247_PARTIAL_RECORD_INDEX = 2U;
static constexpr size_t SPOOL_R247_PARTIAL_BYTES = 40U;
static constexpr size_t SPOOL_R247_RECOVERY_MAX_RECORDS = 3U;
static constexpr uint32_t SPOOL_R247_WINDOW_MS = 15000UL;
static constexpr size_t SPOOL_R247_PRE_CUT_BYTES =
    SPOOL_HEADER_BYTES + (size_t)SPOOL_R247_FULL_RECORDS * SPOOL_RECORD_BYTES + SPOOL_R247_PARTIAL_BYTES;
static_assert(SPOOL_R247_PRE_CUT_BYTES == 272U, "R247 pre-cut geometry changed");

static bool spoolR247WritePowerLossPage(String &resultOut) {
  resultOut = "";
  if (!littlefsReady) { resultOut = "LittleFS nie gotowy"; return false; }
  if (!logMutex || xSemaphoreTake(logMutex, pdMS_TO_TICKS(200)) != pdTRUE) {
    resultOut = "logMutex niedostepny >200ms";
    return false;
  }
  if (!spoolR245EnsureDir()) {
    xSemaphoreGive(logMutex);
    resultOut = "Nie utworzono katalogu /telemetry_spool";
    return false;
  }
  if (LittleFS.exists(SPOOL_R247_POWER_FILE)) LittleFS.remove(SPOOL_R247_POWER_FILE);

  File f = LittleFS.open(SPOOL_R247_POWER_FILE, "w");
  if (!f) {
    xSemaphoreGive(logMutex);
    resultOut = "open R247 do zapisu nieudany";
    return false;
  }

  SpoolPageHeader header{};
  header.magic = SPOOL_PAGE_MAGIC;
  header.formatVersion = SPOOL_PAGE_FORMAT_VERSION;
  header.headerBytes = (uint16_t)SPOOL_HEADER_BYTES;
  header.pageSeq = ((uint64_t)millis() << 16) | (uint64_t)0x247U;
  header.firstSampleSeq = 0xF2470001ULL;
  header.recordBytes = (uint16_t)SPOOL_RECORD_BYTES;
  header.capacity = (uint16_t)SPOOL_64K_SAFE_RECORDS;
  header.flags = 0x52424701UL; // test marker only: R247 power-loss harness
  header.firstUnixTs = 0U;
  header.firstMonoMs = millis();
  header.headerCrc32 = spoolR245HeaderCrc(header);

  if (f.write(reinterpret_cast<const uint8_t*>(&header), sizeof(header)) != sizeof(header)) {
    f.close();
    xSemaphoreGive(logMutex);
    resultOut = "write header nieudany";
    return false;
  }
  f.flush();

  uint8_t recBytes[SPOOL_RECORD_BYTES] = {};
  for (uint32_t i = 0; i < SPOOL_R247_FULL_RECORDS; ++i) {
    TelemetrySample sample{};
    if (!spoolR245BuildSample(i, sample)) {
      f.close(); xSemaphoreGive(logMutex);
      resultOut = "build pelnego rekordu nieudany";
      return false;
    }
    sample.sampleSeq = 0xF2470000UL + i + 1U;
    memcpy(recBytes, &sample, sizeof(TelemetrySample));
    const uint32_t recordCrc = spoolR245Crc32(recBytes, sizeof(TelemetrySample));
    memcpy(recBytes + sizeof(TelemetrySample), &recordCrc, sizeof(recordCrc));
    if (f.write(recBytes, sizeof(recBytes)) != sizeof(recBytes)) {
      f.close(); xSemaphoreGive(logMutex);
      resultOut = "write pelnego rekordu nieudany";
      return false;
    }
    f.flush();
  }

  TelemetrySample partialSample{};
  if (!spoolR245BuildSample(SPOOL_R247_PARTIAL_RECORD_INDEX, partialSample)) {
    f.close(); xSemaphoreGive(logMutex);
    resultOut = "build czesciowego rekordu nieudany";
    return false;
  }
  partialSample.sampleSeq = 0xF2470000UL + SPOOL_R247_PARTIAL_RECORD_INDEX + 1U;
  memcpy(recBytes, &partialSample, sizeof(TelemetrySample));
  const uint32_t partialCrc = spoolR245Crc32(recBytes, sizeof(TelemetrySample));
  memcpy(recBytes + sizeof(TelemetrySample), &partialCrc, sizeof(partialCrc));

  if (f.write(recBytes, SPOOL_R247_PARTIAL_BYTES) != SPOOL_R247_PARTIAL_BYTES) {
    f.close(); xSemaphoreGive(logMutex);
    resultOut = "write pierwszego fragmentu rekordu nieudany";
    return false;
  }
  f.flush();
  const size_t armedSize = f.size();
  xSemaphoreGive(logMutex);

  if (armedSize != SPOOL_R247_PRE_CUT_BYTES) {
    f.close();
    resultOut = "R247 zly rozmiar ARM: expected=" + String((unsigned long)SPOOL_R247_PRE_CUT_BYTES) +
                " actual=" + String((unsigned long)armedSize);
    return false;
  }

  sendTelegramMessage(String("R247 READY: plik ") + SPOOL_R247_POWER_FILE +
                      " ma size=" + String((unsigned long)armedSize) +
                      " B. Odlacz zasilanie TESTOWEJ plytki teraz (okno 15 s). "
                      "Po restarcie NIE wpisuj /spool247, tylko /spool247recover.");

  const uint32_t startMs = millis();
  while ((uint32_t)(millis() - startMs) < SPOOL_R247_WINDOW_MS) {
    delay(100);
  }

  // Jesli zasilania nie odlaczono, domykamy sztucznie przerwany rekord, ale bez footeru.
  // To nie jest PASS power-loss; sluzby tylko sprzataja harness przed kolejnym testem.
  if (logMutex) xSemaphoreTake(logMutex, pdMS_TO_TICKS(200));
  const size_t remainingBytes = SPOOL_RECORD_BYTES - SPOOL_R247_PARTIAL_BYTES;
  if (f.write(recBytes + SPOOL_R247_PARTIAL_BYTES, remainingBytes) != remainingBytes) {
    f.close();
    if (logMutex) xSemaphoreGive(logMutex);
    resultOut = "okno wygaslo, ale dopisanie reszty rekordu nieudane";
    return false;
  }
  f.flush();
  const size_t finalSize = f.size();
  f.close();
  if (logMutex) xSemaphoreGive(logMutex);

  resultOut = "okno 15 s wygaslo bez power loss; stan testowy zostal domkniety bez footeru, size=" +
              String((unsigned long)finalSize) + " B";
  return false;
}

static bool spoolR247RecoverPowerLossPage(String &resultOut) {
  resultOut = "";
  if (!littlefsReady) { resultOut = "LittleFS nie gotowy"; return false; }
  if (!logMutex || xSemaphoreTake(logMutex, pdMS_TO_TICKS(200)) != pdTRUE) {
    resultOut = "logMutex niedostepny >200ms";
    return false;
  }

  File f = LittleFS.open(SPOOL_R247_POWER_FILE, "r");
  if (!f) {
    xSemaphoreGive(logMutex);
    resultOut = "brak pliku R247 — najpierw /spool247 TAK i power loss";
    return false;
  }

  const size_t actualSize = f.size();
  bool headerOk = false;
  uint32_t validRecords = 0U;
  size_t tailBytes = 0U;
  bool badCompleteRecord = false;
  SpoolPageHeader header{};

  if (f.readBytes(reinterpret_cast<char*>(&header), sizeof(header)) == (int)sizeof(header)) {
    headerOk = header.magic == SPOOL_PAGE_MAGIC &&
               header.formatVersion == SPOOL_PAGE_FORMAT_VERSION &&
               header.headerBytes == SPOOL_HEADER_BYTES &&
               header.recordBytes == SPOOL_RECORD_BYTES &&
               header.capacity == SPOOL_64K_SAFE_RECORDS &&
               header.firstSampleSeq == 0xF2470001ULL &&
               header.flags == 0x52424701UL &&
               header.headerCrc32 == spoolR245HeaderCrc(header);
  }

  uint8_t recBytes[SPOOL_RECORD_BYTES] = {};
  while (headerOk && validRecords < SPOOL_R247_RECOVERY_MAX_RECORDS) {
    const size_t pos = (size_t)f.position();
    if (pos >= actualSize) break;
    const size_t remaining = actualSize - pos;
    if (remaining < SPOOL_RECORD_BYTES) {
      tailBytes = remaining;
      break;
    }
    if (f.readBytes(reinterpret_cast<char*>(recBytes), sizeof(recBytes)) != (int)sizeof(recBytes)) {
      tailBytes = remaining;
      break;
    }
    uint32_t storedCrc = 0U;
    memcpy(&storedCrc, recBytes + sizeof(TelemetrySample), sizeof(storedCrc));
    const uint32_t calcCrc = spoolR245Crc32(recBytes, sizeof(TelemetrySample));
    if (storedCrc != calcCrc) {
      badCompleteRecord = true;
      tailBytes = remaining;
      break;
    }
    ++validRecords;
  }

  const size_t consumedBytes = SPOOL_HEADER_BYTES + (size_t)validRecords * SPOOL_RECORD_BYTES;
  if (actualSize >= consumedBytes && tailBytes == 0U) {
    tailBytes = actualSize - consumedBytes;
  }

  // R247 nie uznaje pliku z pelnym, ale uszkodzonym rekordem za czyste recovery.
  // Akceptujemy natomiast brak tailu lub niepelny ogon < jednego rekordu.
  const bool sizeEnvelope = actualSize >= SPOOL_HEADER_BYTES &&
                            actualSize <= SPOOL_HEADER_BYTES +
                                         SPOOL_R247_RECOVERY_MAX_RECORDS * SPOOL_RECORD_BYTES;
  const bool noFooter = actualSize < (SPOOL_HEADER_BYTES + SPOOL_R247_RECOVERY_MAX_RECORDS * SPOOL_RECORD_BYTES + SPOOL_FOOTER_BYTES);
  const bool recoverable = headerOk && validRecords >= SPOOL_R247_FULL_RECORDS &&
                           !badCompleteRecord && sizeEnvelope && noFooter && tailBytes < SPOOL_RECORD_BYTES;

  f.close();
  xSemaphoreGive(logMutex);

  if (!recoverable) {
    resultOut = "recovery FAIL: size=" + String((unsigned long)actualSize) +
                " validRecords=" + String((unsigned)validRecords) +
                " tail=" + String((unsigned long)tailBytes) +
                " headerCRC=" + String(headerOk ? "OK" : "FAIL") +
                " badCompleteRecord=" + String(badCompleteRecord ? "YES" : "NO") +
                " footer=ABSENT";
    return false;
  }

  resultOut = "recovery OK: size=" + String((unsigned long)actualSize) +
              " validRecords=" + String((unsigned)validRecords) +
              " tail=" + String((unsigned long)tailBytes) + "B" +
              " headerCRC=OK recordCRC=OK footer=ABSENT open=RECOVERABLE";
  return true;
}


// ============================================================================
// [R248 LOCAL] Persistent Spool V2 — recovery prefiksu + bezpieczna kontynuacja.
// Wejscie testowe: plik R247 po rzeczywistym power-loss, 272 B = header 64 B +
// 2 x 84 B pelne rekordy + 40 B niepelnego ogona. Najpierw walidujemy prefiks,
// potem budujemy nowy plik .part z 2 zachowanymi rekordami + nowym rekordem #3.
// Po flush/close/reopen i pelnej walidacji CRC dopiero podmieniamy plik testowy.
// TYLKO lokalny harness; bez integracji z normalnym spoolem produkcyjnym.
// ============================================================================
static constexpr char SPOOL_R248_PART_FILE[] = "/telemetry_spool/r248_repaired_page.bin.part";
static constexpr size_t SPOOL_R248_INPUT_BYTES = SPOOL_HEADER_BYTES + 2U * SPOOL_RECORD_BYTES + SPOOL_R247_PARTIAL_BYTES;
static constexpr size_t SPOOL_R248_REPAIRED_BYTES = SPOOL_HEADER_BYTES + 3U * SPOOL_RECORD_BYTES;
static_assert(SPOOL_R248_INPUT_BYTES == 272U, "R248 input geometry changed");
static_assert(SPOOL_R248_REPAIRED_BYTES == 316U, "R248 repaired geometry changed");

static bool spoolR248VerifyThreeRecords(const char *path, String &whyOut) {
  File vf = LittleFS.open(path, "r");
  if (!vf) { whyOut = "open verify nieudany"; return false; }
  const size_t sz = vf.size();
  if (sz != SPOOL_R248_REPAIRED_BYTES) {
    vf.close();
    whyOut = "zly rozmiar verify=" + String((unsigned long)sz);
    return false;
  }
  SpoolPageHeader header{};
  const bool readHeader = vf.readBytes(reinterpret_cast<char*>(&header), sizeof(header)) == (int)sizeof(header);
  const bool headerOk = readHeader &&
                        header.magic == SPOOL_PAGE_MAGIC &&
                        header.formatVersion == SPOOL_PAGE_FORMAT_VERSION &&
                        header.headerBytes == SPOOL_HEADER_BYTES &&
                        header.recordBytes == SPOOL_RECORD_BYTES &&
                        header.capacity == SPOOL_64K_SAFE_RECORDS &&
                        header.firstSampleSeq == 0xF2470001ULL &&
                        header.flags == 0x52424701UL &&
                        header.headerCrc32 == spoolR245HeaderCrc(header);
  if (!headerOk) {
    vf.close();
    whyOut = "headerCRC=FAIL";
    return false;
  }
  uint8_t recBytes[SPOOL_RECORD_BYTES] = {};
  for (uint32_t i = 0; i < 3U; ++i) {
    if (vf.readBytes(reinterpret_cast<char*>(recBytes), sizeof(recBytes)) != (int)sizeof(recBytes)) {
      vf.close();
      whyOut = "rekord=" + String((unsigned)(i + 1U)) + " read=FAIL";
      return false;
    }
    uint32_t storedCrc = 0U;
    memcpy(&storedCrc, recBytes + sizeof(TelemetrySample), sizeof(storedCrc));
    const uint32_t calcCrc = spoolR245Crc32(recBytes, sizeof(TelemetrySample));
    if (storedCrc != calcCrc) {
      vf.close();
      whyOut = "rekord=" + String((unsigned)(i + 1U)) + " crc=FAIL";
      return false;
    }
    TelemetrySample sample{};
    memcpy(&sample, recBytes, sizeof(sample));
    const uint32_t expectedSeq = 0xF2470000UL + i + 1U;
    if (sample.sampleSeq != expectedSeq) {
      vf.close();
      whyOut = "rekord=" + String((unsigned)(i + 1U)) + " seq=" + String((unsigned long)sample.sampleSeq) +
               " expected=" + String((unsigned long)expectedSeq);
      return false;
    }
  }
  const bool noFooter = vf.position() == (long)SPOOL_R248_REPAIRED_BYTES;
  vf.close();
  if (!noFooter) { whyOut = "pozycja po 3 rekordach niezgodna"; return false; }
  return true;
}

static bool spoolR248RecoverAndContinue(String &resultOut) {
  resultOut = "";
  if (!littlefsReady) { resultOut = "LittleFS nie gotowy"; return false; }
  if (!logMutex || xSemaphoreTake(logMutex, pdMS_TO_TICKS(200)) != pdTRUE) {
    resultOut = "logMutex niedostepny >200ms";
    return false;
  }
  if (!spoolR245EnsureDir()) {
    xSemaphoreGive(logMutex);
    resultOut = "Nie utworzono katalogu /telemetry_spool";
    return false;
  }

  File src = LittleFS.open(SPOOL_R247_POWER_FILE, "r");
  if (!src) {
    xSemaphoreGive(logMutex);
    resultOut = "brak R247 page — najpierw /spool247 TAK + power loss";
    return false;
  }
  const size_t inputSize = src.size();
  if (inputSize != SPOOL_R248_INPUT_BYTES) {
    src.close();
    xSemaphoreGive(logMutex);
    resultOut = "R248 wymaga wejscia 272 B; jest " + String((unsigned long)inputSize) + " B";
    return false;
  }

  SpoolPageHeader header{};
  const bool readHeader = src.readBytes(reinterpret_cast<char*>(&header), sizeof(header)) == (int)sizeof(header);
  const bool headerOk = readHeader &&
                        header.magic == SPOOL_PAGE_MAGIC &&
                        header.formatVersion == SPOOL_PAGE_FORMAT_VERSION &&
                        header.headerBytes == SPOOL_HEADER_BYTES &&
                        header.recordBytes == SPOOL_RECORD_BYTES &&
                        header.capacity == SPOOL_64K_SAFE_RECORDS &&
                        header.firstSampleSeq == 0xF2470001ULL &&
                        header.flags == 0x52424701UL &&
                        header.headerCrc32 == spoolR245HeaderCrc(header);
  if (!headerOk) {
    src.close();
    xSemaphoreGive(logMutex);
    resultOut = "R248 recovery FAIL: headerCRC=FAIL";
    return false;
  }

  uint8_t recBytes[SPOOL_RECORD_BYTES] = {};
  for (uint32_t i = 0; i < 2U; ++i) {
    if (src.readBytes(reinterpret_cast<char*>(recBytes), sizeof(recBytes)) != (int)sizeof(recBytes)) {
      src.close();
      xSemaphoreGive(logMutex);
      resultOut = "R248 recovery FAIL: pelny rekord #" + String((unsigned)(i + 1U)) + " nieczytelny";
      return false;
    }
    uint32_t storedCrc = 0U;
    memcpy(&storedCrc, recBytes + sizeof(TelemetrySample), sizeof(storedCrc));
    const uint32_t calcCrc = spoolR245Crc32(recBytes, sizeof(TelemetrySample));
    if (storedCrc != calcCrc) {
      src.close();
      xSemaphoreGive(logMutex);
      resultOut = "R248 recovery FAIL: CRC rekordu #" + String((unsigned)(i + 1U)) + "";
      return false;
    }
  }
  const size_t validPrefixBytes = SPOOL_HEADER_BYTES + 2U * SPOOL_RECORD_BYTES;
  if ((size_t)src.position() != validPrefixBytes) {
    src.close();
    xSemaphoreGive(logMutex);
    resultOut = "R248 recovery FAIL: prefiks=" + String((unsigned long)src.position()) + " expected=232";
    return false;
  }
  const size_t discardedTail = inputSize - validPrefixBytes;
  if (discardedTail != SPOOL_R247_PARTIAL_BYTES) {
    src.close();
    xSemaphoreGive(logMutex);
    resultOut = "R248 recovery FAIL: tail=" + String((unsigned long)discardedTail) + " expected=40B";
    return false;
  }
  src.close();

  LittleFS.remove(SPOOL_R248_PART_FILE);
  File part = LittleFS.open(SPOOL_R248_PART_FILE, "w");
  if (!part) {
    xSemaphoreGive(logMutex);
    resultOut = "open .part R248 nieudany";
    return false;
  }
  if (part.write(reinterpret_cast<const uint8_t*>(&header), sizeof(header)) != sizeof(header)) {
    part.close();
    LittleFS.remove(SPOOL_R248_PART_FILE);
    xSemaphoreGive(logMutex);
    resultOut = "write header do .part nieudany";
    return false;
  }

  // Odczyt zachowanych 2 rekordow z oryginalnego pliku i zapis do .part.
  File src2 = LittleFS.open(SPOOL_R247_POWER_FILE, "r");
  if (!src2) {
    part.close(); LittleFS.remove(SPOOL_R248_PART_FILE); xSemaphoreGive(logMutex);
    resultOut = "reopen R247 do kopiowania nieudany";
    return false;
  }
  if (!src2.seek(SPOOL_HEADER_BYTES)) {
    src2.close(); part.close(); LittleFS.remove(SPOOL_R248_PART_FILE); xSemaphoreGive(logMutex);
    resultOut = "seek R247 po headerze nieudany";
    return false;
  }
  for (uint32_t i = 0; i < 2U; ++i) {
    if (src2.readBytes(reinterpret_cast<char*>(recBytes), sizeof(recBytes)) != (int)sizeof(recBytes)) {
      src2.close(); part.close(); LittleFS.remove(SPOOL_R248_PART_FILE); xSemaphoreGive(logMutex);
      resultOut = "copy rekordu #" + String((unsigned)(i + 1U)) + " nieudane";
      return false;
    }
    if (part.write(recBytes, sizeof(recBytes)) != sizeof(recBytes)) {
      src2.close(); part.close(); LittleFS.remove(SPOOL_R248_PART_FILE); xSemaphoreGive(logMutex);
      resultOut = "write zachowanego rekordu #" + String((unsigned)(i + 1U)) + " nieudany";
      return false;
    }
  }
  src2.close();

  // Nowy, pelny rekord #3: ten sam sampleSeq, ktory mial niedokonczony ogon.
  TelemetrySample continued{};
  if (!spoolR245BuildSample(3U, continued)) {
    part.close(); LittleFS.remove(SPOOL_R248_PART_FILE); xSemaphoreGive(logMutex);
    resultOut = "build nowego rekordu #3 nieudany";
    return false;
  }
  continued.sampleSeq = 0xF2470003UL;
  memset(recBytes, 0, sizeof(recBytes));
  memcpy(recBytes, &continued, sizeof(continued));
  const uint32_t recordCrc = spoolR245Crc32(recBytes, sizeof(TelemetrySample));
  memcpy(recBytes + sizeof(TelemetrySample), &recordCrc, sizeof(recordCrc));
  if (part.write(recBytes, sizeof(recBytes)) != sizeof(recBytes)) {
    part.close(); LittleFS.remove(SPOOL_R248_PART_FILE); xSemaphoreGive(logMutex);
    resultOut = "write nowego rekordu #3 nieudany";
    return false;
  }
  part.flush();
  const size_t afterFlush = part.size();
  part.close();
  if (afterFlush != SPOOL_R248_REPAIRED_BYTES) {
    LittleFS.remove(SPOOL_R248_PART_FILE); xSemaphoreGive(logMutex);
    resultOut = "zly size po flush .part=" + String((unsigned long)afterFlush) + " expected=316";
    return false;
  }

  String verifyWhy;
  if (!spoolR248VerifyThreeRecords(SPOOL_R248_PART_FILE, verifyWhy)) {
    LittleFS.remove(SPOOL_R248_PART_FILE);
    xSemaphoreGive(logMutex);
    resultOut = "verify .part FAIL: " + verifyWhy;
    return false;
  }

  if (!LittleFS.remove(SPOOL_R247_POWER_FILE)) {
    LittleFS.remove(SPOOL_R248_PART_FILE);
    xSemaphoreGive(logMutex);
    resultOut = "usuniecie starego R247 page nieudane";
    return false;
  }
  if (!LittleFS.rename(SPOOL_R248_PART_FILE, SPOOL_R247_POWER_FILE)) {
    // Probujemy zostawic .part do diagnostyki; nie raportujemy PASS.
    xSemaphoreGive(logMutex);
    resultOut = "rename .part -> R247 page nieudany";
    return false;
  }

  const bool finalOk = spoolR248VerifyThreeRecords(SPOOL_R247_POWER_FILE, verifyWhy);
  const size_t finalSize = [&]() -> size_t {
    File chk = LittleFS.open(SPOOL_R247_POWER_FILE, "r");
    if (!chk) return 0U;
    const size_t s = chk.size();
    chk.close();
    return s;
  }();
  xSemaphoreGive(logMutex);

  if (!finalOk) {
    resultOut = "R248 final verify FAIL: " + verifyWhy;
    return false;
  }
  resultOut = "recovery+continue OK: input=272B validPrefix=232B discardedTail=40B "
              "output=" + String((unsigned long)finalSize) +
              "B records=3 headerCRC=OK recordCRC=OK footer=ABSENT continuedSeq=0xF2470003";
  return true;
}


// ============================================================================
// [R249 LOCAL] Persistent Spool V2 — pełna strona bezpiecznej pojemności.
// Geometria zamrożona: header 64 B + 768 rekordów po 84 B + footer 64 B = 64640 B.
// Test zapisuje najpierw do .part, wykonuje flush/close/reopen, weryfikuje:
// header CRC, CRC każdego rekordu, page payload CRC, footer CRC i commit marker.
// Dopiero po pełnej weryfikacji podmienia finalny plik testowy.
// ============================================================================
static constexpr char SPOOL_R249_FULL_FILE[] = "/telemetry_spool/r249_full_page.bin";
static constexpr char SPOOL_R249_FULL_PART[] = "/telemetry_spool/r249_full_page.bin.part";
static constexpr uint32_t SPOOL_R249_FULL_RECORDS = SPOOL_64K_SAFE_RECORDS;
static constexpr size_t SPOOL_R249_FULL_BYTES =
    SPOOL_HEADER_BYTES + (size_t)SPOOL_R249_FULL_RECORDS * SPOOL_RECORD_BYTES + SPOOL_FOOTER_BYTES;
static_assert(SPOOL_R249_FULL_RECORDS == 768U, "R249 full record count changed");
static_assert(SPOOL_R249_FULL_BYTES == 64640U, "R249 full page geometry changed");

static bool spoolR249VerifyFullPage(const char *path, String &whyOut) {
  whyOut = "";
  File f = LittleFS.open(path, "r");
  if (!f) { whyOut = "open verify nieudany"; return false; }

  const size_t actualSize = f.size();
  if (actualSize != SPOOL_R249_FULL_BYTES) {
    f.close();
    whyOut = "rozmiar=" + String((unsigned long)actualSize) + " expected=64640";
    return false;
  }

  SpoolPageHeader header{};
  if (f.readBytes(reinterpret_cast<char*>(&header), sizeof(header)) != (int)sizeof(header)) {
    f.close();
    whyOut = "read header FAIL";
    return false;
  }

  const bool headerOk =
      header.magic == SPOOL_PAGE_MAGIC &&
      header.formatVersion == SPOOL_PAGE_FORMAT_VERSION &&
      header.headerBytes == SPOOL_HEADER_BYTES &&
      header.recordBytes == SPOOL_RECORD_BYTES &&
      header.capacity == SPOOL_64K_SAFE_RECORDS &&
      header.firstSampleSeq == 0xF2490001ULL &&
      header.flags == 0x52424901UL &&
      header.headerCrc32 == spoolR245HeaderCrc(header);

  if (!headerOk) {
    f.close();
    whyOut = "headerCRC=FAIL";
    return false;
  }

  uint8_t recBytes[SPOOL_RECORD_BYTES] = {};
  uint32_t payloadCrc = 0xFFFFFFFFUL;
  uint32_t validRecords = 0U;
  uint32_t firstSeq = 0U;
  uint32_t lastSeq = 0U;

  while (validRecords < SPOOL_R249_FULL_RECORDS) {
    if (f.readBytes(reinterpret_cast<char*>(recBytes), sizeof(recBytes)) != (int)sizeof(recBytes)) {
      f.close();
      whyOut = "recordRead FAIL at=" + String((unsigned)validRecords);
      return false;
    }

    uint32_t storedCrc = 0U;
    memcpy(&storedCrc, recBytes + sizeof(TelemetrySample), sizeof(storedCrc));
    const uint32_t calcCrc = spoolR245Crc32(recBytes, sizeof(TelemetrySample));
    if (storedCrc != calcCrc) {
      f.close();
      whyOut = "recordCRC FAIL at=" + String((unsigned)(validRecords + 1U));
      return false;
    }

    TelemetrySample sample{};
    memcpy(&sample, recBytes, sizeof(sample));
    const uint32_t expectedSeq = 0xF2490000UL + validRecords + 1U;
    if (sample.sampleSeq != expectedSeq) {
      f.close();
      whyOut = "seq FAIL at=" + String((unsigned)(validRecords + 1U)) +
               " got=" + String((unsigned long)sample.sampleSeq) +
               " expected=" + String((unsigned long)expectedSeq);
      return false;
    }

    if (validRecords == 0U) firstSeq = sample.sampleSeq;
    lastSeq = sample.sampleSeq;

    for (size_t j = 0; j < sizeof(recBytes); ++j) {
      payloadCrc ^= recBytes[j];
      for (uint8_t b = 0; b < 8U; ++b) {
        payloadCrc = (payloadCrc >> 1) ^ ((payloadCrc & 1U) ? 0xEDB88320UL : 0U);
      }
    }

    ++validRecords;
  }
  payloadCrc = ~payloadCrc;

  SpoolPageFooter footer{};
  if (f.readBytes(reinterpret_cast<char*>(&footer), sizeof(footer)) != (int)sizeof(footer)) {
    f.close();
    whyOut = "read footer FAIL";
    return false;
  }

  const bool footerOk =
      footer.magic == SPOOL_PAGE_MAGIC &&
      footer.formatVersion == SPOOL_PAGE_FORMAT_VERSION &&
      footer.footerBytes == SPOOL_FOOTER_BYTES &&
      footer.pageSeq == header.pageSeq &&
      footer.firstSampleSeq == header.firstSampleSeq &&
      footer.lastSampleSeq == (uint64_t)lastSeq &&
      footer.recordCount == SPOOL_R249_FULL_RECORDS &&
      footer.payloadCrc32 == payloadCrc &&
      footer.commitMarker == SPOOL_PAGE_COMMIT_MARKER &&
      footer.footerCrc32 == spoolR245FooterCrc(footer);

  const bool exactEnd = f.position() == (long)SPOOL_R249_FULL_BYTES;
  f.close();

  if (!footerOk) {
    whyOut = "footerCommit=FAIL";
    return false;
  }
  if (!exactEnd) {
    whyOut = "pozycja konca FAIL";
    return false;
  }

  return validRecords == SPOOL_R249_FULL_RECORDS && firstSeq == 0xF2490001UL;
}

static bool spoolR249WriteAndVerifyFullPage(String &resultOut) {
  resultOut = "";
  if (!littlefsReady) { resultOut = "LittleFS nie gotowy"; return false; }

  FsQuotaHard quotaHard;
  if (!fsQuotaHardEvaluate(quotaHard)) {
    resultOut = "FS quota hard: stan LOW / brak mozliwosci zapisu";
    return false;
  }
  if (quotaHard.availableQuotaBytes < SPOOL_R249_FULL_BYTES) {
    resultOut = "Za malo quota hard na pelna strone 64640 B";
    return false;
  }

  if (!logMutex || xSemaphoreTake(logMutex, pdMS_TO_TICKS(200)) != pdTRUE) {
    resultOut = "logMutex niedostepny >200ms";
    return false;
  }

  if (!spoolR245EnsureDir()) {
    xSemaphoreGive(logMutex);
    resultOut = "Nie utworzono katalogu /telemetry_spool";
    return false;
  }

  LittleFS.remove(SPOOL_R249_FULL_PART);

  File f = LittleFS.open(SPOOL_R249_FULL_PART, "w");
  if (!f) {
    xSemaphoreGive(logMutex);
    resultOut = "open .part R249 nieudany";
    return false;
  }

  SpoolPageHeader header{};
  header.magic = SPOOL_PAGE_MAGIC;
  header.formatVersion = SPOOL_PAGE_FORMAT_VERSION;
  header.headerBytes = (uint16_t)SPOOL_HEADER_BYTES;
  header.pageSeq = ((uint64_t)millis() << 16) | (uint64_t)0x249U;
  header.firstSampleSeq = 0xF2490001ULL;
  header.recordBytes = (uint16_t)SPOOL_RECORD_BYTES;
  header.capacity = (uint16_t)SPOOL_64K_SAFE_RECORDS;
  header.flags = 0x52424901UL;
  header.firstUnixTs = 0U;
  header.firstMonoMs = millis();
  header.headerCrc32 = spoolR245HeaderCrc(header);

  if (f.write(reinterpret_cast<const uint8_t*>(&header), sizeof(header)) != sizeof(header)) {
    f.close();
    LittleFS.remove(SPOOL_R249_FULL_PART);
    xSemaphoreGive(logMutex);
    resultOut = "write header .part nieudany";
    return false;
  }

  uint8_t recBytes[SPOOL_RECORD_BYTES] = {};
  uint32_t payloadCrc = 0xFFFFFFFFUL;

  for (uint32_t i = 0; i < SPOOL_R249_FULL_RECORDS; ++i) {
    TelemetrySample sample{};
    if (!spoolR245BuildSample(i, sample)) {
      f.close();
      LittleFS.remove(SPOOL_R249_FULL_PART);
      xSemaphoreGive(logMutex);
      resultOut = "build rekordu #" + String((unsigned)(i + 1U)) + " nieudany";
      return false;
    }

    sample.sampleSeq = 0xF2490000UL + i + 1U;
    memcpy(recBytes, &sample, sizeof(TelemetrySample));
    const uint32_t recordCrc = spoolR245Crc32(recBytes, sizeof(TelemetrySample));
    memcpy(recBytes + sizeof(TelemetrySample), &recordCrc, sizeof(recordCrc));

    if (f.write(recBytes, sizeof(recBytes)) != sizeof(recBytes)) {
      f.close();
      LittleFS.remove(SPOOL_R249_FULL_PART);
      xSemaphoreGive(logMutex);
      resultOut = "write rekordu #" + String((unsigned)(i + 1U)) + " nieudany";
      return false;
    }

    for (size_t j = 0; j < sizeof(recBytes); ++j) {
      payloadCrc ^= recBytes[j];
      for (uint8_t b = 0; b < 8U; ++b) {
        payloadCrc = (payloadCrc >> 1) ^ ((payloadCrc & 1U) ? 0xEDB88320UL : 0U);
      }
    }
  }
  payloadCrc = ~payloadCrc;

  SpoolPageFooter footer{};
  footer.magic = SPOOL_PAGE_MAGIC;
  footer.formatVersion = SPOOL_PAGE_FORMAT_VERSION;
  footer.footerBytes = (uint16_t)SPOOL_FOOTER_BYTES;
  footer.pageSeq = header.pageSeq;
  footer.firstSampleSeq = header.firstSampleSeq;
  footer.lastSampleSeq = 0xF2490000ULL + SPOOL_R249_FULL_RECORDS;
  footer.recordCount = SPOOL_R249_FULL_RECORDS;
  footer.payloadCrc32 = payloadCrc;
  footer.commitMarker = SPOOL_PAGE_COMMIT_MARKER;
  footer.footerCrc32 = spoolR245FooterCrc(footer);

  if (f.write(reinterpret_cast<const uint8_t*>(&footer), sizeof(footer)) != sizeof(footer)) {
    f.close();
    LittleFS.remove(SPOOL_R249_FULL_PART);
    xSemaphoreGive(logMutex);
    resultOut = "write footer/commit .part nieudany";
    return false;
  }

  f.flush();
  const size_t afterFlush = f.size();
  f.close();

  File reopened = LittleFS.open(SPOOL_R249_FULL_PART, "r");
  const size_t finalPartSize = reopened ? reopened.size() : 0U;
  if (reopened) reopened.close();

  if (afterFlush != SPOOL_R249_FULL_BYTES || finalPartSize != SPOOL_R249_FULL_BYTES) {
    LittleFS.remove(SPOOL_R249_FULL_PART);
    xSemaphoreGive(logMutex);
    resultOut = "zly rozmiar: expected=64640 afterFlush=" +
                String((unsigned long)afterFlush) +
                " finalPart=" + String((unsigned long)finalPartSize);
    return false;
  }

  String why;
  if (!spoolR249VerifyFullPage(SPOOL_R249_FULL_PART, why)) {
    LittleFS.remove(SPOOL_R249_FULL_PART);
    xSemaphoreGive(logMutex);
    resultOut = "verify .part FAIL: " + why;
    return false;
  }

  if (LittleFS.exists(SPOOL_R249_FULL_FILE) && !LittleFS.remove(SPOOL_R249_FULL_FILE)) {
    xSemaphoreGive(logMutex);
    resultOut = "usuniecie starego R249 final nieudane";
    return false;
  }
  if (!LittleFS.rename(SPOOL_R249_FULL_PART, SPOOL_R249_FULL_FILE)) {
    xSemaphoreGive(logMutex);
    resultOut = "rename .part -> final R249 nieudany";
    return false;
  }

  const bool finalOk = spoolR249VerifyFullPage(SPOOL_R249_FULL_FILE, why);
  File finalCheck = LittleFS.open(SPOOL_R249_FULL_FILE, "r");
  const size_t finalSize = finalCheck ? finalCheck.size() : 0U;
  if (finalCheck) finalCheck.close();

  xSemaphoreGive(logMutex);

  if (!finalOk) {
    resultOut = "final verify FAIL: " + why;
    return false;
  }

  resultOut = "full page OK: size=" + String((unsigned long)finalSize) +
              " records=768 headerCRC=OK recordCRC=OK pageCRC=OK footerCommit=OK";
  return true;
}


// ============================================================================
// [R250 LOCAL] Persistent Spool V2 — negatywny test CRC rekordu.
// Test tworzy 4-rekordowa otwarta strone bez footeru, nastepnie celowo zmienia
// jeden bajt payloadu rekordu #2 bez przeliczania jego CRC. Recovery ma uznac
// rekord #1 za poprawny, rekord #2 za uszkodzony i zatrzymac prefiks na 1.
// TYLKO lokalny harness; bez integracji z normalna telemetryka produkcyjna.
// ============================================================================
static constexpr char SPOOL_R250_FILE[] = "/telemetry_spool/r250_crc_corrupt.bin";
static constexpr uint32_t SPOOL_R250_RECORDS = 4U;
static constexpr size_t SPOOL_R250_BYTES = SPOOL_HEADER_BYTES +
                                           (size_t)SPOOL_R250_RECORDS * SPOOL_RECORD_BYTES;
static_assert(SPOOL_R250_BYTES == 400U, "R250 geometry changed");

static bool spoolR250WriteCorruptRecord(String &resultOut) {
  resultOut = "";
  if (!littlefsReady) { resultOut = "LittleFS nie gotowy"; return false; }
  if (!logMutex || xSemaphoreTake(logMutex, pdMS_TO_TICKS(200)) != pdTRUE) {
    resultOut = "logMutex niedostepny >200ms";
    return false;
  }
  if (!spoolR245EnsureDir()) {
    xSemaphoreGive(logMutex);
    resultOut = "Nie utworzono katalogu /telemetry_spool";
    return false;
  }

  uint8_t page[SPOOL_R250_BYTES] = {};
  SpoolPageHeader header{};
  header.magic = SPOOL_PAGE_MAGIC;
  header.formatVersion = SPOOL_PAGE_FORMAT_VERSION;
  header.headerBytes = (uint16_t)SPOOL_HEADER_BYTES;
  header.pageSeq = ((uint64_t)millis() << 16) | (uint64_t)0x250U;
  header.firstSampleSeq = 0xF2500001ULL;
  header.recordBytes = (uint16_t)SPOOL_RECORD_BYTES;
  header.capacity = (uint16_t)SPOOL_64K_SAFE_RECORDS;
  header.flags = 0x52425001UL;
  header.firstUnixTs = 0U;
  header.firstMonoMs = millis();
  header.headerCrc32 = spoolR245HeaderCrc(header);
  memcpy(page, &header, sizeof(header));

  uint8_t recBytes[SPOOL_RECORD_BYTES] = {};
  for (uint32_t i = 0; i < SPOOL_R250_RECORDS; ++i) {
    TelemetrySample sample{};
    if (!spoolR245BuildSample(i, sample)) {
      xSemaphoreGive(logMutex);
      resultOut = "build rekordu #" + String((unsigned)(i + 1U)) + " nieudany";
      return false;
    }
    sample.sampleSeq = 0xF2500000UL + i + 1U;
    memset(recBytes, 0, sizeof(recBytes));
    memcpy(recBytes, &sample, sizeof(TelemetrySample));
    const uint32_t recordCrc = spoolR245Crc32(recBytes, sizeof(TelemetrySample));
    memcpy(recBytes + sizeof(TelemetrySample), &recordCrc, sizeof(recordCrc));
    memcpy(page + SPOOL_HEADER_BYTES + (size_t)i * SPOOL_RECORD_BYTES,
           recBytes, sizeof(recBytes));
  }

  // Celowo uszkadzamy jeden bajt payloadu rekordu #2. CRC pozostaje stare.
  const size_t corruptOffset = SPOOL_HEADER_BYTES + SPOOL_RECORD_BYTES + 7U;
  page[corruptOffset] ^= 0x5AU;

  LittleFS.remove(SPOOL_R250_FILE);
  File f = LittleFS.open(SPOOL_R250_FILE, "w");
  if (!f) {
    xSemaphoreGive(logMutex);
    resultOut = "open R250 nieudany";
    return false;
  }
  const size_t written = f.write(page, sizeof(page));
  f.flush();
  const size_t afterFlush = f.size();
  f.close();

  File reopened = LittleFS.open(SPOOL_R250_FILE, "r");
  const size_t finalSize = reopened ? reopened.size() : 0U;
  if (reopened) reopened.close();
  xSemaphoreGive(logMutex);

  if (written != sizeof(page) || afterFlush != SPOOL_R250_BYTES || finalSize != SPOOL_R250_BYTES) {
    resultOut = "zly size/write: written=" + String((unsigned long)written) +
                " afterFlush=" + String((unsigned long)afterFlush) +
                " final=" + String((unsigned long)finalSize) + " expected=400";
    return false;
  }

  resultOut = "corrupted page prepared: size=400 records=4 corruptRecord=2 corruptOffset=" +
              String((unsigned long)corruptOffset) + " footer=ABSENT";
  return true;
}

static bool spoolR250RecoverCorruptRecord(String &resultOut) {
  resultOut = "";
  if (!littlefsReady) { resultOut = "LittleFS nie gotowy"; return false; }
  if (!logMutex || xSemaphoreTake(logMutex, pdMS_TO_TICKS(200)) != pdTRUE) {
    resultOut = "logMutex niedostepny >200ms";
    return false;
  }
  File f = LittleFS.open(SPOOL_R250_FILE, "r");
  if (!f) {
    xSemaphoreGive(logMutex);
    resultOut = "brak R250 page — najpierw /spool250 TAK";
    return false;
  }
  const size_t actualSize = f.size();
  if (actualSize != SPOOL_R250_BYTES) {
    f.close();
    xSemaphoreGive(logMutex);
    resultOut = "R250 size=" + String((unsigned long)actualSize) + " expected=400";
    return false;
  }

  SpoolPageHeader header{};
  const bool readHeader = f.readBytes(reinterpret_cast<char*>(&header), sizeof(header)) == (int)sizeof(header);
  const bool headerOk = readHeader &&
                        header.magic == SPOOL_PAGE_MAGIC &&
                        header.formatVersion == SPOOL_PAGE_FORMAT_VERSION &&
                        header.headerBytes == SPOOL_HEADER_BYTES &&
                        header.recordBytes == SPOOL_RECORD_BYTES &&
                        header.capacity == SPOOL_64K_SAFE_RECORDS &&
                        header.firstSampleSeq == 0xF2500001ULL &&
                        header.flags == 0x52425001UL &&
                        header.headerCrc32 == spoolR245HeaderCrc(header);
  if (!headerOk) {
    f.close();
    xSemaphoreGive(logMutex);
    resultOut = "R250 recovery FAIL: headerCRC=FAIL";
    return false;
  }

  uint8_t recBytes[SPOOL_RECORD_BYTES] = {};
  uint32_t validPrefix = 0U;
  uint32_t badRecord = 0U;
  for (uint32_t i = 0; i < SPOOL_R250_RECORDS; ++i) {
    if (f.readBytes(reinterpret_cast<char*>(recBytes), sizeof(recBytes)) != (int)sizeof(recBytes)) {
      break;
    }
    uint32_t storedCrc = 0U;
    memcpy(&storedCrc, recBytes + sizeof(TelemetrySample), sizeof(storedCrc));
    const uint32_t calcCrc = spoolR245Crc32(recBytes, sizeof(TelemetrySample));
    if (storedCrc != calcCrc) {
      badRecord = i + 1U;
      break;
    }
    TelemetrySample sample{};
    memcpy(&sample, recBytes, sizeof(sample));
    const uint32_t expectedSeq = 0xF2500000UL + i + 1U;
    if (sample.sampleSeq != expectedSeq) {
      badRecord = i + 1U;
      break;
    }
    ++validPrefix;
  }

  const bool expectedNegativeRecovery =
      headerOk && validPrefix == 1U && badRecord == 2U &&
      f.position() == (long)(SPOOL_HEADER_BYTES + 2U * SPOOL_RECORD_BYTES);
  f.close();
  xSemaphoreGive(logMutex);

  if (!expectedNegativeRecovery) {
    resultOut = "R250 recovery FAIL: validPrefix=" + String((unsigned)validPrefix) +
                " badRecord=" + String((unsigned)badRecord) +
                " headerCRC=OK";
    return false;
  }

  resultOut = "negative recovery OK: size=400 validPrefix=1 badRecord=2 "
              "headerCRC=OK record1CRC=OK record2CRC=FAIL footer=ABSENT "
              "recovery=REJECT_BAD_RECORD";
  return true;
}



// ============================================================================
// [R251 LOCAL] Hard quota boundary — admission only, no bulk filesystem fill.
// Test verifies:
//   1) request exactly equal to available quota is ADMITTED,
//   2) request one byte above available quota is REJECTED,
//   3) a normal Spool V2 64 KiB safe page is admitted only when quota permits.
// This is a local diagnostic and does not alter production telemetry behavior.
// ============================================================================
static constexpr size_t SPOOL_R251_PROBE_PAGE_BYTES = 64640U; // 768-record safe page

static bool spoolR251QuotaBoundary(String &resultOut) {
  resultOut = "";
  if (!littlefsReady) {
    resultOut = "LittleFS nie gotowy";
    return false;
  }

  FsQuotaHard q;
  if (!fsQuotaHardEvaluate(q) || !q.valid) {
    resultOut = "FS quota hard: snapshot niedostepny";
    return false;
  }

  size_t freeBytes = 0, protectedBytes = 0, quotaBytes = 0;

  const bool exactAdmitted =
      fsQuotaTelemetryAdmission(q.availableQuotaBytes, freeBytes, protectedBytes, quotaBytes);

  const size_t overRequest = q.availableQuotaBytes + 1U;
  const bool overAdmitted =
      fsQuotaTelemetryAdmission(overRequest, freeBytes, protectedBytes, quotaBytes);

  const bool exactBoundaryOk = exactAdmitted;
  const bool overBoundaryOk = !overAdmitted;

  size_t pageFree = 0, pageProtected = 0, pageQuota = 0;
  const bool pageAdmitted =
      fsQuotaTelemetryAdmission(SPOOL_R251_PROBE_PAGE_BYTES, pageFree, pageProtected, pageQuota);

  if (!exactBoundaryOk || !overBoundaryOk) {
    resultOut = "quota boundary FAIL: quota=" +
                String((unsigned long)q.availableQuotaBytes) +
                " exact=" + String(exactAdmitted ? "ADMIT" : "REJECT") +
                " over1=" + String(overAdmitted ? "ADMIT" : "REJECT") +
                " free=" + String((unsigned long)q.freeBytes) +
                " protected=" + String((unsigned long)q.protectedReserveBytes);
    return false;
  }

  resultOut = "quota boundary OK: free=" +
              String((unsigned long)q.freeBytes) +
              " protected=" +
              String((unsigned long)q.protectedReserveBytes) +
              " quota=" +
              String((unsigned long)q.availableQuotaBytes) +
              " exact=ADMIT over1=REJECT page64640=" +
              String(pageAdmitted ? "ADMIT" : "REJECT");
  return true;
}

String buildTelegramTelemetryDiagReport() {
  String s;
  s.reserve(1800);
  const unsigned long nowMs = millis();
  const uint32_t pending = g_telemetryRing.ready() ? g_telemetryRing.size() : 0U;
  const uint32_t capacity = g_telemetryRing.capacity();

  s += F("<b>Diagnostyka telemetryki</b>\n");
  s += F("Ring: ");
  s += g_telemetryRing.ready() ? F("OK") : F("BLAD");
  s += F(" - ");
  s += String((unsigned)pending);
  s += F("/");
  s += String((unsigned)capacity);
  s += F(" probek");
  s += F("\nPamiec ringu: ");
  s += String((unsigned long)g_telemetryRing.bytes());
  s += F(" B");

  FsUsageSnapshot fs;
  if (fsAccountingSnapshot(fs)) {
    s += F("\nFS fizyczny: used=");
    s += String((unsigned long)fs.usedBytes);
    s += F(" B / total=");
    s += String((unsigned long)fs.totalBytes);
    s += F(" B / free=");
    s += String((unsigned long)fs.freeBytes);
    s += F(" B");
    s += F("\nFS logiczny: ");
    s += String((unsigned long)fs.logicalBytes);
    s += F(" B");
    long long diff = (long long)fs.usedBytes - (long long)fs.logicalBytes;
    s += F("\nRoznica used-logiczny: ");
    s += String(diff);
    s += F(" B");
    s += F("\nFS skladniki: logi=");
    s += String((unsigned long)fs.logsBytes);
    s += F(" B ustawienia=");
    s += String((unsigned long)fs.settingsBytes);
    s += F(" B histS=");
    s += String((unsigned long)fs.histShortBytes);
    s += F(" B histL=");
    s += String((unsigned long)fs.histLongBytes);
    s += F(" B panel=");
    s += String((unsigned long)fs.panelFirmwareBytes);
    s += F(" B coredump=");
    s += String((unsigned long)fs.coredumpBytes);
    s += F(" B/");
    s += String((unsigned)fs.coredumpFileCount);
    s += F(" plikow");
  } else {
    s += F("\nFS: niedostepny");
  }

  FsQuotaShadow quotaShadow;
  if (fsQuotaShadowEvaluate(quotaShadow)) {
    s += F("\nFS quota shadow: free=");
    s += String((unsigned long)quotaShadow.freeBytes);
    s += F(" B / rezerwa=");
    s += String((unsigned long)quotaShadow.reservedBytes);
    s += F(" B / po_rezerwach=");
    s += String((unsigned long)quotaShadow.operatingFreeAfterReserveBytes);
    s += F(" B / status=");
    s += quotaShadow.ok ? F("OK") : F("LOW");
  }

  FsQuotaDynamic quotaDynamic;
  if (fsQuotaDynamicEvaluate(quotaDynamic)) {
    s += F("\nFS quota dynamic: pozostala_rezerwa=");
    s += String((unsigned long)quotaDynamic.protectedReserveRemainingBytes);
    s += F(" B / headroom=");
    s += String((unsigned long)quotaDynamic.planningHeadroomBytes);
    s += F(" B / core=");
    s += String((unsigned long)quotaDynamic.coredumpReserveRemainingBytes);
    s += F(" B / histS=");
    s += String((unsigned long)quotaDynamic.histShortReserveRemainingBytes);
    s += F(" B / histL=");
    s += String((unsigned long)quotaDynamic.histLongReserveRemainingBytes);
    s += F(" B / panel=OPEN / status=");
    s += quotaDynamic.ok ? F("OK") : F("LOW");
  }

  FsQuotaHard quotaHard;
  if (fsQuotaHardEvaluate(quotaHard)) {
    s += F("\nFS quota hard: chronione=");
    s += String((unsigned long)quotaHard.protectedReserveBytes);
    s += F(" B / quota=");
    s += String((unsigned long)quotaHard.availableQuotaBytes);
    s += F(" B / panelPozostalo=");
    s += String((unsigned long)quotaHard.panelReserveRemainingBytes);
    s += F(" B / status=");
    s += quotaHard.ok ? F("OK") : F("LOW");
  }

  // [R242] Read-only benchmark — zero write do LittleFS.
  s += F("\nSpool V2 benchmark: rekord=");
  s += String((unsigned)SPOOL_RECORD_BYTES);
  s += F(" B (sample=");
  s += String((unsigned)sizeof(TelemetrySample));
  s += F(" + crc=4), meta=");
  s += String((unsigned)SPOOL_META_BYTES);
  s += F(" B");
  const size_t spoolPages[] = {SPOOL_PAGE_32K, SPOOL_PAGE_48K, SPOOL_PAGE_64K};
  const char* spoolNames[] = {"32K", "48K", "64K"};
  for (size_t i = 0; i < 3; ++i) {
    const uint32_t maxRec = spoolMaxRecordsForPage(spoolPages[i]);
    const size_t used = spoolUsedBytes(spoolPages[i], maxRec);
    const size_t slack = spoolPages[i] - used;
    s += F("\n  ");
    s += spoolNames[i];
    s += F(": max=");
    s += String((unsigned)maxRec);
    s += F(" rec / used=");
    s += String((unsigned long)used);
    s += F(" B / slack=");
    s += String((unsigned long)slack);
    s += F(" B");
  }
  s += F("\n  64K safe=768 rec / used=");
  s += String((unsigned long)spoolUsedBytes(SPOOL_PAGE_64K, SPOOL_64K_SAFE_RECORDS));
  s += F(" B / slack=");
  s += String((unsigned long)(SPOOL_PAGE_64K - spoolUsedBytes(SPOOL_PAGE_64K, SPOOL_64K_SAFE_RECORDS)));
  s += F(" B / coverage=12h48m");
  s += F("\nSpool V2 format: header=64 B / record=84 B / footer=64 B / safe=768 / crc=record+page / commit=footer");
  s += F("\nR245 local test: /spooltest TAK = write+commit, /spoolverify = read+verify");

  s += F("\nSpool V2 R246: open-page test /spoolopen TAK -> /spoolrecover");
  s += F("\nSpool V2 R247: power-loss test /spool247 TAK -> odciecie zasilania -> /spool247recover");
  s += F("\nSpool V2 R252: real telemetry mirror /spool252 TAK -> 3 probki -> /spool252verify");
  s += F("\nSpool V2 batch R253-R262: /spoolbatch TAK (tylko lokalna plytka)");
  s += F("\nSpool V2 batch R263-R272: /spoolbatch2 TAK (tylko lokalna plytka)");
  s += F("\nSpool V2 batch R273-R282: /spoolbatch3 TAK (tylko lokalna plytka)");
  s += F("\nSecurity H1 R335-R344: /securityh TAK (tylko lokalna plytka)");
  s += F("\nSpool V2 replay batch R301-R312: /spoolreplay TAK (tylko lokalna plytka)");
  s += F("\nSpool V2 fault batch R313-R324: /spoolfault TAK (tylko lokalna plytka)");
  s += F("\nProdukcja: ");
  s += String((unsigned long)g_telemetrySamplesProduced);
  s += F("\nWyslane: ");
  s += String((unsigned long)g_telemetrySamplesSent);
  s += F("\nDrop: ");
  s += String((unsigned long)g_telemetrySamplesDropped);
  s += F("\nBledy transportu: ");
  s += String((unsigned long)g_telemetryTransportFailures);
  s += F("\nRequest aktywny: ");
  s += g_telemetryRequestActive ? F("TAK") : F("NIE");

  if (g_telemetryLastAttemptMillis != 0U) {
    s += F("\nOstatnia proba: ");
    s += String((unsigned long)((nowMs - g_telemetryLastAttemptMillis) / 1000UL));
    s += F(" s temu");
  } else {
    s += F("\nOstatnia proba: brak");
  }

  const TelemetrySample &sample = g_telemetryLastSnapshot;
  if (sample.sampleSeq == 0U) {
    s += F("\nOstatnia probka: brak");
    return s;
  }

  s += F("\nOstatnia probka seq: ");
  s += String((unsigned long)sample.sampleSeq);
  s += F(" / ts: ");
  s += String((unsigned long)sample.unixTs);

  s += F("\nQuality/age [s]:\n");
  struct ChInfo { TelemetryChannel ch; const char *name; };
  static const ChInfo chans[] = {
    {TELEMETRY_CH_ZEWN, "zewn"},
    {TELEMETRY_CH_BOJLER, "boj"},
    {TELEMETRY_CH_OGZ, "ogrz"},
    {TELEMETRY_CH_OGZ_SR, "sr"},
    {TELEMETRY_CH_POWROT, "pow"},
    {TELEMETRY_CH_PANEL, "panel"},
    {TELEMETRY_CH_POKOJ, "pok"},
    {TELEMETRY_CH_TROCINY, "tr"},
    {TELEMETRY_CH_RH, "RH"},
    {TELEMETRY_CH_PRESSURE, "cis"},
    {TELEMETRY_CH_DYM, "dym"}
  };
  for (size_t i = 0; i < sizeof(chans) / sizeof(chans[0]); ++i) {
    const uint8_t q = (uint8_t)((sample.qualityBits >> ((uint8_t)chans[i].ch * 2U)) & 0x3U);
    const char *qt = (q == 0U) ? "F" : (q == 1U) ? "S" : (q == 2U) ? "U" : "I";
    s += chans[i].name;
    s += F("=");
    s += qt;
    s += F("/");
    s += String((unsigned)sample.ageS[chans[i].ch]);
    if (i + 1U < sizeof(chans) / sizeof(chans[0])) s += F(" | ");
    if ((i + 1U) % 4U == 0U) s += F("\n");
  }
  s += F("\nLegenda: F=fresh S=stale U=unknown I=invalid");
  return s;
}

// --- TELEGRAM - raport diagnostyczny systemu ---
// Zbiera informacje, ktore dotad byly dostepne glownie jako reczne komendy
// (/ip, /wifi, /heap, /uptime, /time, /version, /logsize). Bez operacji
// mutujacych — sam odczyt stanu.
String buildTelegramDiagReport() {
  String s;
  s.reserve(900);
  s += F("<b>Diagnostyka systemu</b>\n");

  s += F("Firmware: ");
  s += String(FIRMWARE_VERSION);
  s += F("\n");

  if (wifiStan == WIFI_STAN_PORTAL_AP) {
    s += F("WiFi: AP / portal\nIP: ");
    s += WiFi.softAPIP().toString();
    s += F("\nSSID AP: ");
    s += String(WIFI_AP_SSID);
  } else {
    s += F("WiFi: STA ");
    s += (WiFi.status() == WL_CONNECTED) ? F("POLACZONE") : F("BRAK POLACZENIA");
    s += F("\nIP: ");
    if (WiFi.status() == WL_CONNECTED) {
      s += WiFi.localIP().toString();
    } else {
      s += F("-");
    }
    if (WiFi.status() == WL_CONNECTED) {
      s += F("\nSSID: ");
      s += WiFi.SSID();
      s += F("\nRSSI: ");
      s += String(WiFi.RSSI());
      s += F(" dBm");
    }
  }

  s += F("\nFirebase: ");
  s += fbAppReady ? F("OK") : F("BRAK");

  s += F("\nHeap: ");
  s += String((unsigned long)ESP.getFreeHeap());
  s += F(" B\nNajwiekszy blok: ");
  s += String((unsigned long)heap_caps_get_largest_free_block(MALLOC_CAP_8BIT));
  s += F(" B");

  unsigned long sekundy = millis() / 1000UL;
  unsigned long dni = sekundy / 86400UL; sekundy %= 86400UL;
  unsigned long godz = sekundy / 3600UL; sekundy %= 3600UL;
  unsigned long min = sekundy / 60UL; sekundy %= 60UL;
  s += F("\nUptime: ");
  s += String(dni); s += F("d ");
  s += String(godz); s += F("h ");
  s += String(min); s += F("m ");
  s += String(sekundy); s += F("s");

  if (g_rtcGotowy || g_rtcNtpZsynchronizowany) {
    char buf[24];
    snprintf(buf, sizeof(buf), "%02d.%02d.%04d %02d:%02d",
             aktualnaDataDzien, aktualnaDataMiesiac, aktualnaDataRok,
             aktualnyCzasGodzina, aktualnyCzasMinuta);
    s += F("\nCzas: ");
    s += buf;
    s += g_rtcGotowy ? F(" (RTC)") : F(" (NTP)");
  } else {
    s += F("\nCzas: niezsynchronizowany");
  }

  s += F("\nLogi LittleFS: ");
  s += String((unsigned long)logFsRozmiarUzyty());
  s += F(" B");
  s += F("\nBufor PSRAM: ");
  s += String((unsigned long)(logPelny ? LOG_BUF_SIZE : logZapisanychLacznie));
  s += F(" / ");
  s += String((unsigned long)LOG_BUF_SIZE);
  s += F(" B");

  return s;
}

