// [FB-ETAP1] Firebase — config (Preferences/NVS) + inicjalizacja/autoryzacja.
// Wzorzec 1:1 Ryby_LED_fi_S3_v160.cpp (fbInitialize(), ~linia 13260) — DNS
// pre-warm z retry (WDT-safe), jawny CA TLS, initializeApp()+UserAuth,
// pripiecie RealtimeDatabase, czekanie na fbApp.ready() max 3s z feedem WDT.
// ════════════════════════════════════════════════════════

// --- FIREBASE H2 - UserAuth credential z NVS, z awaryjnym credentialem boot ---
// [FB-BOOT-AUTH] Sterownik zdalny moze startowac bez wczesniejszego
// provisionowania NVS. Gdy NVS nie zawiera kompletnego UserAuth, uzywamy
// ponizszego konta startowego i od razu zapisujemy je do NVS.
static const char* FIREBASE_BOOT_API_KEY = "AIzaSyDcheuRNcNo4mzNpaTzn-19Ntw62djkfVU";
static const char* FIREBASE_BOOT_EMAIL   = "piec_co_boot@akwarium.local";
static const char* FIREBASE_BOOT_PASS    = "PcTg8plOcvRrMSojv79X";

void loadFirebaseConfig() {
  fbConfig.begin("firebase", false);
  fbApiKey = fbConfig.getString("api_key", "");
  fbUserEmail = fbConfig.getString("auth_email", "");
  fbUserPassword = fbConfig.getString("auth_pass", "");

  bool apiOk = fbApiKey.length() >= 20;
  bool emailOk = fbUserEmail.indexOf('@') > 0 && fbUserEmail.length() <= 160;
  bool passOk = fbUserPassword.length() >= 8;

  if (!apiOk || !emailOk || !passOk) {
    // [FB-BOOT-AUTH] Fallback tylko jako brak konfiguracji; nie nadpisujemy
    // poprawnych credentiali zapisanych juz w NVS.
    fbApiKey = FIREBASE_BOOT_API_KEY;
    fbUserEmail = FIREBASE_BOOT_EMAIL;
    fbUserPassword = FIREBASE_BOOT_PASS;
    fbConfig.putString("api_key", fbApiKey);
    fbConfig.putString("auth_email", fbUserEmail);
    fbConfig.putString("auth_pass", fbUserPassword);
    apiOk = true;
    emailOk = true;
    passOk = true;
    DLOG(DC_FIREBASE, DL_WARN, F("FB-CFG msg=\"brak kompletnego UserAuth w NVS - uzywam FB-BOOT-AUTH i zapisuje do NVS\""));
  }
  fbConfig.end();

  if (!apiOk || !emailOk || !passOk) {
    DLOG(DC_FIREBASE, DL_WARN, F("FB-CFG msg=\"brak kompletnego Firebase UserAuth - Firebase wylaczony\""));
    return;
  }

  if (fbUserAuth == nullptr) {
    fbUserAuth = new UserAuth(fbApiKey, fbUserEmail, fbUserPassword, 3300);
  }
  DLOG(DC_FIREBASE, DL_INFO, F("FB-CFG msg=\"Firebase UserAuth credential gotowy (NVS/FB-BOOT-AUTH)\""));
}

// ============================================================================
// [FIX-FB-LOOP-BEZ-LIMITU, v3.10.3] Pelne uzasadnienie w changelogu na samej
// gorze pliku (wpis [v3.10.3]). W skrocie: fbApp.loop() wewnatrz biblioteki
// FirebaseClient sam laczy fbSSLClient z FIREBASE_HOST (nazwa, nie IP) — a
// NetworkClientSecure::connect(host,...) w rdzeniu Arduino-ESP32 wola
// nieograniczone w czasie Network.hostByName() ZANIM jakikolwiek timeout
// (nasz _timeout/setHandshakeTimeout) wchodzi w gre. Dotychczasowa petla
// "while (!wynik.isResult() && millis()-start<limit) { fbApp.loop(); ...;
// esp_task_wdt_reset(); }" karmi WDT MIEDZY wywolaniami fbApp.loop(), nie W
// ICH TRAKCIE — jedno zablokowane wywolanie i tak zawiesza tgTask na Task
// WDT. Ponizej: dokladnie ten sam wzorzec "task-robotnik + wywolujacy czeka
// z wlasnym esp_task_wdt_reset() co ~20ms" co juz sprawdzone
// wifiHostByNameZLimitem() (patrz definicja przy tgEnsureConnected()), tylko
// opakowujacy cala petle fbApp.loop(), a nie pojedyncze hostByName().

// [STRAZNIK ROWNOLEGLOSCI] KRYTYCZNE: porzucony worker (ten, ktory nie
// zdazyl w limicie) NADAL siedzi w fbApp.loop() — czyli nadal, w tle, dotyka
// fbApp/fbDatabase/fbSSLClient i swojego AsyncResult. Gdyby w tym czasie
// kolejny cykl tgTask wszedl normalnie w fbDatabase.set()/get() + nowego
// workera, mielibysmy DWA taski grzebiace rownolegle w tych samych obiektach
// biblioteki — a FirebaseClient nie jest do tego przystosowany. To by
// zamienilo jeden zawieszony task w uszkodzenie pamieci/stanu biblioteki,
// czyli LECZENIE GORSZE OD CHOROBY. Dlatego: dopoki poprzedni worker zyje,
// cala sciezka Firebase jest pomijana (jak przy otwartym circuit breakerze —
// zero ruchu sieciowego, reszta systemu bez zmian). Flaga zdejmowana jest
// przez SAMEGO workera, gdy realnie wroci z zablokowanego wywolania.
static constexpr size_t TELEMETRY_JSON_BUFFER_BYTES = 8192U;
static constexpr size_t TELEMETRY_MAX_PAYLOAD_BYTES = 6144U;
static constexpr uint8_t TELEMETRY_BATCH_MAX_RECORDS = 10U;
static constexpr unsigned long TELEMETRY_SEND_INTERVAL_MS = 60000UL;
static constexpr uint32_t TELEMETRY_REQUEST_LIMIT_MS = 6000UL;

static bool telemetryEnsureJsonBuffer() {
  if (g_telemetryJsonBuffer) return true;
  g_telemetryJsonBuffer = static_cast<char *>(ps_malloc(TELEMETRY_JSON_BUFFER_BYTES));
  if (!g_telemetryJsonBuffer) {
    DLOGF(DC_TELEMETRY, DL_ERR, "json_buffer_alloc_fail bytes=%u",
                  (unsigned)TELEMETRY_JSON_BUFFER_BYTES);
    return false;
  }
  g_telemetryJsonBuffer[0] = '\0';
  return true;
}

static void telemetryJsonAppend(char *buf, size_t cap, size_t &used, const char *fmt, ...) {
  if (!buf || used >= cap) return;
  va_list ap;
  va_start(ap, fmt);
  int n = vsnprintf(buf + used, cap - used, fmt, ap);
  va_end(ap);
  if (n < 0) { used = cap; return; }
  if ((size_t)n >= cap - used) { used = cap; return; }
  used += (size_t)n;
}

static void telemetryFormatRecordId(const TelemetrySample &s, char *out, size_t outCap) {
  snprintf(out, outCap, "%016llX-%08lX",
           (unsigned long long)s.sessionNonce, (unsigned long)s.sampleSeq);
}

static bool telemetryAppendPathForSample(const TelemetrySample &s, char *buf, size_t cap, size_t &used, bool &first) {
  char recordId[32];
  telemetryFormatRecordId(s, recordId, sizeof(recordId));

  char path[64];
  if (s.unixTs == 0U) {
    snprintf(path, sizeof(path), "unknown/%s", recordId);
  } else {
    time_t raw = (time_t)s.unixTs;
    struct tm utc;
    memset(&utc, 0, sizeof(utc));
    if (!gmtime_r(&raw, &utc)) return false;
    snprintf(path, sizeof(path), "%04d/%02d/%02d/%s",
             utc.tm_year + 1900, utc.tm_mon + 1, utc.tm_mday, recordId);
  }

  if (!first) telemetryJsonAppend(buf, cap, used, ",");
  telemetryJsonAppend(buf, cap, used, "\"%s\":{", path);
  telemetryJsonAppend(buf, cap, used, "\"seq\":%lu,", (unsigned long)s.sampleSeq);
  telemetryJsonAppend(buf, cap, used, "\"ts\":%lu,", (unsigned long)s.unixTs);
  telemetryJsonAppend(buf, cap, used, "\"mono\":%lu,", (unsigned long)s.monoMs);
  telemetryJsonAppend(buf, cap, used, "\"a\":[%d,%d,%d,%d,%d,%d,%d,%d,%d,%d,%u],",
                      (int)s.tZewnX10, (int)s.tBojlerX10, (int)s.tOgrzX10,
                      (int)s.tOgrzSrX10, (int)s.tPowrotX10, (int)s.tPanelX10,
                      (int)s.tPokojX10, (int)s.tTrocinyX10, (int)s.rhX10,
                      (int)s.pressureX10, (unsigned)s.dym);
  telemetryJsonAppend(buf, cap, used, "\"k\":%u,\"s\":%u,",
                      (unsigned)s.klapaDeg, (unsigned)s.syberkoDeg);
  telemetryJsonAppend(buf, cap, used, "\"state\":%u,\"q\":%lu,\"sim\":%u,",
                      (unsigned)s.stateBits, (unsigned long)s.qualityBits,
                      (unsigned)s.simulatedBits);
  telemetryJsonAppend(buf, cap, used, "\"age\":[");
  for (uint8_t i = 0; i < TELEMETRY_CH_COUNT; ++i) {
    if (i) telemetryJsonAppend(buf, cap, used, ",");
    telemetryJsonAppend(buf, cap, used, "%u", (unsigned)s.ageS[i]);
  }
  telemetryJsonAppend(buf, cap, used, "]}");
  first = false;
  return used < cap;
}

static bool telemetryBuildBatch(uint8_t &countOut, uint32_t &lastSeqOut, size_t &bytesOut) {
  countOut = 0;
  lastSeqOut = 0;
  bytesOut = 0;
  if (!g_telemetryRing.ready() || g_telemetryRing.size() == 0U) return false;
  if (!telemetryEnsureJsonBuffer()) return false;

  size_t used = 0;
  g_telemetryJsonBuffer[0] = '{';
  used = 1;
  bool first = true;
  const uint32_t available = g_telemetryRing.size();
  const uint32_t limit = available < TELEMETRY_BATCH_MAX_RECORDS ? available : TELEMETRY_BATCH_MAX_RECORDS;

  for (uint32_t i = 0; i < limit; ++i) {
    TelemetrySample sample{};
    if (!g_telemetryRing.peekAt(i, sample)) break;

    const size_t before = used;
    bool trialFirst = first;
    const bool appendOk = telemetryAppendPathForSample(sample, g_telemetryJsonBuffer, TELEMETRY_JSON_BUFFER_BYTES, used, trialFirst);
    if (!appendOk && used < TELEMETRY_JSON_BUFFER_BYTES) return false;
    if (used >= TELEMETRY_MAX_PAYLOAD_BYTES) {
      used = before;
      if (countOut == 0U) return false;
      break;
    }
    first = trialFirst;
    countOut = (uint8_t)(i + 1U);
    lastSeqOut = sample.sampleSeq;
  }

  telemetryJsonAppend(g_telemetryJsonBuffer, TELEMETRY_JSON_BUFFER_BYTES, used, "}");
  if (used == 0U || used > TELEMETRY_MAX_PAYLOAD_BYTES) return false;
  bytesOut = used;
  return countOut > 0U;
}

// [v3.31.16] Jedynym wlascicielem fbApp.loop() jest tgTask. Nie tworzymy
// osobnego detached workera i nie wykonujemy Firebase rownolegle na drugim tasku.
static volatile bool g_fbAppInitialized = false;

bool fbLoopWorkerZajety() {
  return false;
}

static void fbFirebaseSocketStopSafe() {
  // Brak detached workera = brak rownoleglego fbApp.loop().
  fbSSLClient.stop();
}

// Warunek zakonczenia petli. Dwa tryby:
//   wynik != nullptr -> oczekiwanie na wynik operacji Firebase
//   wynik == nullptr -> oczekiwanie na fbApp.ready() podczas inicjalizacji
static inline bool fbWarunekSpelniony(AsyncResult *wynik) {
  return wynik ? wynik->isResult() : fbApp.ready();
}

static void fbCzekajImpl(AsyncResult *wynik, uint32_t limitWewnetrznyMs) {
  const unsigned long start = millis();
  while (!fbWarunekSpelniony(wynik) && millis() - start < limitWewnetrznyMs) {
    fbApp.loop();
    applyTcpKeepalive(fbSSLClient, 2, 1, 2);
    applyFbSockTimeouts(fbSSLClient, 8);
    serwisujTWDTJesliZarejestrowany();
    vTaskDelay(pdMS_TO_TICKS(10));
  }
  serwisujTWDTJesliZarejestrowany();
}

void fbCzekajNaWynikZLimitem(AsyncResult &wynik, uint32_t limitWewnetrznyMs) {
  fbCzekajImpl(&wynik, limitWewnetrznyMs);
}

// ============================================================================
// [R335-R344 LOCAL] COMMIT H1 — Firebase TLS verification + secret baseline.
// Test jest read-only względem RTDB: tylko bezpośredni TLS handshake i GET
// /piec/status. LegacyToken pozostaje tutaj wyłącznie jako baseline auth;
// migracja do docelowej per-device Firebase Auth + Rules to osobny H2.
// ============================================================================
static bool securityH1R335R344RunBatch(String &resultOut) {
  resultOut = "";
  bool ok = true;
  auto add = [&](const String &line) {
    if (resultOut.length()) resultOut += "\n";
    resultOut += line;
  };

  // R335: jawny trust store CA — Firebase nie korzysta już z setInsecure().
  add(F("R335:firebaseTLS=CA_CERT_REQUIRED"));

  // R336: LegacyToken jest usuniety z builda H2.
#if defined(ENABLE_LEGACY_TOKEN)
  add(F("R336:legacyToken=ENABLED"));
  ok = false;
#else
  add(F("R336:legacyToken=DISABLED"));
#endif

  // R337: H2 credential UserAuth pochodzi z NVS; wartosci nigdy nie logujemy.
  if (fbApiKey.length() >= 20 && fbUserEmail.indexOf('@') > 0 && fbUserPassword.length() >= 8) {
    add(F("R337:userAuthCredential=YES source=NVS"));
  } else {
    add(F("R337:userAuthCredential=NO fail-closed=YES"));
    return false;
  }

  // R338: NIE otwieramy juz dodatkowego, recznego TLS na fbSSLClient. Ten
  // klient jest wspoldzielonym transportem FirebaseClient; bezposrednie
  // connect()/stop() w harnessie mogly zmieniac stan tego samego transportu.
  // Sprawdzamy tutaj jedynie obecnosci jawnego CA, a zywy handshake + GET sa
  // faktycznie wykonywane kilka linii nizej przez normalna sciezke R340.
  {
    const bool caConfigured = FIREBASE_TLS_TRUST_CA && strlen(FIREBASE_TLS_TRUST_CA) > 100U;
    add(caConfigured
          ? F("R338:tlsConfig=CA_CERT_PRESENT certValidation=ON client=fbSSLClient")
          : F("R338:tlsConfig=CA_CERT_MISSING fail-closed=YES"));
    if (!caConfigured) ok = false;
  }

  // R339-R340: H1 nie zrywamy poprawnej sesji UserAuth tylko po to,
  // aby odtworzyc ja drugi raz. Jezeli sesji faktycznie nie ma, inicjalizujemy
  // i dajemy jej do 8 s na przejscie w READY.
  if (!fbAppReady || !fbApp.ready()) {
    fbInitialize();
    const unsigned long authWaitStartMs = millis();
    while ((!fbAppReady || !fbApp.ready()) &&
           (millis() - authWaitStartMs < 8000UL)) {
      serwisujTWDTJesliZarejestrowany();
      vTaskDelay(pdMS_TO_TICKS(50));
    }
  }
  if (fbAppReady && fbApp.ready()) {
    add(F("R339:firebaseAuth=READY authMode=USER_AUTH"));

    static AsyncResult securityReadResult;
    securityReadResult = AsyncResult{};
    fbSSLClient.setHandshakeTimeout(4000);
    fbSSLClient.setTimeout(4);
    serwisujTWDTJesliZarejestrowany();
    if (fbLoopWorkerZajety()) {
      add(F("R340:statusRead=SKIPPED workerBusy"));
      return false;
    }

    fbDatabase.get(fbAsyncClient, "/piec/status", securityReadResult);
    fbCzekajNaWynikZLimitem(securityReadResult, 5000UL);
    if (securityReadResult.isResult() && !securityReadResult.isError()) {
      add(F("R340:statusRead=OK method=GET readOnly=YES"));
    } else {
      add(String(F("R340:statusRead=FAIL error=")) +
          (securityReadResult.isError()
             ? securityReadResult.error().message()
             : String("TIMEOUT")));
      ok = false;
      fbFirebaseSocketStopSafe();
      fbAppReady = false;
      FB_NET_FAIL();
    }
  } else {
    add(F("R339:firebaseAuth=NOT_READY"));
    return false;
  }

  // R341-R343: H1 nie zmienia kontraktu istniejących namespace'ów.
  add(F("R341:telemetryPath=/piec/telemetry/1m/v1 UNCHANGED"));
  add(F("R342:cmdPath=/piec/cmd UNCHANGED"));
  add(F("R343:ackPath=/piec/ack UNCHANGED"));

  // R344: brak credentialu w diagnostyce.
  add(F("R344:secretDiagnostics=REDACTED noCredentialValue=EMITTED"));
  return ok;
}

// ============================================================================
// [R345-R356 LOCAL] COMMIT H2 — Firebase UserAuth + isolated per-device Rules gate.
// H2 NIE zapisuje /piec/status, /piec/cmd ani /piec/ack i nie przelacza normalnej
// telemetryki V1. Test dotyka tylko GET /piec/status (regresja auth) oraz shadow
// namespace /piec/devices/<uid>/... po wdrozeniu osobnych Rules.
// ============================================================================
static bool securityH2R345R356RunBatch(String &resultOut) {
  resultOut = "";
  bool ok = true;
  auto add = [&](const String &line) {
    if (resultOut.length()) resultOut += "\n";
    resultOut += line;
  };

#if defined(ENABLE_USER_AUTH)
  add(F("R345:userAuthBuild=ENABLED"));
#else
  add(F("R345:userAuthBuild=DISABLED"));
  return false;
#endif

#if defined(ENABLE_LEGACY_TOKEN)
  add(F("R346:legacyTokenCompile=ENABLED"));
  ok = false;
#else
  add(F("R346:legacyTokenCompile=DISABLED"));
#endif

  const bool apiOk = fbApiKey.length() >= 20;
  const bool emailOk = fbUserEmail.indexOf('@') > 0 && fbUserEmail.length() <= 160;
  const bool passOk = fbUserPassword.length() >= 8;
  if (apiOk && emailOk && passOk) {
    add(F("R347:userAuthNVS=YES api/email/password=present"));
  } else {
    add(F("R347:userAuthNVS=NO fail-closed=YES"));
    return false;
  }

  if (fbUserAuth != nullptr) {
    add(F("R348:userAuthObject=READY"));
  } else {
    add(F("R348:userAuthObject=NOT_READY"));
    return false;
  }

  // [H2-SESSION-FIX] Nie resetujemy fbAppReady w trakcie pracy gotowej sesji
  // UserAuth. Wymuszanie false powodowalo niepotrzebne wejscie w fbInitialize()
  // i moglo wejsc w konflikt z aktywnym fbApp.loop()/workerem. Inicjalizuj
  // tylko wtedy, gdy sesja faktycznie nie jest gotowa.
  Serial.println(F("tag=SEC-H2 lvl=INFO zdarzenie=before_auth_ready_check"));
  if (!(fbAppReady && fbApp.ready())) {
    Serial.println(F("tag=SEC-H2 lvl=INFO zdarzenie=auth_init_needed"));
    fbInitialize();
  }
  if (!(fbAppReady && fbApp.ready())) {
    add(F("R349:firebaseAuth=NOT_READY"));
    Serial.println(F("tag=SEC-H2 lvl=ERR zdarzenie=auth_not_ready"));
    return false;
  }
  Serial.println(F("tag=SEC-H2 lvl=INFO zdarzenie=auth_ready"));

  Serial.println(F("tag=SEC-H2 lvl=INFO zdarzenie=before_get_uid"));
  const String uid = fbApp.getUid();
  Serial.println(F("tag=SEC-H2 lvl=INFO zdarzenie=after_get_uid"));
  if (uid.length() >= 6 && uid.length() <= 128) {
    add(String(F("R350:firebaseAuth=READY authMode=USER_AUTH uidPresent=YES uidLen=")) + String(uid.length()));
  } else {
    add(F("R350:firebaseAuth=READY uidPresent=NO"));
    ok = false;
  }

  add(F("R351:tokenDiagnostics=REDACTED idToken=NOT_EMITTED"));

  Serial.println(F("tag=SEC-H2 lvl=INFO zdarzenie=R352_start"));
  static AsyncResult r352;
    r352 = AsyncResult{};
  fbSSLClient.setHandshakeTimeout(4000);
  fbSSLClient.setTimeout(4);
  if (fbLoopWorkerZajety()) {
    add(F("R352:legacyStatusGET=SKIPPED workerBusy"));
    return false;
  }
  fbDatabase.get(fbAsyncClient, "/piec/status", r352);
  fbCzekajNaWynikZLimitem(r352, 5000UL);
  if (r352.isResult() && !r352.isError()) {
    add(F("R352:legacyStatusGET=OK method=GET readOnly=YES"));
    Serial.println(F("tag=SEC-H2 lvl=INFO zdarzenie=R352_done"));
  } else {
    add(String(F("R352:legacyStatusGET=FAIL error=")) +
        (r352.isError() ? r352.error().message() : String("TIMEOUT")));
    fbFirebaseSocketStopSafe();
    fbAppReady = false;
    FB_NET_FAIL();
    return false;
  }

  if (uid.length() > 0) {
    Serial.println(F("tag=SEC-H2 lvl=INFO zdarzenie=R353_start"));
    const String ownPath = String("/piec/devices/") + uid + "/status";
    static AsyncResult r353;
    r353 = AsyncResult{};
    fbDatabase.get(fbAsyncClient, ownPath, r353);
    fbCzekajNaWynikZLimitem(r353, 5000UL);
    if (r353.isResult() && !r353.isError()) {
      add(F("R353:ownDeviceShadowRead=OK path=/piec/devices/UID/status"));
      Serial.println(F("tag=SEC-H2 lvl=INFO zdarzenie=R353_done"));
    } else {
      add(String(F("R353:ownDeviceShadowRead=FAIL error=")) +
          (r353.isError() ? r353.error().message() : String("TIMEOUT")));
      ok = false;
    }

    Serial.println(F("tag=SEC-H2 lvl=INFO zdarzenie=R354_start"));
    const String foreignUid = String("h2_foreign_uid_denied");
    static AsyncResult r354;
    r354 = AsyncResult{};
    fbDatabase.get(fbAsyncClient, String("/piec/devices/") + foreignUid + "/status", r354);
    fbCzekajNaWynikZLimitem(r354, 5000UL);
    if (r354.isError()) {
      add(F("R354:foreignDeviceRead=DENIED"));
      Serial.println(F("tag=SEC-H2 lvl=INFO zdarzenie=R354_done state=DENIED"));
    } else if (r354.isResult()) {
      add(F("R354:foreignDeviceRead=ALLOWED_RULES_FAIL"));
      Serial.println(F("tag=SEC-H2 lvl=ERR zdarzenie=R354_done state=ALLOWED"));
      ok = false;
    } else {
      add(F("R354:foreignDeviceRead=TIMEOUT workerPending=YES"));
      Serial.println(F("tag=SEC-H2 lvl=ERR zdarzenie=R354_timeout workerBusy="));
      Serial.printf("%u\n", fbLoopWorkerZajety() ? 1U : 0U);
      return false;
    }

    // R355: prawdziwy negative write test na shadow cmd. Przy poprawnych Rules
    // device (auth.uid == uid) nie ma prawa pisac do wlasnego /cmd.
    // Probe jest jedynym miejscem H2, gdzie wykonujemy celowy write test.
    Serial.println(F("tag=SEC-H2 lvl=INFO zdarzenie=R355_start"));
    if (!fbLoopWorkerZajety()) {
      const String probePath = String("/piec/devices/") + uid + "/cmd/__h2_probe";
      object_t probeData("{\"probe\":true}");
      static AsyncResult r355;
    r355 = AsyncResult{};
      fbDatabase.set<object_t>(fbAsyncClient, probePath, probeData, r355);
      fbCzekajNaWynikZLimitem(r355, 5000UL);
      if (r355.isError()) {
        add(F("R355:ownDeviceCmdWrite=DENIED"));
        Serial.println(F("tag=SEC-H2 lvl=INFO zdarzenie=R355_done state=DENIED"));
      } else if (r355.isResult()) {
        add(F("R355:ownDeviceCmdWrite=ALLOWED_RULES_FAIL"));
        Serial.println(F("tag=SEC-H2 lvl=ERR zdarzenie=R355_done state=ALLOWED"));
        ok = false;
        // Jezeli rules sa zbyt szerokie, probujemy posprzatac tylko ten unikalny probe.
        static AsyncResult cleanup;
    cleanup = AsyncResult{};
        fbDatabase.remove(fbAsyncClient, probePath, cleanup);
        fbCzekajNaWynikZLimitem(cleanup, 5000UL);
      } else {
        add(F("R355:ownDeviceCmdWrite=TIMEOUT workerPending=YES"));
        Serial.printf("tag=SEC-H2 lvl=ERR zdarzenie=R355_timeout workerBusy=%u\n",
                      fbLoopWorkerZajety() ? 1U : 0U);
        return false;
      }
    } else {
      add(F("R355:ownDeviceCmdWrite=SKIPPED workerBusy"));
      ok = false;
    }
  } else {
    add(F("R353-R355:SKIPPED uidMissing"));
    ok = false;
  }

  add(F("R356:v1Paths=UNCHANGED h2ShadowOnly=YES legacySecret=NOT_USED"));
  return ok;
}

// ============================================================================
// [H2-WORKER-FIX v3.29.3] Niezalezny task wykonujacy batch H2.
// Cel: nie zalezec od tgTask/tgCmdQueue, ktore moga byc zajete dluzsza
// operacja Firebase, wysylka Telegrama albo innym blokujacym odcinkiem.
// Worker dziala na Core 0, a fbCzekajNaWynikZLimitem() uruchamia osobny
// fbLoopWork na Core 1 — tak jak pozostale ograniczone operacje Firebase.
// Jednoczesnosc jest jawnie blokowana jedna flaga, wiec dwa /securityh2 TAK
// nie uruchomia dwoch workerow H2 naraz.
// ============================================================================
static volatile bool g_securityH2TaskRunning = false;
static TaskHandle_t g_securityH2TaskHandle = nullptr;

static void securityH2TaskFn(void * /*pvParams*/) {
  Serial.println(F("tag=SEC-H2 lvl=INFO zdarzenie=worker_start"));

  String wynik;
  const bool pass = securityH2R345R356RunBatch(wynik);

  Serial.printf("tag=SEC-H2 lvl=INFO zdarzenie=worker_done pass=%u resultLen=%u\n",
                pass ? 1U : 0U, (unsigned)wynik.length());

  if (pass) {
    sendTelegramMessage(String("R345-R356 security H2 batch: PASS\n") + wynik);
  } else {
    sendTelegramMessage(String("R345-R356 security H2 batch: FAIL\n") + wynik);
  }

  g_securityH2TaskRunning = false;
  g_securityH2TaskHandle = nullptr;
  vTaskDelete(nullptr);
}

static bool securityH2LaunchTask() {
  if (g_securityH2TaskRunning) {
    Serial.println(F("tag=SEC-H2 lvl=WARN zdarzenie=worker_already_running"));
    return false;
  }

  // Ustaw przed xTaskCreate, zeby druga komenda nie weszla w to samo okno
  // czasowe i nie uruchomila drugiego workera. Przy porazce tworzenia taska
  // flaga jest natychmiast cofana.
  g_securityH2TaskRunning = true;
  BaseType_t created = xTaskCreatePinnedToCore(
      securityH2TaskFn, "secH2Task", 12288, nullptr, 1,
      &g_securityH2TaskHandle, 0);

  if (created != pdPASS) {
    g_securityH2TaskRunning = false;
    g_securityH2TaskHandle = nullptr;
    Serial.println(F("tag=SEC-H2 lvl=ERR zdarzenie=worker_create_fail"));
    return false;
  }

  Serial.println(F("tag=SEC-H2 lvl=INFO zdarzenie=worker_created"));
  return true;
}

static void telemetryFinalizeCompletedRequest() {
  if (!g_telemetryRequestActive) return;
  if (fbLoopWorkerZajety()) return;
  if (!g_telemetryCompletionPending) return;

  const bool ok = g_telemetryCompletionSuccess;
  const uint8_t batchCount = (uint8_t)g_telemetryBatchCount;
  g_telemetryCompletionPending = false;
  g_telemetryRequestActive = false;

  if (ok && batchCount > 0U) {
    if (!g_telemetryRing.commitPopN(batchCount)) {
      if (g_telemetryCountersMutex) xSemaphoreTake(g_telemetryCountersMutex, portMAX_DELAY);
      ++g_telemetryTransportFailures;
      if (g_telemetryCountersMutex) xSemaphoreGive(g_telemetryCountersMutex);
      DLOGF(DC_TELEMETRY, DL_ERR, "commit_tail_fail count=%u", (unsigned)batchCount);
      return;
    }
    if (g_telemetryCountersMutex) xSemaphoreTake(g_telemetryCountersMutex, portMAX_DELAY);
    g_telemetrySamplesSent += batchCount;
    if (g_telemetryCountersMutex) xSemaphoreGive(g_telemetryCountersMutex);
    DLOGF(DC_TELEMETRY, DL_DEBUG, "batch_ok count=%u last_seq=%lu sent=%lu",
          (unsigned)batchCount, (unsigned long)g_telemetryBatchLastSeq,
          (unsigned long)g_telemetrySamplesSent);
  } else {
    if (g_telemetryCountersMutex) xSemaphoreTake(g_telemetryCountersMutex, portMAX_DELAY);
    ++g_telemetryTransportFailures;
    if (g_telemetryCountersMutex) xSemaphoreGive(g_telemetryCountersMutex);
    DLOGF(DC_TELEMETRY, DL_WARN, "batch_fail count=%u", (unsigned)batchCount);
    fbAppReady = false;
    fbSSLClient.stop();
    FB_NET_FAIL();
  }
  g_telemetryBatchCount = 0;
  g_telemetryBatchLastSeq = 0;
}

static void telemetryPublishCompletionFromResult() {
  if (!g_telemetryRequestActive || g_telemetryCompletionPending) return;
  if (fbLoopWorkerZajety()) return;
  g_telemetryCompletionSuccess = g_fbTelemetryResult.isResult() && !g_fbTelemetryResult.isError();
  // Worker zakonczyl prace. Brak result/error oznacza timeout bez finalnego
  // ACK — traktujemy go jako FAIL i zachowujemy tail do retry.
  g_telemetryCompletionPending = true;
}

// ============================================================================
// [G2 LOCAL] Persistent Spool V2 runtime exercise.
// Jawnie uzbrojony tryb testowy. Reuzywa zamrozonych helperow page/CRC/quota,
// tego samego TelemetryRing i TEGO SAMEGO klienta Firebase. Nie tworzy nowego
// Firebase client/task. Po restarcie tryb wraca OFF; strony pozostaja na FS,
// wiec kolejny /spoolrt TAK moze zweryfikowac replay od poczatku (at-least-once).
// ============================================================================
static bool spoolRuntimeParsePageSeq(const char* name, uint32_t &seqOut) {
  seqOut = 0U;
  if (!name) return false;
  const char* p = strstr(name, "/page_");
  if (!p) p = strstr(name, "page_");
  if (!p) return false;
  p += 6;
  if (strlen(p) < 15U) return false; // 10 cyfr + .bin
  char digits[11] = {};
  memcpy(digits, p, 10U);
  for (size_t i = 0; i < 10U; ++i) if (digits[i] < '0' || digits[i] > '9') return false;
  if (strncmp(p + 10, ".bin", 4) != 0) return false;
  const unsigned long v = strtoul(digits, nullptr, 10);
  if (v > 0xFFFFFFFFUL) return false;
  seqOut = (uint32_t)v;
  return seqOut >= SPOOL_RUNTIME_PAGESEQ_BASE;
}

static bool spoolRuntimeMakeFinalPath(uint32_t seq, String &pathOut) {
  char finalPath[96] = {};
  char partPath[100] = {};
  if (!spoolGMakePagePath(seq, finalPath, sizeof(finalPath), partPath, sizeof(partPath))) return false;
  pathOut = String(finalPath);
  return true;
}

static bool spoolRuntimeValidateFinalBySeq(uint32_t seq, String &pathOut, uint32_t &recordsOut) {
  pathOut = "";
  recordsOut = 0U;
  if (!littlefsReady || seq < SPOOL_RUNTIME_PAGESEQ_BASE) return false;
  String candidate;
  if (!spoolRuntimeMakeFinalPath(seq, candidate)) return false;
  if (!LittleFS.exists(candidate.c_str())) return false;
  SpoolBatchScan scan{};
  if (!spoolBatchScan(candidate.c_str(), scan) || !scan.footerOk || scan.validRecords == 0U || scan.pageSeq != seq) return false;
  pathOut = candidate;
  recordsOut = scan.validRecords;
  return true;
}

static uint32_t spoolRuntimeGetOldestHint() {
  Preferences prefs;
  if (!prefs.begin("spoolrt", true)) return 0U;
  const uint32_t v = nvsGetUInt(prefs, "oldest", 0U);
  prefs.end();
  return (v >= SPOOL_RUNTIME_PAGESEQ_BASE) ? v : 0U;
}

static void spoolRuntimeSetOldestHint(uint32_t seq) {
  Preferences prefs;
  if (!prefs.begin("spoolrt", false)) return;
  if (seq >= SPOOL_RUNTIME_PAGESEQ_BASE) prefs.putUInt("oldest", seq);
  else prefs.remove("oldest");
  prefs.end();
}

static bool spoolRuntimeFindOldestFinalPage(String &pathOut, uint32_t &seqOut, uint32_t &recordsOut) {
  pathOut = "";
  seqOut = 0U;
  recordsOut = 0U;
  if (!littlefsReady) return false;

  // Najpierw deterministyczny hint z NVS. To omija zaleznosc od tego,
  // czy dana wersja LittleFS zwraca basename czy pelna sciezke z openNextFile().
  uint32_t hint = spoolRuntimeGetOldestHint();
  Preferences prefs;
  uint32_t lastSeqNvs = 0U;
  if (prefs.begin("spoolrt", true)) {
    lastSeqNvs = nvsGetUInt(prefs, "lastseq", 0U);
    prefs.end();
  }

  if (hint) {
    if (spoolRuntimeValidateFinalBySeq(hint, pathOut, recordsOut)) {
      seqOut = hint;
      return true;
    }
  }

  // Migracja bez zapisu do FS: strony z v3.30.0/v3.30.1 nie mialy pola
  // "oldest" w NVS. Ich sequence jest jednak monotoniczne i lastseq jest
  // juz trwale zapisany. Szukamy wstecz ograniczonego okna i wybieramy
  // najstarsza poprawna strone. To odzyskuje juz utworzone strony bez
  // ponownego testu offline.
  if (lastSeqNvs >= SPOOL_RUNTIME_PAGESEQ_BASE) {
    const uint32_t firstTry = (lastSeqNvs > 4096U) ? (lastSeqNvs - 4096U) : SPOOL_RUNTIME_PAGESEQ_BASE;
    for (uint32_t seq = lastSeqNvs; seq >= firstTry; --seq) {
      String candidate;
      uint32_t recs = 0U;
      if (spoolRuntimeValidateFinalBySeq(seq, candidate, recs)) {
        pathOut = candidate;
        seqOut = seq;
        recordsOut = recs;
        spoolRuntimeSetOldestHint(seq);
        // Nie zatrzymujemy sie na pierwszym znalezionym od konca. Szukamy
        // najstarszej strony w zakresie, aby zachowac FIFO.
      }
      if (seq == firstTry) break;
    }
    if (seqOut != 0U) return true;
  }

  // Fallback dla starych stron utworzonych przed wprowadzeniem hintu.
  if (!LittleFS.exists(SPOOL_G_DIR)) return false;
  File dir = LittleFS.open(SPOOL_G_DIR);
  if (!dir || !dir.isDirectory()) return false;

  bool found = false;
  uint32_t bestSeq = 0U;
  String bestPath;
  uint32_t bestRecords = 0U;
  File entry = dir.openNextFile();
  while (entry) {
    if (!entry.isDirectory()) {
      String nm = String(entry.name());
      if (!nm.endsWith(".part")) {
        uint32_t seq = 0U;
        if (spoolRuntimeParsePageSeq(nm.c_str(), seq)) {
          String candidatePath = nm;
          if (!candidatePath.startsWith("/")) candidatePath = String(SPOOL_G_DIR) + "/" + candidatePath;
          SpoolBatchScan scan{};
          if (spoolBatchScan(candidatePath.c_str(), scan) && scan.footerOk && scan.validRecords > 0U && scan.pageSeq == seq) {
            if (!found || seq < bestSeq) {
              found = true;
              bestSeq = seq;
              bestPath = candidatePath;
              bestRecords = scan.validRecords;
            }
          }
        }
      }
    }
    entry.close();
    entry = dir.openNextFile();
  }
  dir.close();
  if (!found) return false;
  pathOut = bestPath;
  seqOut = bestSeq;
  recordsOut = bestRecords;
  spoolRuntimeSetOldestHint(bestSeq);
  return true;
}

static bool spoolRuntimeAllocatePageSeq(uint32_t &seqOut) {
  seqOut = 0U;
  Preferences prefs;
  if (!prefs.begin("spoolrt", false)) return false;
  const uint32_t stored = nvsGetUInt(prefs, "lastseq", SPOOL_RUNTIME_PAGESEQ_BASE - 1U);
  const uint32_t last = (stored >= SPOOL_RUNTIME_PAGESEQ_BASE) ? stored : (SPOOL_RUNTIME_PAGESEQ_BASE - 1U);
  if (last == 0xFFFFFFFFUL) { prefs.end(); return false; }
  const uint32_t next = last + 1U;
  if (prefs.putUInt("lastseq", next) != sizeof(uint32_t)) { prefs.end(); return false; }
  prefs.end();
  seqOut = next;
  return true;
}

static String spoolRuntimeBuildReport() {
  String s;
  s.reserve(1000);
  String oldestPath;
  uint32_t oldestSeq = 0U, oldestRecords = 0U;
  const bool haveOldest = spoolRuntimeFindOldestFinalPage(oldestPath, oldestSeq, oldestRecords);
  s += F("Spool G2 runtime: ");
  s += g_spoolRuntimeArmed ? F("ARMED") : F("OFF");
  s += F("\nRing: ");
  s += String((unsigned)g_telemetryRing.size());
  s += F("/");
  s += String((unsigned)g_telemetryRing.capacity());
  s += F("\nPages created: ");
  s += String((unsigned long)g_spoolRuntimePagesCreated);
  s += F("\nSamples spilled: ");
  s += String((unsigned long)g_spoolRuntimeSamplesSpilled);
  s += F("\nSamples replayed: ");
  s += String((unsigned long)g_spoolRuntimeSamplesReplayed);
  s += F("\nPages deleted: ");
  s += String((unsigned long)g_spoolRuntimePagesDeleted);
  s += F("\nReplay failures: ");
  s += String((unsigned long)g_spoolRuntimeReplayFailures);
  if (haveOldest) {
    s += F("\nOldest runtime page: seq=");
    s += String((unsigned long)oldestSeq);
    s += F(" records=");
    s += String((unsigned)oldestRecords);
    s += F(" cursor=");
    s += String((unsigned)(g_spoolRuntimeLastReplayPageSeq == oldestSeq ? g_spoolRuntimeReplayCursor : 0U));
  } else {
    s += F("\nOldest runtime page: NONE");
  }
  s += F("\nPolicy test: offline>=");
  s += String((unsigned long)(SPOOL_RUNTIME_OFFLINE_TRIGGER_MS / 1000UL));
  s += F("s lub ring>=");
  s += String((unsigned)SPOOL_RUNTIME_RING_WATERMARK);
  s += F("; replayMax=");
  s += String((unsigned)SPOOL_RUNTIME_REPLAY_BATCH_MAX);
  return s;
}

static bool spoolRuntimeArm(String &resultOut) {
  resultOut = "";
  if (!littlefsReady) { resultOut = "LittleFS nie gotowy"; return false; }
  if (!g_telemetryRing.ready()) { resultOut = "TelemetryRing nie gotowy"; return false; }
  if (fbLoopWorkerZajety()) { resultOut = "Firebase worker zajety"; return false; }
  g_spoolRuntimeArmed = true;
  g_spoolRuntimeOfflineSinceMs = 0U;
  resultOut = "G2 runtime ARMED: offline/backpressure -> spool, online -> replay FIFO max 10; produkcja OFF";
  DLOG(DC_SPOOL, DL_INFO, F("SPOOL-G2 zdarzenie=armed"));
  return true;
}

static bool spoolRuntimeStop(String &resultOut) {
  resultOut = "";
  g_spoolRuntimeArmed = false;
  g_spoolRuntimeOfflineSinceMs = 0U;
  resultOut = "G2 runtime OFF: strony na LittleFS zachowane";
  DLOG(DC_SPOOL, DL_INFO, F("SPOOL-G2 zdarzenie=stopped"));
  return true;
}

static bool spoolRuntimeMaybeSpill() {
  if (!g_spoolRuntimeArmed || g_spoolGTestActive) return false;
  if (!littlefsReady || !g_telemetryRing.ready()) return false;
  if (g_telemetryRequestActive || fbLoopWorkerZajety()) return false;
  const uint32_t ringSize = g_telemetryRing.size();
  if (ringSize == 0U) return false;

  const bool transportUnavailable =
      WiFi.status() != WL_CONNECTED || !fbAppReady || !fbApp.ready();
  const uint32_t now = millis();
  if (transportUnavailable) {
    if (g_spoolRuntimeOfflineSinceMs == 0U) g_spoolRuntimeOfflineSinceMs = now;
  } else {
    g_spoolRuntimeOfflineSinceMs = 0U;
  }

  const bool offlineDue =
      g_spoolRuntimeOfflineSinceMs != 0U &&
      (uint32_t)(now - g_spoolRuntimeOfflineSinceMs) >= SPOOL_RUNTIME_OFFLINE_TRIGGER_MS;
  const bool backlogDue = ringSize >= SPOOL_RUNTIME_RING_WATERMARK;
  if (!offlineDue && !backlogDue) return false;
  if ((uint32_t)(now - g_spoolRuntimeLastSpillMs) < SPOOL_RUNTIME_SPILL_COOLDOWN_MS) return false;

  const uint32_t count = min(ringSize, SPOOL_RUNTIME_SPILL_MAX_RECORDS);
  if (count == 0U) return false;
  const size_t pageBytes = spoolUsedBytes(SPOOL_PAGE_64K, count);
  size_t freeBytes = 0, protectedBytes = 0, quotaBytes = 0;
  if (!fsQuotaTelemetryAdmission(pageBytes, freeBytes, protectedBytes, quotaBytes)) {
    DLOGF(DC_SPOOL, DL_WARN, "quota_block count=%u free=%lu protected=%lu quota=%lu",
                  (unsigned)count, (unsigned long)freeBytes,
                  (unsigned long)protectedBytes, (unsigned long)quotaBytes);
    return false;
  }

  uint32_t pageSeq = 0U;
  if (!spoolRuntimeAllocatePageSeq(pageSeq)) return false;
  char finalPath[96] = {}, partPath[100] = {};
  if (!spoolGMakePagePath(pageSeq, finalPath, sizeof(finalPath), partPath, sizeof(partPath))) return false;
  if (LittleFS.exists(partPath)) LittleFS.remove(partPath);
  if (LittleFS.exists(finalPath)) return false;

  if (!logMutex || xSemaphoreTake(logMutex, pdMS_TO_TICKS(1000)) != pdTRUE) return false;
  uint32_t firstSeq = 0U, lastSeq = 0U;
  String why;
  const bool wrote = spoolGWritePageFromRing(partPath, count, pageSeq, false, false,
                                               firstSeq, lastSeq, why);
  if (!wrote) {
    xSemaphoreGive(logMutex);
    if (LittleFS.exists(partPath)) LittleFS.remove(partPath);
    DLOGF(DC_SPOOL, DL_ERR, "spill_write_fail why=%s", why.c_str());
    return false;
  }
  if (!LittleFS.rename(partPath, finalPath)) {
    xSemaphoreGive(logMutex);
    if (LittleFS.exists(partPath)) LittleFS.remove(partPath);
    DLOG(DC_SPOOL, DL_ERR, F("spill_rename_fail"));
    return false;
  }
  SpoolBatchScan scan{};
  const bool durable = spoolBatchScan(finalPath, scan) && scan.footerOk &&
                       scan.validRecords == count && scan.firstSeq == firstSeq && scan.lastSeq == lastSeq;
  if (!durable) {
    xSemaphoreGive(logMutex);
    DLOG(DC_SPOOL, DL_ERR, F("spill_final_verify_fail"));
    return false;
  }

  // Tail przesuwamy dopiero po finalnym reopen/CRC verification.
  const bool tailOk = g_telemetryRing.commitPopN(count);
  xSemaphoreGive(logMutex);
  if (!tailOk) {
    DLOG(DC_SPOOL, DL_ERR, F("spill_tail_commit_fail"));
    return false;
  }

  if (spoolRuntimeGetOldestHint() == 0U) spoolRuntimeSetOldestHint(pageSeq);
  g_spoolRuntimeLastSpillMs = now;
  g_spoolRuntimeSamplesSpilled += count;
  g_spoolRuntimePagesCreated++;
  DLOGF(DC_SPOOL, DL_DEBUG, "spill_ok pageSeq=%lu records=%u firstSeq=%lu lastSeq=%lu ringAfter=%u",
                (unsigned long)pageSeq, (unsigned)count,
                (unsigned long)firstSeq, (unsigned long)lastSeq,
                (unsigned)g_telemetryRing.size());
  return true;
}

static bool spoolRuntimeReplayOneBatch(unsigned long tgIterStartMs) {
  if (!g_spoolRuntimeArmed || g_spoolGTestActive) return false;
  if (millis() - tgIterStartMs >= 10000UL) return false;
  if (g_telemetryRequestActive || fbLoopWorkerZajety()) return false;

  // Po powrocie WAN sesja Firebase mogla zostac oznaczona jako niegotowa
  // podczas awarii. Replay ma samodzielnie odtworzyc UserAuth, zamiast
  // czekac az przypadkiem zrobi to status/cmd polling.
  if (WiFi.status() == WL_CONNECTED && !(fbAppReady && fbApp.ready())) {
    if (!fbNetCircuitOpen || millis() >= fbNetCooldownUntilMs) fbInitialize();
  }
  if (WiFi.status() != WL_CONNECTED || !fbAppReady || !fbApp.ready()) return false;

  String pagePath;
  uint32_t pageSeq = 0U, recordCount = 0U;
  if (!logMutex || xSemaphoreTake(logMutex, pdMS_TO_TICKS(1000)) != pdTRUE) return false;
  const bool foundPage = spoolRuntimeFindOldestFinalPage(pagePath, pageSeq, recordCount);
  if (!foundPage) {
    xSemaphoreGive(logMutex);
    return false;
  }

  if (g_spoolRuntimeLastReplayPageSeq != pageSeq) {
    g_spoolRuntimeLastReplayPageSeq = pageSeq;
    g_spoolRuntimeReplayCursor = 0U;
    g_spoolRuntimeReplayPageRecordCount = recordCount;
  } else if (g_spoolRuntimeReplayPageRecordCount != recordCount) {
    g_spoolRuntimeReplayPageRecordCount = recordCount;
    if (g_spoolRuntimeReplayCursor > recordCount) g_spoolRuntimeReplayCursor = 0U;
  }

  const uint32_t cursor = g_spoolRuntimeReplayCursor;
  if (cursor >= recordCount) {
    if (LittleFS.remove(pagePath.c_str())) {
      g_spoolRuntimePagesDeleted++;
      {
        Preferences prefs;
        uint32_t lastSeq = pageSeq;
        if (prefs.begin("spoolrt", true)) { lastSeq = nvsGetUInt(prefs, "lastseq", pageSeq); prefs.end(); }
        spoolRuntimeSetOldestHint((pageSeq < lastSeq) ? (pageSeq + 1U) : 0U);
      }
      g_spoolRuntimeLastReplayPageSeq = 0U;
      g_spoolRuntimeReplayCursor = 0U;
      g_spoolRuntimeReplayPageRecordCount = 0U;
      DLOGF(DC_SPOOL, DL_DEBUG, "replay_delete pageSeq=%lu", (unsigned long)pageSeq);
      return true;
    }
    return false;
  }

  const uint32_t take = min((uint32_t)SPOOL_RUNTIME_REPLAY_BATCH_MAX, recordCount - cursor);
  if (!telemetryEnsureJsonBuffer()) return false;
  size_t used = 0U;
  g_telemetryJsonBuffer[0] = '{';
  used = 1U;
  bool first = true;
  for (uint32_t i = 0U; i < take; ++i) {
    TelemetrySample sample{};
    String recordId;
    if (!spoolReplayReadRecord(pagePath.c_str(), cursor + i, sample, recordId)) {
      g_spoolRuntimeReplayFailures++;
      DLOGF(DC_SPOOL, DL_ERR, "replay_read_fail pageSeq=%lu idx=%u",
                    (unsigned long)pageSeq, (unsigned)(cursor + i));
      xSemaphoreGive(logMutex);
      return false;
    }
    if (!telemetryAppendPathForSample(sample, g_telemetryJsonBuffer,
                                       TELEMETRY_JSON_BUFFER_BYTES, used, first)) {
      g_spoolRuntimeReplayFailures++;
      xSemaphoreGive(logMutex);
      return false;
    }
  }
  if (used + 2U >= TELEMETRY_JSON_BUFFER_BYTES) {
    g_spoolRuntimeReplayFailures++;
    xSemaphoreGive(logMutex);
    return false;
  }
  xSemaphoreGive(logMutex);
  g_telemetryJsonBuffer[used++] = '}';
  g_telemetryJsonBuffer[used] = '\0';

  g_spoolRuntimeReplayResult = AsyncResult{};
  g_spoolRuntimeReplayActive = true;
  fbSSLClient.setHandshakeTimeout(4000);
  serwisujTWDTJesliZarejestrowany();
  object_t payload(g_telemetryJsonBuffer);
  fbDatabase.update<object_t>(fbAsyncClient, "/piec/telemetry/1m/v1", payload, g_spoolRuntimeReplayResult);
  fbCzekajNaWynikZLimitem(g_spoolRuntimeReplayResult, TELEMETRY_REQUEST_LIMIT_MS);
  const bool ack = g_spoolRuntimeReplayResult.isResult() && !g_spoolRuntimeReplayResult.isError();
  g_spoolRuntimeReplayActive = false;

  if (!ack) {
    g_spoolRuntimeReplayFailures++;
    DLOGF(DC_SPOOL, DL_WARN, "replay_ack_fail pageSeq=%lu cursor=%u take=%u",
                  (unsigned long)pageSeq, (unsigned)cursor, (unsigned)take);
    return false;
  }

  FB_NET_SUCCESS();
  g_spoolRuntimeReplayCursor += take;
  g_spoolRuntimeSamplesReplayed += take;
  DLOGF(DC_SPOOL, DL_DEBUG, "replay_ack pageSeq=%lu cursor=%u/%u batch=%u",
                (unsigned long)pageSeq,
                (unsigned)g_spoolRuntimeReplayCursor,
                (unsigned)recordCount,
                (unsigned)take);

  if (g_spoolRuntimeReplayCursor >= recordCount) {
    if (!logMutex || xSemaphoreTake(logMutex, pdMS_TO_TICKS(1000)) != pdTRUE) {
      g_spoolRuntimeReplayFailures++;
      return false;
    }
    const bool deleted = LittleFS.remove(pagePath.c_str());
    xSemaphoreGive(logMutex);
    if (deleted) {
      g_spoolRuntimePagesDeleted++;
      spoolRuntimeSetOldestHint(0U);
      DLOGF(DC_SPOOL, DL_DEBUG, "replay_page_deleted pageSeq=%lu records=%u",
                    (unsigned long)pageSeq, (unsigned)recordCount);
      g_spoolRuntimeLastReplayPageSeq = 0U;
      g_spoolRuntimeReplayCursor = 0U;
      g_spoolRuntimeReplayPageRecordCount = 0U;
    } else {
      g_spoolRuntimeReplayFailures++;
      return false;
    }
  }
  return true;
}

// ============================================================================
// ============================================================================
// [R380-R400 LOCAL] FINAL REGRESSION MEGA
// One command re-runs the critical frozen test gates in dependency order:
// Persistent Spool V2 -> replay/faults -> Commit G -> H1/H2 -> RTDB.
// Then it checks final runtime health and the latest coredump archive.
// Test-only, local/test board. Production remains v3.19.2.
// ============================================================================
static bool finalMegaEnsureRealTelemetrySnapshot(String &why) {
  if (g_telemetryLastSnapshot.sampleSeq != 0U && g_telemetryLastSnapshot.sessionNonce != 0ULL) {
    why = "telemetrySnapshot=ALREADY_PRESENT sampleSeq=" +
          String((unsigned long)g_telemetryLastSnapshot.sampleSeq) +
          " sessionNonce=READY";
    return true;
  }

  int historySlot = -1;
  for (int i = 0; i < liczbaZadan; ++i) {
    if (zadania[i].funkcja == historiaZapiszProbke) {
      historySlot = i;
      break;
    }
  }
  if (historySlot < 0) {
    why = "historiaZapiszProbke=NOT_REGISTERED";
    return false;
  }

  // Test-only: przyspieszamy pierwszy normalny tick historii. Nie wywolujemy
  // buildera bezposrednio z workera Final-Mega; scheduler nadal wykonuje
  // historiaZapiszProbke() w swoim normalnym kontekscie.
  const unsigned long nowMs = millis();
  zadania[historySlot].aktywne = true;
  zadania[historySlot].ostatnieWywolanie = nowMs - zadania[historySlot].interwalMs;

  Serial.println(F("tag=FINAL-MEGA lvl=INFO zdarzenie=telemetry_prime scheduler_due=YES"));
  const unsigned long startMs = millis();
  while (millis() - startMs < 10000UL) {
    serwisujTWDTJesliZarejestrowany();
    if (g_telemetryLastSnapshot.sampleSeq != 0U && g_telemetryLastSnapshot.sessionNonce != 0ULL) {
      why = "telemetrySnapshot=PRIMED_BY_NORMAL_SCHEDULER sampleSeq=" +
            String((unsigned long)g_telemetryLastSnapshot.sampleSeq) +
            " sessionNonce=READY";
      return true;
    }
    vTaskDelay(pdMS_TO_TICKS(50));
  }

  why = "telemetrySnapshot=TIMEOUT_AFTER_10S sampleSeq=" +
        String((unsigned long)g_telemetryLastSnapshot.sampleSeq);
  return false;
}

static bool finalMegaR380R400RunBatch(String &resultOut) {
  resultOut = "";
  bool allOk = true;

  auto add = [&](const String &line) {
    if (resultOut.length()) resultOut += "\n";
    resultOut += line;
  };
  auto runGate = [&](uint16_t gate, const char* label, bool (*fn)(String&)) {
    serwisujTWDTJesliZarejestrowany();
    String detail;
    const bool pass = fn(detail);
    add(String("R") + String((unsigned)gate) + ":" +
        (pass ? F("PASS " ) : F("FAIL ")) + String(label));
    // Na PASS wysylamy tylko zwięzły summary, aby zmiescic caly mega-batch
    // w jednym komunikacie Telegram. Przy FAIL dolaczamy szczegoly wlasciwego
    // gate'a, zeby od razu bylo wiadomo, ktory test wymaga poprawki.
    if (!pass && detail.length()) add(detail);
    allOk = allOk && pass;
    serwisujTWDTJesliZarejestrowany();
    vTaskDelay(pdMS_TO_TICKS(20));
  };

  // Clean-start gates. We intentionally reject an overlapping Firebase worker
  // because parallel RTDB/TG work was the source of the earlier crash investigation.
  if (!littlefsReady) { add(F("R380:FAIL littlefs=NOT_READY")); return false; }
  add(F("R380:PASS littlefs=READY"));
  if (!g_telemetryRing.ready()) { add(F("R381:FAIL telemetryRing=NOT_READY")); return false; }
  add(F("R381:PASS telemetryRing=READY"));

  const unsigned long pollWaitStart = millis();
  while (g_tgPollInFlight && millis() - pollWaitStart < 35000UL) {
    serwisujTWDTJesliZarejestrowany();
    vTaskDelay(pdMS_TO_TICKS(50));
  }
  if (g_tgPollInFlight) { add(F("R382:FAIL tgPollStillInFlight")); return false; }
  add(F("R382:PASS tgPoll=IDLE"));

  const unsigned long fbWaitStart = millis();
  while ((fbLoopWorkerZajety() || g_telemetryRequestActive || g_telemetryCompletionPending) &&
         millis() - fbWaitStart < 30000UL) {
    serwisujTWDTJesliZarejestrowany();
    vTaskDelay(pdMS_TO_TICKS(50));
  }
  if (fbLoopWorkerZajety()) { add(F("R383:FAIL firebaseWorker=BUSY")); return false; }
  add(F("R383:PASS firebaseWorker=IDLE"));
  if (g_telemetryRequestActive || g_telemetryCompletionPending) {
    add(F("R384:FAIL telemetryRequest=ACTIVE")); return false;
  }
  add(F("R384:PASS telemetryRequest=IDLE"));

  runGate(385, "spoolCore=R253-R262", spoolR253R262RunBatch);
  runGate(386, "spoolSemantics=R263-R272", spoolR263R272RunBatch);

  String primeWhy;
  const bool primeOk = finalMegaEnsureRealTelemetrySnapshot(primeWhy);
  add(String(F("FINAL-MEGA:telemetryPrime:")) + (primeOk ? F("PASS ") : F("FAIL ")) + primeWhy);
  allOk = allOk && primeOk;

  runGate(387, "telemetryProducer=R273-R282", spoolR273R282RunBatch);
  runGate(388, "replayAckDelete=R301-R312", spoolR301R312RunReplayBatch);
  runGate(389, "faultRecoveryQuota=R313-R324", spoolR313R324RunFaultBatch);
  runGate(390, "commitG=R325-R334", spoolR325R334RunCommitGBatch);
  runGate(391, "securityH1=R335-R344", securityH1R335R344RunBatch);
  runGate(392, "securityH2=R345-R356", securityH2R345R356RunBatch);
  runGate(393, "rtdbIntegration=R367-R379", rtdbIntegrationR367R379RunBatch);

  // Final health sentinels after all gates. These do not invent policy; they
  // simply prove the runtime returned to an idle, connected state.
  const bool wifiOk = (WiFi.status() == WL_CONNECTED);
  add(String(F("R394:")) + (wifiOk ? F("PASS WiFi=CONNECTED") : F("FAIL WiFi=DISCONNECTED")));
  allOk = allOk && wifiOk;

  const bool authOk = fbAppReady && fbApp.ready();
  add(String(F("R395:")) + (authOk ? F("PASS firebaseAuth=READY") : F("FAIL firebaseAuth=NOT_READY")));
  allOk = allOk && authOk;

  const bool circuitOk = !fbNetCircuitOpen;
  add(String(F("R396:")) + (circuitOk ? F("PASS firebaseCircuit=CLOSED") : F("FAIL firebaseCircuit=OPEN")));
  allOk = allOk && circuitOk;

  const bool workerIdle = !fbLoopWorkerZajety();
  add(String(F("R397:")) + (workerIdle ? F("PASS firebaseWorker=IDLE") : F("FAIL firebaseWorker=BUSY")));
  allOk = allOk && workerIdle;

  const bool telemetryIdle = !g_telemetryRequestActive && !g_telemetryCompletionPending;
  add(String(F("R398:")) + (telemetryIdle ? F("PASS telemetryRequest=IDLE") : F("FAIL telemetryRequest=ACTIVE")));
  allOk = allOk && telemetryIdle;

  String latestPath;
  uint32_t latestBoot = 0U, latestSeq = 0U;
  bool latestLegacy = false;
  size_t latestSize = 0U;
  const bool dumpOk = coredumpZnajdzNajnowszy(latestPath, latestBoot, latestSeq, latestLegacy, latestSize) && latestSeq > 0U && latestSize > 0U;
  add(String(F("R399:")) + (dumpOk ? F("PASS latestCoredump=AVAILABLE") : F("FAIL latestCoredump=MISSING")));
  allOk = allOk && dumpOk;

  add(String(F("R400:")) + (allOk ? F("PASS FINAL-MEGA overall=PASS") : F("FAIL FINAL-MEGA overall=FAIL")));
  return allOk;
}

