// ============================================================================
// [R401-R430 LOCAL] STABILITY-MEGA
// Cel: repeatability under back-to-back execution, bez celowego resetu/crash.
// Cztery glówne gate'y spool sa wykonywane ponownie, H1/H2 i RTDB po 2-3x,
// a po kazdym kroku sprawdzany jest brak pozostawionego workera/requestu.
// Ostatni coredump jest tylko odczytywany: batch NIE generuje crasha.
// Produkcja pozostaje v3.19.2.
// ============================================================================
static bool stabilityMegaHealthSentinel(const char* tag, String &detail) {
  const bool wifi = (WiFi.status() == WL_CONNECTED);
  const bool auth = fbAppReady && fbApp.ready();
  const bool worker = !fbLoopWorkerZajety();
  const bool req = !g_telemetryRequestActive && !g_telemetryCompletionPending;
  if (!wifi || !auth || !worker || !req) {
    detail = String(tag) + ":wifi=" + (wifi ? "CONNECTED" : "DOWN") +
             " auth=" + (auth ? "READY" : "NOT_READY") +
             " worker=" + (worker ? "IDLE" : "BUSY") +
             " telemetryRequest=" + (req ? "IDLE" : "ACTIVE");
    return false;
  }
  detail = String(tag) + ":wifi=CONNECTED auth=READY worker=IDLE telemetryRequest=IDLE";
  return true;
}

static bool stabilityMegaR401R430RunBatch(String &resultOut) {
  resultOut = "";
  bool allOk = true;
  auto add = [&](const String &line) {
    if (resultOut.length()) resultOut += "\n";
    resultOut += line;
  };
  auto gateBool = [&](uint16_t r, const char* label, bool pass, const String &detail = String()) {
    add(String("R") + String((unsigned)r) + ":" + (pass ? "PASS " : "FAIL ") + label);
    if (!pass && detail.length()) add(detail);
    allOk = allOk && pass;
    serwisujTWDTJesliZarejestrowany();
    vTaskDelay(pdMS_TO_TICKS(20));
  };
  auto waitForSharedWorkersIdle = [&](uint16_t r) -> bool {
    const unsigned long startMs = millis();
    while ((millis() - startMs) < 12000UL) {
      const bool busy = fbLoopWorkerZajety() || g_telemetryRequestActive ||
                        g_telemetryCompletionPending || g_securityH2TaskRunning ||
                        g_rtdbIntegrationActive;
      if (!busy) return true;
      serwisujTWDTJesliZarejestrowany();
      vTaskDelay(pdMS_TO_TICKS(50));
    }
    add(String("STABILITY-MEGA: settle timeout before R") + String((unsigned)r));
    return false;
  };
  auto runGate = [&](uint16_t r, const char* label, bool (*fn)(String&)) {
    if (!waitForSharedWorkersIdle(r)) {
      gateBool(r, label, false, "shared worker did not settle before gate");
      return;
    }
    String d;
    bool p = fn(d);
    gateBool(r, label, p, d);
  };

  if (!littlefsReady) { add("R401:FAIL littlefs=NOT_READY"); return false; }
  gateBool(401, "littlefs=READY", true);
  gateBool(402, "telemetryRing=READY", g_telemetryRing.ready());
  gateBool(403, "WiFi=CONNECTED", WiFi.status() == WL_CONNECTED);
  gateBool(404, "firebaseAuth=READY", fbAppReady && fbApp.ready());
  gateBool(405, "firebaseWorker=IDLE", !fbLoopWorkerZajety());
  gateBool(406, "telemetryRequest=IDLE", !g_telemetryRequestActive && !g_telemetryCompletionPending);

  String prime;
  bool primeOk = finalMegaEnsureRealTelemetrySnapshot(prime);
  gateBool(407, "telemetryProducer=REAL_SNAPSHOT", primeOk, prime);

  // Repeat the proven producer/replay/fault/Commit-G gates twice. This checks
  // cleanup/idempotence and allocator/reopen behavior across immediate repeats.
  runGate(408, "producerRound1=R273-R282", spoolR273R282RunBatch);
  runGate(409, "producerRound2=R273-R282", spoolR273R282RunBatch);
  runGate(410, "replayRound1=R301-R312", spoolR301R312RunReplayBatch);
  runGate(411, "replayRound2=R301-R312", spoolR301R312RunReplayBatch);
  runGate(412, "faultRound1=R313-R324", spoolR313R324RunFaultBatch);
  runGate(413, "faultRound2=R313-R324", spoolR313R324RunFaultBatch);
  runGate(414, "commitGRound1=R325-R334", spoolR325R334RunCommitGBatch);
  runGate(415, "commitGRound2=R325-R334", spoolR325R334RunCommitGBatch);

  runGate(416, "securityH1Round1=R335-R344", securityH1R335R344RunBatch);
  runGate(417, "securityH1Round2=R335-R344", securityH1R335R344RunBatch);
  runGate(418, "securityH2Round1=R345-R356", securityH2R345R356RunBatch);
  runGate(419, "securityH2Round2=R345-R356", securityH2R345R356RunBatch);

  // RTDB gets three fresh run nonces internally, so retries cannot alias old
  // nodes. This is intentionally a live Firebase test, not an offline mock.
  runGate(420, "rtdbRound1=R367-R379", rtdbIntegrationR367R379RunBatch);
  runGate(421, "rtdbRound2=R367-R379", rtdbIntegrationR367R379RunBatch);
  runGate(422, "rtdbRound3=R367-R379", rtdbIntegrationR367R379RunBatch);

  String h;
  gateBool(423, "postRoundHealth=OK", stabilityMegaHealthSentinel("postRoundHealth", h), h);

  // No crash is induced here. We only prove that the existing coredump store
  // is readable and still has the latest archived sequence/size.
  String dumpPath;
  uint32_t dumpBoot = 0U, dumpSeq = 0U;
  bool dumpLegacy = false;
  size_t dumpSize = 0U;
  bool dumpOk = coredumpZnajdzNajnowszy(dumpPath, dumpBoot, dumpSeq, dumpLegacy, dumpSize) &&
                dumpSeq > 0U && dumpSize > 0U;
  gateBool(424, "coredumpArchive=READABLE", dumpOk,
           String("coredumpSeq=") + String((unsigned long)dumpSeq) +
           " boot=" + String((unsigned long)dumpBoot) +
           " size=" + String((unsigned long)dumpSize));

  // Memory sentinels use conservative floors observed on the test board;
  // they are tripwires, not claims about production capacity.
  uint32_t freeHeap = ESP.getFreeHeap();
  uint32_t largest8 = heap_caps_get_largest_free_block(MALLOC_CAP_8BIT);
  gateBool(425, "heapFloor=PASS", freeHeap >= 45000U,
           String("freeHeap=") + String((unsigned long)freeHeap));
  gateBool(426, "largest8Floor=PASS", largest8 >= 32768U,
           String("largest8=") + String((unsigned long)largest8));

  gateBool(427, "firebaseCircuit=CLOSED", !fbNetCircuitOpen);
  gateBool(428, "tgPoll=IDLE", !g_tgPollInFlight);
  gateBool(429, "workersAndRequests=IDLE",
           !fbLoopWorkerZajety() && !g_telemetryRequestActive && !g_telemetryCompletionPending,
           "worker=" + String(fbLoopWorkerZajety() ? "BUSY" : "IDLE") +
           " telemetryRequest=" + String((g_telemetryRequestActive || g_telemetryCompletionPending) ? "ACTIVE" : "IDLE"));
  gateBool(430, "STABILITY-MEGA overall=PASS", allOk);
  return allOk;
}

static void stabilityMegaTaskFn(void * /*pvParams*/) {
  Serial.println(F("tag=STABILITY-MEGA lvl=INFO zdarzenie=worker_start"));
  String wynik;
  const bool pass = stabilityMegaR401R430RunBatch(wynik);
  Serial.printf("tag=STABILITY-MEGA lvl=INFO zdarzenie=worker_done pass=%u resultLen=%u\n",
                pass ? 1U : 0U, (unsigned)wynik.length());
  sendTelegramMessage(String("R401-R430 stability mega batch: ") +
                      (pass ? F("PASS\n") : F("FAIL\n")) + wynik);
  g_stabilityMegaActive = false;
  g_stabilityMegaTaskHandle = nullptr;
  vTaskDelete(nullptr);
}

static bool stabilityMegaLaunchTask() {
  if (g_stabilityMegaActive || g_finalMegaActive) return false;
  if (fbLoopWorkerZajety() || g_telemetryRequestActive || g_telemetryCompletionPending ||
      g_spoolRuntimeArmed || g_securityH2TaskRunning || g_rtdbIntegrationActive) {
    return false;
  }
  g_stabilityMegaActive = true;
  BaseType_t created = xTaskCreatePinnedToCore(
      stabilityMegaTaskFn, "stabilityMega", 16384, nullptr, 1,
      &g_stabilityMegaTaskHandle, 0);
  if (created != pdPASS) {
    g_stabilityMegaActive = false;
    g_stabilityMegaTaskHandle = nullptr;
    return false;
  }
  return true;
}

// ============================================================================
// [R431-R470 LOCAL] RECOVERY / OTA / FS / BOOT MEGA
// Cel: duzy, niemutujacy test warstwy recovery i OTA. Nie wykonuje flashowania,
// nie wymusza rebootu i nie zmienia produkcyjnej sciezki V1. Tymczasowy plik
// LittleFS jest tworzony i usuwany w tym samym przebiegu.
// ============================================================================
static bool recoveryOtaMegaEnsureRealTelemetrySnapshot(String &why) {
  if (g_telemetryLastSnapshot.sampleSeq != 0U && g_telemetryLastSnapshot.sessionNonce != 0ULL) {
    why = "telemetrySnapshot=ALREADY_PRESENT sampleSeq=" +
          String((unsigned long)g_telemetryLastSnapshot.sampleSeq) +
          " sessionNonce=READY";
    return true;
  }

  int historySlot = -1;
  for (int i = 0; i < liczbaZadan; ++i) {
    if (zadania[i].funkcja == historiaZapiszProbke) {
      historySlot = i;
      break;
    }
  }
  if (historySlot < 0) {
    why = "historiaZapiszProbke=NOT_REGISTERED";
    return false;
  }

  // Test-only: przyspieszamy pierwszy normalny tick historii. Nie wywolujemy
  // buildera bezposrednio z workera; scheduler nadal wykonuje
  // historiaZapiszProbke() w swoim normalnym kontekscie.
  const unsigned long nowMs = millis();
  zadania[historySlot].aktywne = true;
  zadania[historySlot].ostatnieWywolanie = nowMs - zadania[historySlot].interwalMs;

  Serial.println(F("tag=RECOVERY-OTA-MEGA lvl=INFO zdarzenie=telemetry_prime scheduler_due=YES"));
  const unsigned long startMs = millis();
  while (millis() - startMs < 10000UL) {
    serwisujTWDTJesliZarejestrowany();
    if (g_telemetryLastSnapshot.sampleSeq != 0U && g_telemetryLastSnapshot.sessionNonce != 0ULL) {
      why = "telemetrySnapshot=PRIMED_BY_NORMAL_SCHEDULER sampleSeq=" +
            String((unsigned long)g_telemetryLastSnapshot.sampleSeq) +
            " sessionNonce=READY";
      return true;
    }
    vTaskDelay(pdMS_TO_TICKS(50));
  }

  why = "telemetrySnapshot=TIMEOUT_AFTER_10S sampleSeq=" +
        String((unsigned long)g_telemetryLastSnapshot.sampleSeq);
  return false;
}

static bool recoveryOtaMegaTempFsTest(String &detail) {
  const char *path = "/recoverymega_probe.tmp";
  LittleFS.remove(path);
  File f = LittleFS.open(path, "w");
  if (!f) { detail = "open_write=FAIL"; return false; }
  const uint8_t payload[] = { 'R','4','3','1','-','4','7','0', 0x00, 0x5A, 0xA5 };
  size_t n = f.write(payload, sizeof(payload));
  f.flush();
  f.close();
  if (n != sizeof(payload)) { LittleFS.remove(path); detail = "write=FAIL"; return false; }
  f = LittleFS.open(path, "r");
  if (!f) { LittleFS.remove(path); detail = "open_read=FAIL"; return false; }
  uint8_t got[sizeof(payload)] = {};
  size_t rn = f.read(got, sizeof(got));
  f.close();
  const bool exact = rn == sizeof(payload) && memcmp(got, payload, sizeof(payload)) == 0;
  const bool removed = LittleFS.remove(path);
  detail = String("write_read_exact=") + (exact ? "YES" : "NO") +
           " removed=" + (removed ? "YES" : "NO");
  return exact && removed;
}

static bool recoveryOtaMegaR431R470RunBatch(String &resultOut) {
  resultOut = "";
  bool allOk = true;
  auto add = [&](const String &line) {
    if (resultOut.length()) resultOut += "\n";
    resultOut += line;
  };
  auto gateBool = [&](uint16_t r, const char* label, bool pass, const String &detail = String()) {
    add(String("R") + String((unsigned)r) + ":" + (pass ? "PASS " : "FAIL ") + label);
    if (!pass && detail.length()) add(detail);
    allOk = allOk && pass;
    serwisujTWDTJesliZarejestrowany();
    vTaskDelay(pdMS_TO_TICKS(20));
  };
  auto gateNoMutate = [&](uint16_t r, const char* label, bool pass, const String &detail = String()) {
    gateBool(r, label, pass, detail);
  };

  gateNoMutate(431, "version=NON_EMPTY", FIRMWARE_VERSION && String(FIRMWARE_VERSION).length() > 0,
               String("version=") + String(FIRMWARE_VERSION ? FIRMWARE_VERSION : "NULL"));
  gateNoMutate(432, "littlefs=READY", littlefsReady);
  String fsd;
  gateNoMutate(433, "littlefsTempWriteReadDelete=PASS", littlefsReady && recoveryOtaMegaTempFsTest(fsd), fsd);

  FsQuotaHard q{};
  bool qok = fsQuotaHardEvaluate(q) && q.valid && q.protectedReserveBytes > 0U;
  gateNoMutate(434, "quotaHardSnapshot=VALID", qok,
               String("valid=") + (q.valid ? "YES" : "NO") +
               " free=" + String((unsigned long)q.freeBytes) +
               " protected=" + String((unsigned long)q.protectedReserveBytes) +
               " quota=" + String((unsigned long)q.availableQuotaBytes));

  FsQuotaDynamic qd{};
  bool qdok = fsQuotaDynamicEvaluate(qd) && qd.valid;
  gateNoMutate(435, "quotaDynamicSnapshot=VALID", qdok,
               String("valid=") + (qd.valid ? "YES" : "NO") +
               " free=" + String((unsigned long)qd.freeBytes));

  String dumpPath;
  uint32_t dumpBoot = 0U, dumpSeq = 0U;
  bool dumpLegacy = false;
  size_t dumpSize = 0U;
  bool dump = coredumpZnajdzNajnowszy(dumpPath, dumpBoot, dumpSeq, dumpLegacy, dumpSize);
  gateNoMutate(436, "coredumpLatest=DISCOVERABLE", dump && dumpSeq > 0U && dumpSize > 0U,
               String("path=") + dumpPath + " seq=" + String((unsigned long)dumpSeq) +
               " boot=" + String((unsigned long)dumpBoot) + " size=" + String((unsigned long)dumpSize));
  bool dumpFile = dump && LittleFS.exists(dumpPath);
  gateNoMutate(437, "coredumpFile=EXISTS", dumpFile);
  gateNoMutate(438, "coredumpSize=NONZERO", dumpSize > 0U);

  const esp_partition_t *run = esp_ota_get_running_partition();
  const esp_partition_t *boot = esp_ota_get_boot_partition();
  gateNoMutate(439, "otaRunningPartition=PRESENT", run != nullptr,
               String("label=") + (run ? run->label : "NULL"));
  gateNoMutate(440, "otaBootPartition=PRESENT", boot != nullptr,
               String("label=") + (boot ? boot->label : "NULL"));
  gateNoMutate(441, "otaRunningMatchesBoot=CONSISTENT", run && boot && run->address == boot->address,
               String("running=0x") + String(run ? run->address : 0, HEX) +
               " boot=0x" + String(boot ? boot->address : 0, HEX));

  esp_ota_img_states_t otaState = ESP_OTA_IMG_UNDEFINED;
  esp_err_t otaStateRc = run ? esp_ota_get_state_partition(run, &otaState) : ESP_FAIL;
  const bool otaStateAccepted = (otaStateRc == ESP_OK) || (otaStateRc == ESP_ERR_NOT_FOUND) || (otaStateRc == ESP_ERR_INVALID_STATE);
  gateNoMutate(442, "otaStateQuery=SAFE", otaStateAccepted,
               String("rc=") + String((int)otaStateRc) + " state=" + String((int)otaState));
  gateNoMutate(443, "verifyRollbackLater=OVERRIDE_ACTIVE", verifyRollbackLater() == true);

  gateNoMutate(444, "bootCounter=NONZERO", logBootCounter > 0U,
               String("boot=") + String((unsigned long)logBootCounter));
  gateNoMutate(445, "rtcDiagMagic=VALID", diagStanPoprawny(rtcCrashDiag));
  gateNoMutate(446, "crashQueue=VALID", crashQueuePoprawna(rtcCrashReportQueue));

  gateNoMutate(447, "recoveryMega=NO_FLASH_OPERATION", true);
  gateNoMutate(448, "recoveryMega=NO_REBOOT_REQUEST", true);
  gateNoMutate(449, "finalMega=IDLE", !g_finalMegaActive);
  gateNoMutate(450, "stabilityMega=IDLE", !g_stabilityMegaActive);

  String health;
  bool healthOk = (WiFi.status() == WL_CONNECTED) && fbAppReady && fbApp.ready() &&
                  !fbLoopWorkerZajety() && !g_telemetryRequestActive && !g_telemetryCompletionPending &&
                  !g_tgPollInFlight;
  gateNoMutate(451, "runtimeHealth=IDLE", healthOk, health);
  gateNoMutate(452, "firebaseAuth=READY", fbAppReady && fbApp.ready());
  gateNoMutate(453, "firebaseWorker=IDLE", !fbLoopWorkerZajety());
  gateNoMutate(454, "telemetryRequest=IDLE", !g_telemetryRequestActive && !g_telemetryCompletionPending);
  gateNoMutate(455, "tgPoll=IDLE", !g_tgPollInFlight);
  gateNoMutate(456, "firebaseCircuit=CLOSED", !fbNetCircuitOpen);

  const uint32_t freeHeap = ESP.getFreeHeap();
  const uint32_t largest8 = heap_caps_get_largest_free_block(MALLOC_CAP_8BIT);
  gateNoMutate(457, "heap=NONTRIVIAL", freeHeap >= 40000U,
               String("freeHeap=") + String((unsigned long)freeHeap));
  gateNoMutate(458, "largest8=NONTRIVIAL", largest8 >= 32768U,
               String("largest8=") + String((unsigned long)largest8));
  gateNoMutate(459, "telemetryRing=READY", g_telemetryRing.ready());
  gateNoMutate(460, "spoolQuotaProtected=POSITIVE", q.protectedReserveBytes > 0U);

  String primeWhy;
  const bool primeOk = recoveryOtaMegaEnsureRealTelemetrySnapshot(primeWhy);
  add(String(F("RECOVERY-OTA-MEGA:telemetryPrime:")) + (primeOk ? F("PASS ") : F("FAIL ")) + primeWhy);
  allOk = allOk && primeOk;

  // After priming, allow any normal producer-side Firebase activity to settle
  // before replay/fault/Commit-G regressions start.
  const unsigned long settleStartMs = millis();
  while ((fbLoopWorkerZajety() || g_telemetryRequestActive || g_telemetryCompletionPending) &&
         millis() - settleStartMs < 15000UL) {
    serwisujTWDTJesliZarejestrowany();
    vTaskDelay(pdMS_TO_TICKS(50));
  }

  // Final broad regression sweep: no new fault injection, reuse proven live gates.
  String sub;
  const bool s1 = spoolR273R282RunBatch(sub);
  gateNoMutate(461, "producerRegression=PASS", s1, sub);
  const bool s2 = spoolR301R312RunReplayBatch(sub);
  gateNoMutate(462, "replayRegression=PASS", s2, sub);
  const bool s3 = spoolR313R324RunFaultBatch(sub);
  gateNoMutate(463, "faultRegression=PASS", s3, sub);
  const bool s4 = spoolR325R334RunCommitGBatch(sub);
  gateNoMutate(464, "commitGRegression=PASS", s4, sub);
  const bool s5 = securityH1R335R344RunBatch(sub);
  gateNoMutate(465, "securityH1Regression=PASS", s5, sub);
  const bool s6 = securityH2R345R356RunBatch(sub);
  gateNoMutate(466, "securityH2Regression=PASS", s6, sub);
  const bool s7 = rtdbIntegrationR367R379RunBatch(sub);
  gateNoMutate(467, "rtdbRegression=PASS", s7, sub);

  gateNoMutate(468, "postRegressionWorker=IDLE", !fbLoopWorkerZajety());
  gateNoMutate(469, "postRegressionTelemetryRequest=IDLE", !g_telemetryRequestActive && !g_telemetryCompletionPending);
  gateNoMutate(470, "RECOVERY-OTA-MEGA overall=PASS", allOk);
  return allOk;
}

