// [R367-R379 LOCAL] RTDB INTEGRATION MEGA BATCH
// Jeden duzy pakiet zywego testu Firebase RTDB na lokalnej plytce testowej.
// Wszystkie zapisy testowe ida pod /piec/_rtdb_test/<run>/ i sa usuwane
// na koncu. Nie zmienia normalnej sciezki V1 ani Rules produkcyjnych.
// ============================================================================
static uint32_t rtdbTestCountToken(const String &payload, const char *token) {
  if (!token || !*token) return 0U;
  uint32_t n = 0U;
  int pos = 0;
  while (true) {
    const int hit = payload.indexOf(token, pos);
    if (hit < 0) break;
    ++n;
    pos = hit + (int)strlen(token);
  }
  return n;
}

// [R367-R379 TIMEOUT BOUNDARY] Jedno okno dla lokalnych operacji RTDB.
// 12 s zostawia margines ponad 8 s socket timeout + 4 s handshake timeout.
static const uint32_t RTDB_TEST_OP_TIMEOUT_MS = 12000UL;

static bool rtdbTestResultOk(AsyncResult &r) {
  return r.isResult() && !r.isError();
}

static bool rtdbTestSet(const String &path, const String &json, String &payloadOut, String &errorOut) {
  payloadOut = "";
  errorOut = "";
  if (fbLoopWorkerZajety()) { errorOut = "workerBusy"; return false; }
  // Re-arm przed kazda proba: stop() po bledzie czysci timeout handshake.
  fbSSLClient.setTimeout(4);
  fbSSLClient.setHandshakeTimeout(4000);
  static AsyncResult r;
  r = AsyncResult{};
  object_t data(json.c_str());
  fbDatabase.set<object_t>(fbAsyncClient, path, data, r);
  fbCzekajNaWynikZLimitem(r, RTDB_TEST_OP_TIMEOUT_MS);
  if (!rtdbTestResultOk(r)) {
    errorOut = r.isError() ? r.error().message() : "TIMEOUT";
    fbFirebaseSocketStopSafe();
    return false;
  }
  payloadOut = r.c_str();
  FB_NET_SUCCESS();
  return true;
}

